--
-- Name: accept_team_invite(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_team_invite(p_token text, p_profile_id uuid, p_confirm_mismatch boolean DEFAULT false) RETURNS TABLE(invite_id uuid, team_id uuid, team_slug text, invite_email text, invite_role text, email_match boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_invite public.team_invites%rowtype;
  v_profile_email text;
  v_team_slug text;
begin
  if p_token is null or btrim(p_token) = '' then
    raise exception using errcode = 'P0002', message = 'invite_not_found';
  end if;

  select candidate.*
  into v_invite
  from public.team_invites as candidate
  where candidate.token = p_token
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'invite_not_found';
  end if;
  if v_invite.accepted_at is not null then
    raise exception using errcode = 'P0001', message = 'already_accepted';
  end if;
  if v_invite.expires_at < clock_timestamp() then
    raise exception using errcode = 'P0001', message = 'expired';
  end if;

  select profile.email
  into v_profile_email
  from public.profiles as profile
  where profile.id = p_profile_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'profile_not_found';
  end if;

  email_match :=
    v_profile_email is not null
    and lower(v_profile_email) = lower(v_invite.email);
  if not email_match and not coalesce(p_confirm_mismatch, false) then
    raise exception using errcode = 'P0001', message = 'mismatch_unconfirmed';
  end if;

  insert into public.team_members (
    team_id,
    user_id,
    role,
    invited_by_user_id
  ) values (
    v_invite.team_id,
    p_profile_id,
    v_invite.role,
    v_invite.invited_by_user_id
  )
  on conflict on constraint team_members_pkey do nothing;

  update public.team_invites as claimed
  set accepted_at = clock_timestamp()
  where claimed.id = v_invite.id;

  select team_record.slug
  into v_team_slug
  from public.teams as team_record
  where team_record.id = v_invite.team_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'team_not_found';
  end if;

  invite_id := v_invite.id;
  team_id := v_invite.team_id;
  team_slug := v_team_slug;
  invite_email := v_invite.email;
  invite_role := v_invite.role;
  return next;
end;
$$;


--
-- Name: accrue_sandbox_billing_session(uuid, timestamp with time zone, boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_sandbox_billing_session(p_session uuid, p_through timestamp with time zone, p_final boolean DEFAULT false, p_close_generation bigint DEFAULT NULL::bigint) RETURNS TABLE(accrued boolean, debited_cents bigint, metered_through_at timestamp with time zone, session_state text)
    LANGUAGE plpgsql
    AS $$
declare
  v_session public.sandbox_billing_sessions%rowtype;
  v_target timestamptz;
  v_delta_ms bigint;
  v_delta_units bigint;
  v_remainder_units bigint;
  v_total_units bigint;
  v_debit_cents bigint;
  v_next_seq bigint;
  v_debit_posted boolean;
begin
  if p_through is null then
    raise exception 'sandbox billing accrual time is required';
  end if;

  select * into v_session
  from public.sandbox_billing_sessions
  where id = p_session
  for update;
  if not found then
    raise exception 'sandbox billing session % not found', p_session;
  end if;

  if v_session.state in ('closed', 'closed_unmetered') then
    return query select false, 0::bigint, v_session.metered_through_at,
      v_session.state;
    return;
  end if;

  if not p_final and v_session.state <> 'open' then
    return query select false, 0::bigint, v_session.metered_through_at,
      v_session.state;
    return;
  end if;

  if p_final and (
    v_session.state <> 'closing'
    or p_close_generation is null
    or v_session.close_generation <> p_close_generation
  ) then
    return query select false, 0::bigint, v_session.metered_through_at,
      v_session.state;
    return;
  end if;

  v_target := greatest(
    p_through,
    v_session.started_at,
    v_session.metered_through_at
  );
  if p_final then
    v_target := greatest(v_target, v_session.started_at + interval '1 minute');
  end if;

  v_delta_ms := floor(
    extract(epoch from (v_target - v_session.metered_through_at)) * 1000
  )::bigint;
  if v_delta_ms = 0 and not p_final then
    return query select false, 0::bigint, v_session.metered_through_at,
      v_session.state;
    return;
  end if;

  v_delta_units := v_delta_ms * v_session.rate_micro_usd_per_minute;
  v_next_seq := v_session.accrual_seq + 1;

  select sandbox_usage_remainder_units into v_remainder_units
  from public.billing_accounts
  where id = v_session.account_id
  for update;
  if not found then
    raise exception 'billing account % not found', v_session.account_id;
  end if;

  v_total_units := v_remainder_units + v_delta_units;
  v_debit_cents := v_total_units / 600000000;
  v_remainder_units := v_total_units % 600000000;

  update public.billing_accounts
  set sandbox_usage_remainder_units = v_remainder_units,
      updated_at = now()
  where id = v_session.account_id;

  if v_debit_cents > 0 then
    select posted into v_debit_posted
    from public.post_billing_usage_debit(
      v_session.account_id,
      v_debit_cents,
      'usage_sandbox',
      'sbx:' || v_session.vercel_session_id || ':a:' || v_next_seq,
      to_char(v_target at time zone 'UTC', 'YYYY-MM'),
      jsonb_build_object(
        'sandbox_record_id', v_session.sandbox_record_id,
        'vercel_sandbox_id', v_session.vercel_sandbox_id,
        'vercel_session_id', v_session.vercel_session_id,
        'actor_user_id', v_session.actor_user_id,
        'product_team_id', v_session.product_team_id,
        'rate_micro_usd_per_minute', v_session.rate_micro_usd_per_minute,
        'accrual_seq', v_next_seq,
        'accrued_ms', v_delta_ms
      )
    );
    if not coalesce(v_debit_posted, false) then
      raise exception 'sandbox billing debit source collision for session %',
        v_session.vercel_session_id;
    end if;
  end if;

  update public.sandbox_billing_sessions
  set metered_through_at = v_target,
      usage_units = usage_units + v_delta_units,
      billed_cents = billed_cents + v_debit_cents,
      accrual_seq = v_next_seq,
      state = case when p_final then 'closed' else state end,
      ended_at = case when p_final then v_target else ended_at end,
      updated_at = now()
  where id = p_session;

  return query select (v_delta_ms > 0 or p_final), v_debit_cents, v_target,
    case when p_final then 'closed'::text else v_session.state end;
end;
$$;


--
-- Name: accrue_token_usage(uuid, bigint, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_token_usage(p_account uuid, p_cost_units bigint, p_source_ref text, p_period text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(posted boolean, debited_cents bigint, remainder_cost_units bigint)
    LANGUAGE plpgsql
    AS $$
declare
  v_existing public.token_usage_accruals%rowtype;
  v_remainder bigint;
  v_total_units bigint;
  v_debit_cents bigint;
  v_debit_posted boolean;
  v_existing_debit_rows bigint;
  v_existing_debit_cents bigint;
  v_existing_debit_valid boolean;
  v_legacy_expected_cents bigint;
  v_recovery_debit_cents bigint;
  v_recovery_debit_posted boolean;
begin
  if p_cost_units is null or p_cost_units <= 0 then
    raise exception 'token usage cost must be positive, got %', p_cost_units;
  end if;
  if nullif(trim(p_source_ref), '') is null then
    raise exception 'token usage source reference is required';
  end if;
  if nullif(trim(p_period), '') is null then
    raise exception 'token usage period is required';
  end if;

  select token_usage_remainder_cost_units into v_remainder
  from public.billing_accounts
  where id = p_account
  for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;

  select * into v_existing
  from public.token_usage_accruals
  where source_ref = trim(p_source_ref);
  if found then
    -- Gateway costs are final once reported. A retry may repeat that value but
    -- must never rewrite a previously accrued call with a different identity.
    if v_existing.account_id <> p_account
      or v_existing.cost_units <> p_cost_units
      or v_existing.period <> trim(p_period)
    then
      raise exception 'token usage source % identity mismatch', p_source_ref;
    end if;
    return query select false, v_existing.debited_cents, v_remainder;
    return;
  end if;

  v_total_units := v_remainder + p_cost_units;
  select count(*),
         coalesce(-sum(delta_cents), 0)::bigint,
         coalesce(bool_and(
           account_id = p_account
           and kind = 'usage_tokens'
           and period is not distinct from trim(p_period)
           and delta_cents < 0
         ), false)
    into v_existing_debit_rows,
         v_existing_debit_cents,
         v_existing_debit_valid
  from public.credit_ledger
  where source_ref in (
    trim(p_source_ref) || ':inc',
    trim(p_source_ref) || ':pur'
  );

  if v_existing_debit_rows > 0 then
    -- The previous metering path rounded each call to cents and wrote the
    -- same ledger source before this exact-accrual row existed. Recover only
    -- that verified crash window, then carry its rounding difference into
    -- the exact remainder instead of charging the call twice.
    v_legacy_expected_cents := (p_cost_units + 500000) / 1000000;
    if not v_existing_debit_valid
      or v_existing_debit_cents <> v_legacy_expected_cents
    then
      raise exception 'token usage source % has an incompatible ledger debit', p_source_ref;
    end if;

    v_debit_cents := v_existing_debit_cents;
    v_remainder := v_total_units - (v_existing_debit_cents * 1000000);
    if v_remainder >= 1000000 then
      v_recovery_debit_cents := v_remainder / 1000000;
      select d.posted into v_recovery_debit_posted
      from public.post_billing_usage_debit(
        p_account,
        v_recovery_debit_cents,
        'usage_tokens',
        trim(p_source_ref) || ':exact-recovery',
        trim(p_period),
        coalesce(p_metadata, '{}')
      ) d;
      if not v_recovery_debit_posted then
        raise exception 'token usage source % recovery debit already exists', p_source_ref;
      end if;
      v_debit_cents := v_debit_cents + v_recovery_debit_cents;
      v_remainder := v_remainder - (v_recovery_debit_cents * 1000000);
    end if;
  else
    -- Gateway costs use 8 decimal places in USD. One cent is 1,000,000 of
    -- those units. A negative remainder represents cents overcharged by the
    -- legacy per-call rounding path and is paid down by later exact usage.
    v_debit_cents := greatest(v_total_units / 1000000, 0);
    v_remainder := v_total_units - (v_debit_cents * 1000000);

    if v_debit_cents > 0 then
      select d.posted into v_debit_posted
      from public.post_billing_usage_debit(
        p_account,
        v_debit_cents,
        'usage_tokens',
        trim(p_source_ref),
        trim(p_period),
        coalesce(p_metadata, '{}')
      ) d;
      if not v_debit_posted then
        raise exception 'token usage source % already has a ledger debit', p_source_ref;
      end if;
    end if;
  end if;

  update public.billing_accounts
  set token_usage_remainder_cost_units = v_remainder,
      updated_at = now()
  where id = p_account;

  insert into public.token_usage_accruals (
    source_ref,
    account_id,
    cost_units,
    debited_cents,
    period,
    metadata
  ) values (
    trim(p_source_ref),
    p_account,
    p_cost_units,
    v_debit_cents,
    trim(p_period),
    coalesce(p_metadata, '{}')
  );

  return query select true, v_debit_cents, v_remainder;
end;
$$;


--
-- Name: activate_orchestration_worktree(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_orchestration_worktree(p_worktree_id uuid, p_user_id uuid, p_checkout_path text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_worktree public.orchestration_worktrees;
begin
  update public.orchestration_worktrees
  set checkout_path = p_checkout_path,
      status = 'active',
      error = null,
      archived_at = null
  where id = p_worktree_id
    and user_id = p_user_id
    and (status in ('creating', 'error') or
      (status = 'archived' and checkout_path = p_checkout_path
       and checkout_path not like '/.reserved/%'))
  returning * into v_worktree;

  if not found then
    raise exception 'worktree is not available for activation';
  end if;

  update public.orchestration_tasks
  set worktree_id = v_worktree.id,
      sandbox_id = v_worktree.sandbox_id,
      root_directory = v_worktree.checkout_path
  where id = v_worktree.task_id
    and run_id = v_worktree.run_id
    and repo_id = v_worktree.repo_id;

  if not found then
    raise exception 'worktree task is not available for binding';
  end if;

  return to_jsonb(v_worktree);
end;
$$;


--
-- Name: admit_billing_workflow_capacity(uuid, text, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admit_billing_workflow_capacity(p_account uuid, p_admission_ref text, p_source_ref text, p_lease_ref text, p_root_workflow_ref text, p_attempted_at timestamp with time zone, p_metadata jsonb) RETURNS TABLE(posted boolean, admitted boolean, would_admit boolean, active_before integer, concurrency_limit integer, accounting_mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_mode text;
  v_limit integer;
  v_active integer;
  v_would_admit boolean;
  v_admitted boolean;
  v_lease_id bigint;
  v_existing public.billing_workflow_capacity_admission_events%rowtype;
begin
  select entitlement_enforcement_mode, included_concurrency
    into v_mode, v_limit
  from public.billing_accounts
  where id = p_account
  for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;

  select * into v_existing
  from public.billing_workflow_capacity_admission_events
  where admission_ref = btrim(p_admission_ref)
    or source_ref = btrim(p_source_ref)
  order by id
  limit 1;

  if found then
    if v_existing.account_id is distinct from p_account
      or v_existing.admission_ref <> btrim(p_admission_ref)
      or v_existing.source_ref <> btrim(p_source_ref)
      or v_existing.lease_ref <> btrim(p_lease_ref)
      or v_existing.root_workflow_ref <> btrim(p_root_workflow_ref)
      or v_existing.attempted_at <> p_attempted_at
      or v_existing.metadata <> coalesce(p_metadata, '{}') then
      raise exception 'capacity admission idempotency conflict for %',
        p_admission_ref;
    end if;

    return query select false, v_existing.admitted,
      v_existing.would_admit, v_existing.active_before,
      v_existing.concurrency_limit, v_existing.accounting_mode;
    return;
  end if;

  if exists (
    select 1
    from public.billing_workflow_capacity_leases lease
    left join public.billing_workflow_capacity_release_events release
      on release.lease_id = lease.id
    where lease.account_id = p_account
      and lease.root_workflow_ref = btrim(p_root_workflow_ref)
      and release.id is null
  ) then
    raise exception 'root workflow % already has active capacity',
      p_root_workflow_ref;
  end if;

  select count(*)::integer into v_active
  from public.billing_workflow_capacity_leases lease
  left join public.billing_workflow_capacity_release_events release
    on release.lease_id = lease.id
  where lease.account_id = p_account
    and release.id is null;

  v_would_admit := v_active < v_limit;
  v_admitted := v_mode <> 'enforced' or v_would_admit;

  if v_admitted then
    insert into public.billing_workflow_capacity_leases (
      account_id,
      lease_ref,
      source_ref,
      root_workflow_ref,
      accounting_mode,
      concurrency_limit,
      active_before,
      would_admit,
      acquired_at,
      metadata
    ) values (
      p_account,
      btrim(p_lease_ref),
      'lease:' || btrim(p_source_ref),
      btrim(p_root_workflow_ref),
      v_mode,
      v_limit,
      v_active,
      v_would_admit,
      p_attempted_at,
      coalesce(p_metadata, '{}')
    ) returning id into v_lease_id;
  end if;

  insert into public.billing_workflow_capacity_admission_events (
    account_id,
    admission_ref,
    source_ref,
    lease_ref,
    root_workflow_ref,
    lease_id,
    accounting_mode,
    concurrency_limit,
    active_before,
    would_admit,
    admitted,
    attempted_at,
    metadata
  ) values (
    p_account,
    btrim(p_admission_ref),
    btrim(p_source_ref),
    btrim(p_lease_ref),
    btrim(p_root_workflow_ref),
    v_lease_id,
    v_mode,
    v_limit,
    v_active,
    v_would_admit,
    v_admitted,
    p_attempted_at,
    coalesce(p_metadata, '{}')
  );

  return query select true, v_admitted, v_would_admit, v_active, v_limit,
    v_mode;
end;
$$;


--
-- Name: agent_categories_enforce_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_categories_enforce_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  category_count int;
begin
  -- Serialize concurrent inserts for the same user so the count check is
  -- accurate under concurrency. Lock is released at transaction end.
  perform pg_advisory_xact_lock(
    hashtextextended(new.user_id::text, 5503)
  );

  select count(*) into category_count
  from public.agent_categories
  where user_id = new.user_id;

  if category_count >= 50 then
    raise exception 'Category limit reached'
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: agent_roster_summary(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_roster_summary(p_user_id uuid, p_since timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
WITH run_agents AS (
  SELECT jr.status,
         COALESCE(a.agent_id, t.agent_id) AS agent_id
  FROM job_runs jr
  LEFT JOIN assignments a ON a.id = jr.assignment_id
  LEFT JOIN repos ar ON ar.id = a.repo_id
  LEFT JOIN triggers t ON t.id = jr.trigger_id
  WHERE jr.created_at >= p_since
    AND COALESCE(ar.user_id, t.user_id) = p_user_id
    AND COALESCE(a.agent_id, t.agent_id) IS NOT NULL
),
runs AS (
  SELECT agent_id,
         COUNT(*)::bigint AS runs,
         COUNT(*) FILTER (WHERE status = 'success')::bigint AS succeeded,
         COUNT(*) FILTER (WHERE status = 'failed')::bigint AS failed,
         COUNT(*) FILTER (WHERE status = 'suppressed')::bigint AS suppressed
  FROM run_agents
  GROUP BY agent_id
),
tokens AS (
  SELECT COALESCE(a.agent_id, t.agent_id) AS agent_id,
         COALESCE(SUM(c.total_tokens), 0)::bigint AS tokens
  FROM ai_calls c
  JOIN job_runs jr ON jr.id = c.job_run_id
  LEFT JOIN assignments a ON a.id = jr.assignment_id
  LEFT JOIN triggers t ON t.id = jr.trigger_id
  WHERE c.user_id = p_user_id
    AND c.started_at >= p_since
    AND COALESCE(a.agent_id, t.agent_id) IS NOT NULL
  GROUP BY 1
)
SELECT COALESCE(
  jsonb_object_agg(
    agent_id::text,
    jsonb_build_object(
      'agentId', agent_id::text,
      'runs24h', COALESCE(r.runs, 0),
      'succeeded', COALESCE(r.succeeded, 0),
      'failed', COALESCE(r.failed, 0),
      'suppressed', COALESCE(r.suppressed, 0),
      'tokens24h', COALESCE(tk.tokens, 0)
    )
  ),
  '{}'::jsonb
)
FROM runs r
FULL OUTER JOIN tokens tk USING (agent_id);
$$;


--
-- Name: append_billing_account_event(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_billing_account_event(p_account uuid, p_event_type text, p_source_event_id text) RETURNS TABLE(sequence bigint, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_current bigint;
  v_existing bigint;
begin
  if p_event_type is null or p_event_type not in (
    'billing.summary.changed',
    'billing.capacity.change_pending',
    'billing.capacity.change_applied',
    'billing.capacity.change_failed',
    'billing.hosted_usage.added',
    'billing.account.status_changed'
  ) then
    raise exception 'billing account event type is invalid';
  end if;
  if p_source_event_id is null or btrim(p_source_event_id) = '' then
    raise exception 'billing account event source is required';
  end if;

  select billing_event_sequence into v_current
  from public.billing_accounts
  where id = p_account
  for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;

  select event.sequence into v_existing
  from public.billing_account_events event
  where event.account_id = p_account
    and event.event_type = p_event_type
    and event.source_event_id = btrim(p_source_event_id);
  if found then
    return query select v_existing, false;
    return;
  end if;

  v_current := v_current + 1;
  update public.billing_accounts
  set billing_event_sequence = v_current
  where id = p_account;

  insert into public.billing_account_events (
    account_id,
    sequence,
    event_type,
    source_event_id
  ) values (
    p_account,
    v_current,
    p_event_type,
    btrim(p_source_event_id)
  );

  return query select v_current, true;
end;
$$;


--
-- Name: apply_billing_annual_grant_schedule(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_billing_annual_grant_schedule(p_schedule uuid) RETURNS TABLE(eligible boolean, posted boolean, duplicate boolean, cancelled boolean, account_id uuid, stripe_subscription_id text, entitlement_version bigint, price_lookup_key text, included_usage_cents bigint, cycle_started_at timestamp with time zone, grant_offset smallint, grant_period text, due_at timestamp with time zone, source_event_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_schedule public.billing_annual_grant_schedules%rowtype;
  v_account public.billing_accounts%rowtype;
  v_posted boolean;
begin
  select * into v_schedule
  from public.billing_annual_grant_schedules
  where id = p_schedule;
  if not found then
    raise exception 'annual grant schedule % not found', p_schedule;
  end if;

  select * into v_account
  from public.billing_accounts
  where id = v_schedule.account_id
  for update;
  if not found then
    raise exception 'billing account % not found', v_schedule.account_id;
  end if;

  select * into v_schedule
  from public.billing_annual_grant_schedules
  where id = p_schedule
  for update;

  if v_schedule.status = 'completed' then
    return query select
      true, false, true, false,
      v_schedule.account_id,
      v_schedule.stripe_subscription_id,
      v_schedule.entitlement_version,
      v_schedule.price_lookup_key,
      v_schedule.included_usage_cents,
      v_schedule.cycle_started_at,
      v_schedule.grant_offset,
      v_schedule.grant_period,
      v_schedule.due_at,
      v_schedule.source_event_id;
    return;
  end if;

  if v_schedule.status <> 'pending' then
    return query select
      false, false, false, true,
      v_schedule.account_id,
      v_schedule.stripe_subscription_id,
      v_schedule.entitlement_version,
      v_schedule.price_lookup_key,
      v_schedule.included_usage_cents,
      v_schedule.cycle_started_at,
      v_schedule.grant_offset,
      v_schedule.grant_period,
      v_schedule.due_at,
      v_schedule.source_event_id;
    return;
  end if;

  if v_account.entitlement_version <> v_schedule.entitlement_version
    or v_account.stripe_subscription_id is distinct from
      v_schedule.stripe_subscription_id
    or v_account.plan_audience <> 'individual'
    or v_account.plan_code is null
    or v_account.included_hosted_usage_cents <>
      v_schedule.included_usage_cents
    or v_account.status = 'past_due' then
    update public.billing_annual_grant_schedules
    set status = 'cancelled',
        cancelled_at = now(),
        updated_at = now()
    where id = p_schedule;
    return query select
      false, false, false, true,
      v_schedule.account_id,
      v_schedule.stripe_subscription_id,
      v_schedule.entitlement_version,
      v_schedule.price_lookup_key,
      v_schedule.included_usage_cents,
      v_schedule.cycle_started_at,
      v_schedule.grant_offset,
      v_schedule.grant_period,
      v_schedule.due_at,
      v_schedule.source_event_id;
    return;
  end if;

  if now() < v_schedule.due_at then
    raise exception 'annual grant schedule % is not due', p_schedule;
  end if;
  if v_schedule.grant_period is distinct from
    to_char(v_schedule.due_at at time zone 'UTC', 'YYYY-MM') then
    raise exception 'annual grant schedule % has an invalid grant period',
      p_schedule;
  end if;

  select result.posted into v_posted
  from public.post_billing_period_grant(
    v_schedule.account_id,
    v_schedule.included_usage_cents,
    'grant:' || v_schedule.account_id::text || ':' ||
      v_schedule.grant_period || ':' || v_schedule.stripe_subscription_id,
    'grantexp:' || v_schedule.account_id::text || ':' ||
      v_schedule.grant_period || ':' || v_schedule.stripe_subscription_id,
    v_schedule.grant_period,
    jsonb_build_object(
      'source', 'capacity_annual_schedule',
      'plan', v_schedule.price_lookup_key,
      'catalog', 'capacity_v2',
      'schedule_id', v_schedule.id,
      'source_event_id', v_schedule.source_event_id
    )
  ) result;

  update public.billing_annual_grant_schedules
  set status = 'completed',
      completed_at = now(),
      updated_at = now()
  where id = p_schedule;

  return query select
    true, v_posted, not v_posted, false,
    v_schedule.account_id,
    v_schedule.stripe_subscription_id,
    v_schedule.entitlement_version,
    v_schedule.price_lookup_key,
    v_schedule.included_usage_cents,
    v_schedule.cycle_started_at,
    v_schedule.grant_offset,
    v_schedule.grant_period,
    v_schedule.due_at,
    v_schedule.source_event_id;
end;
$$;


--
-- Name: apply_billing_capacity_entitlement_snapshot(uuid, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_billing_capacity_entitlement_snapshot(p_account uuid, p_subscription_id text, p_source_event_id text, p_effective_at timestamp with time zone, p_snapshot jsonb) RETURNS TABLE(applied boolean, duplicate boolean, stale boolean, entitlement_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account public.billing_accounts%rowtype;
  v_existing public.billing_entitlement_snapshots%rowtype;
  v_should_apply boolean;
  v_cancellation boolean;
  v_event_priority smallint;
  v_plan jsonb;
  v_items jsonb;
  v_item jsonb;
  v_item_refs text[] := array[]::text[];
  v_item_ref text;
  v_item_kind text;
  v_lookup_key text;
  v_quantity integer;
  v_concurrency_delta integer;
  v_retained_delta bigint;
  v_hosted_delta bigint;
  v_plan_count integer := 0;
  v_plan_code text;
  v_max_named_users integer;
  v_included_concurrency integer;
  v_included_retained_bytes bigint;
  v_included_hosted_usage_cents bigint;
  v_period_anchor date;
begin
  if p_subscription_id is null or btrim(p_subscription_id) = '' then
    raise exception 'capacity entitlement subscription id is required';
  end if;
  if p_source_event_id is null or btrim(p_source_event_id) = '' then
    raise exception 'capacity entitlement source event id is required';
  end if;
  if p_effective_at is null then
    raise exception 'capacity entitlement effective time is required';
  end if;
  if p_snapshot is null or jsonb_typeof(p_snapshot) <> 'object' then
    raise exception 'capacity entitlement snapshot must be an object';
  end if;
  if p_snapshot->>'catalogVersion' is distinct from 'capacity_v2'
    or p_snapshot->>'subscriptionId' is distinct from btrim(p_subscription_id) then
    raise exception 'capacity entitlement snapshot identity is invalid';
  end if;
  if jsonb_typeof(p_snapshot->'cancellation') is distinct from 'boolean'
    or jsonb_typeof(p_snapshot->'items') is distinct from 'array' then
    raise exception 'capacity entitlement snapshot shape is invalid';
  end if;
  v_cancellation := (p_snapshot->>'cancellation')::boolean;
  v_event_priority := case when v_cancellation then 100 else 0 end;

  select * into v_account
  from public.billing_accounts
  where id = p_account
  for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;

  select * into v_existing
  from public.billing_entitlement_snapshots
  where account_id = p_account
    and source_event_id = btrim(p_source_event_id);
  if found then
    if v_existing.stripe_subscription_id <> btrim(p_subscription_id)
      or v_existing.effective_at <> p_effective_at
      or v_existing.snapshot <> p_snapshot then
      raise exception 'capacity entitlement snapshot idempotency conflict for %',
        p_source_event_id;
    end if;
    return query select
      false,
      true,
      not v_existing.applied,
      v_account.entitlement_version;
    return;
  end if;

  v_should_apply :=
    v_account.entitlement_projection_effective_at is null
    or p_effective_at > v_account.entitlement_projection_effective_at
    or (
      p_effective_at = v_account.entitlement_projection_effective_at
      and v_event_priority > v_account.entitlement_projection_priority
    )
    or (
      p_effective_at = v_account.entitlement_projection_effective_at
      and v_event_priority = v_account.entitlement_projection_priority
      and btrim(p_source_event_id) >
          coalesce(v_account.entitlement_projection_event_id, '')
    );

  insert into public.billing_entitlement_snapshots (
    account_id,
    stripe_subscription_id,
    source_event_id,
    effective_at,
    snapshot,
    applied
  ) values (
    p_account,
    btrim(p_subscription_id),
    btrim(p_source_event_id),
    p_effective_at,
    p_snapshot,
    v_should_apply
  );

  if not v_should_apply then
    return query select false, false, true, v_account.entitlement_version;
    return;
  end if;

  v_plan := p_snapshot->'plan';
  v_items := p_snapshot->'items';

  if v_cancellation then
    if v_plan is distinct from 'null'::jsonb
      or jsonb_array_length(v_items) <> 0 then
      raise exception 'capacity cancellation snapshot must not include entitlements';
    end if;
    v_plan_code := null;
    v_max_named_users := null;
    v_included_concurrency := 0;
    v_included_retained_bytes := 0;
    v_included_hosted_usage_cents := 0;
    v_period_anchor := null;
  else
    if jsonb_typeof(v_plan) is distinct from 'object' then
      raise exception 'capacity entitlement snapshot plan is required';
    end if;
    v_plan_code := v_plan->>'code';
    v_max_named_users := (v_plan->>'maxNamedUsers')::integer;
    v_included_concurrency := (v_plan->>'concurrency')::integer;
    v_included_retained_bytes := (v_plan->>'retainedDataBytes')::bigint;
    v_included_hosted_usage_cents :=
      (v_plan->>'hostedUsageCents')::bigint;
    v_period_anchor := (v_plan->>'periodAnchor')::date;
    if v_plan_code is null
      or v_plan_code not in ('pro', 'plus', 'max')
      or nullif(btrim(v_plan->>'priceLookupKey'), '') is null
      or v_max_named_users is distinct from 1
      or v_included_concurrency is null
      or v_included_concurrency < 0
      or v_included_retained_bytes is null
      or v_included_retained_bytes < 0
      or v_included_hosted_usage_cents is null
      or v_period_anchor is null
      or v_included_hosted_usage_cents < 0 then
      raise exception 'capacity entitlement plan values are invalid';
    end if;
  end if;

  for v_item in select value from jsonb_array_elements(v_items)
  loop
    if jsonb_typeof(v_item) is distinct from 'object' then
      raise exception 'capacity entitlement item must be an object';
    end if;
    v_item_ref := btrim(v_item->>'itemRef');
    v_item_kind := v_item->>'itemKind';
    v_lookup_key := btrim(v_item->>'priceLookupKey');
    v_quantity := (v_item->>'quantity')::integer;
    v_concurrency_delta := (v_item->>'concurrencyDelta')::integer;
    v_retained_delta := (v_item->>'retainedDataBytesDelta')::bigint;
    v_hosted_delta := (v_item->>'hostedUsageCentsDelta')::bigint;
    if v_item_ref is null or v_item_ref = ''
      or v_lookup_key is null or v_lookup_key = ''
      or v_item_kind is null
      or v_item_kind not in
        ('plan', 'concurrency_addon', 'retained_data_addon')
      or v_quantity is null
      or v_quantity <= 0
      or v_concurrency_delta is null
      or v_concurrency_delta < 0
      or v_retained_delta is null
      or v_retained_delta < 0
      or v_hosted_delta is null
      or v_hosted_delta < 0 then
      raise exception 'capacity entitlement item values are invalid';
    end if;
    if v_item_ref = any(v_item_refs) then
      raise exception 'duplicate capacity entitlement item %', v_item_ref;
    end if;
    v_item_refs := array_append(v_item_refs, v_item_ref);
    if v_item_kind = 'plan' then
      v_plan_count := v_plan_count + 1;
      if v_quantity <> 1
        or v_lookup_key <> v_plan->>'priceLookupKey'
        or v_concurrency_delta <> v_included_concurrency
        or v_retained_delta <> v_included_retained_bytes
        or v_hosted_delta <> v_included_hosted_usage_cents then
        raise exception 'capacity entitlement plan item does not match plan';
      end if;
    elsif v_hosted_delta <> 0 then
      raise exception 'capacity add-on cannot grant hosted usage';
    end if;

    insert into public.billing_entitlement_items (
      account_id,
      item_ref,
      item_kind,
      price_lookup_key,
      quantity,
      concurrency_delta,
      retained_data_bytes_delta,
      hosted_usage_cents_delta,
      effective_at,
      source_event_id,
      metadata
    ) values (
      p_account,
      v_item_ref,
      v_item_kind,
      v_lookup_key,
      v_quantity,
      v_concurrency_delta,
      v_retained_delta,
      v_hosted_delta,
      p_effective_at,
      btrim(p_source_event_id),
      jsonb_build_object(
        'stripe_subscription_id', btrim(p_subscription_id),
        'catalog_version', 'capacity_v2'
      )
    );
  end loop;

  if (not v_cancellation and v_plan_count <> 1)
    or (v_cancellation and v_plan_count <> 0) then
    raise exception 'capacity entitlement snapshot has an invalid plan count';
  end if;

  insert into public.billing_entitlement_items (
    account_id,
    item_ref,
    item_kind,
    price_lookup_key,
    quantity,
    concurrency_delta,
    retained_data_bytes_delta,
    hosted_usage_cents_delta,
    effective_at,
    source_event_id,
    metadata
  )
  select
    p_account,
    previous.item_ref,
    previous.item_kind,
    previous.price_lookup_key,
    0,
    previous.concurrency_delta,
    previous.retained_data_bytes_delta,
    previous.hosted_usage_cents_delta,
    p_effective_at,
    btrim(p_source_event_id),
    jsonb_build_object(
      'stripe_subscription_id', btrim(p_subscription_id),
      'catalog_version', 'capacity_v2',
      'closed_by_snapshot', true
    )
  from (
    select distinct on (item_ref)
      item_ref,
      item_kind,
      price_lookup_key,
      quantity,
      concurrency_delta,
      retained_data_bytes_delta,
      hosted_usage_cents_delta
    from public.billing_entitlement_items
    where account_id = p_account
      and metadata->>'stripe_subscription_id' = btrim(p_subscription_id)
      and source_event_id <> btrim(p_source_event_id)
    order by item_ref, effective_at desc, id desc
  ) previous
  where previous.quantity > 0
    and not (previous.item_ref = any(v_item_refs));

  update public.billing_accounts
  set plan_code = v_plan_code,
      plan_audience = case
        when v_plan_code is null then 'legacy'
        else 'individual'
      end,
      max_named_users = v_max_named_users,
      included_concurrency = v_included_concurrency,
      included_retained_bytes = v_included_retained_bytes,
      included_hosted_usage_cents = v_included_hosted_usage_cents,
      entitlement_catalog_version = 'capacity_v2',
      entitlement_version = public.billing_accounts.entitlement_version + 1,
      entitlement_projection_effective_at = p_effective_at,
      entitlement_projection_event_id = btrim(p_source_event_id),
      entitlement_projection_priority = v_event_priority,
      stripe_subscription_id = case
        when v_cancellation then null
        else btrim(p_subscription_id)
      end,
      period_anchor = v_period_anchor,
      updated_at = now()
  where id = p_account
  returning billing_accounts.entitlement_version
    into v_account.entitlement_version;

  return query select true, false, false, v_account.entitlement_version;
end;
$$;


--
-- Name: assert_slug_available(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_slug_available(p_slug text, p_kind text, p_self_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_slug is null then
    return;
  end if;

  if not public.is_valid_scope_slug(p_slug) then
    raise exception 'invalid slug %: must match [a-z0-9-], 1-39 chars, no leading/trailing/double hyphens', p_slug
      using errcode = 'check_violation';
  end if;

  if public.is_reserved_slug(p_slug) then
    raise exception 'slug % is reserved', p_slug
      using errcode = 'check_violation';
  end if;

  if p_kind = 'profile' then
    if exists (select 1 from public.teams where slug = p_slug) then
      raise exception 'slug % already taken by a team', p_slug using errcode = 'unique_violation';
    end if;
  elsif p_kind = 'team' then
    if exists (
      select 1 from public.profiles
      where slug = p_slug and (p_self_id is null or id <> p_self_id)
    ) then
      raise exception 'slug % already taken by a personal account', p_slug using errcode = 'unique_violation';
    end if;
  end if;
end;
$$;


--
-- Name: billing_balance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_balance(p_account uuid) RETURNS TABLE(included_cents bigint, purchased_cents bigint, total_cents bigint)
    LANGUAGE sql STABLE
    AS $$
  select
    coalesce(sum(delta_cents) filter (where bucket = 'included'), 0)::bigint,
    coalesce(sum(delta_cents) filter (where bucket = 'purchased'), 0)::bigint,
    coalesce(sum(delta_cents), 0)::bigint
  from public.credit_ledger where account_id = p_account;
$$;


--
-- Name: billing_monthly_spend(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_monthly_spend(p_account uuid, p_period text) RETURNS bigint
    LANGUAGE sql STABLE
    AS $$
  select coalesce(-sum(delta_cents), 0)::bigint from public.credit_ledger
  where account_id = p_account
    and delta_cents < 0
    and kind in ('usage_tokens', 'usage_sandbox')
    and period = p_period;
$$;


--
-- Name: bind_orchestration_worktree_agent(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_orchestration_worktree_agent(p_worktree_id uuid, p_user_id uuid, p_agent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_worktree public.orchestration_worktrees;
begin
  update public.orchestration_worktrees
  set agent_id = p_agent_id
  where id = p_worktree_id
    and user_id = p_user_id
    and status = 'active'
  returning * into v_worktree;

  if not found then
    raise exception 'active worktree not found';
  end if;

  update public.orchestration_tasks
  set agent_id = p_agent_id
  where id = v_worktree.task_id
    and run_id = v_worktree.run_id
    and repo_id = v_worktree.repo_id;

  if not found then
    raise exception 'worktree task is not available for agent binding';
  end if;

  return to_jsonb(v_worktree);
end;
$$;


--
-- Name: claim_archived_worktree(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_archived_worktree(p_worktree_id uuid, p_user_id uuid, p_expected_updated_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_token uuid := gen_random_uuid();
begin
  update public.orchestration_worktrees
  set metadata = metadata || jsonb_build_object('archived_claim',
    jsonb_build_object('token', v_token, 'claimed_at', now()))
  where id = p_worktree_id
    and user_id = p_user_id
    and status = 'archived'
    and updated_at = p_expected_updated_at
    and (metadata->'archived_claim' is null or
      (metadata->'archived_claim'->>'claimed_at')::timestamptz
        < now() - interval '10 minutes');

  if not found then
    return null;
  end if;
  return v_token;
end;
$$;


--
-- Name: claim_automation_job_run(uuid, uuid, bigint, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_automation_job_run(p_job_run_id uuid, p_repo_id uuid DEFAULT NULL::uuid, p_installation_id bigint DEFAULT NULL::bigint, p_claimed_at timestamp with time zone DEFAULT now(), p_max_running_per_repo integer DEFAULT 2, p_max_running_per_installation integer DEFAULT 8) RETURNS TABLE(claimed boolean, status text, reason text, started_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status TEXT;
  v_installation_running INT := 0;
BEGIN
  IF p_installation_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext('job_installation:' || p_installation_id::text));
  END IF;

  SELECT jr.status
  INTO v_status
  FROM public.job_runs jr
  WHERE jr.id = p_job_run_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::TEXT, 'JOB_NOT_FOUND'::TEXT, NULL::TIMESTAMPTZ;
    RETURN;
  END IF;

  IF v_status <> 'pending' THEN
    RETURN QUERY SELECT false, v_status, NULL::TEXT, NULL::TIMESTAMPTZ;
    RETURN;
  END IF;

  IF p_installation_id IS NOT NULL THEN
    SELECT COUNT(*)
    INTO v_installation_running
    FROM public.job_runs jr
    LEFT JOIN public.assignments a
      ON a.id = jr.assignment_id
    LEFT JOIN public.repos r
      ON r.id = a.repo_id
    LEFT JOIN public.triggers t
      ON t.id = jr.trigger_id
    WHERE jr.status = 'running'
      AND jr.id <> p_job_run_id
      AND COALESCE(
        t.installation_id::BIGINT,
        r.github_installation_id::BIGINT,
        NULLIF(jr.metadata->>'installation_id', '')::BIGINT
      ) = p_installation_id;

    IF v_installation_running >= p_max_running_per_installation THEN
      RETURN QUERY SELECT false, 'pending'::TEXT, 'INSTALLATION_CONCURRENCY_LIMIT'::TEXT, NULL::TIMESTAMPTZ;
      RETURN;
    END IF;
  END IF;

  UPDATE public.job_runs AS jr
  SET
    status = 'running',
    started_at = p_claimed_at,
    completed_at = NULL,
    duration_ms = NULL,
    input_tokens = NULL,
    output_tokens = NULL,
    error = NULL
  WHERE jr.id = p_job_run_id
    AND jr.status = 'pending';

  RETURN QUERY SELECT true, 'running'::TEXT, NULL::TEXT, p_claimed_at;
END;
$$;


--
-- Name: claim_chat_limit_admission(uuid, uuid, uuid, timestamp with time zone, uuid, integer, integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_chat_limit_admission(p_user_id uuid, p_repo_id uuid DEFAULT NULL::uuid, p_sandbox_id uuid DEFAULT NULL::uuid, p_now timestamp with time zone DEFAULT now(), p_claim_id uuid DEFAULT gen_random_uuid(), p_concurrent_limit integer DEFAULT 2, p_hourly_limit integer DEFAULT 30, p_daily_limit integer DEFAULT 150, p_hourly_window_seconds integer DEFAULT 3600, p_daily_window_seconds integer DEFAULT 86400, p_concurrency_retry_after_seconds integer DEFAULT 15, p_claim_ttl_seconds integer DEFAULT 300, p_stale_threshold_seconds integer DEFAULT 300) RETURNS TABLE(allowed boolean, claim_id uuid, code text, error text, reason text, retry_after_seconds integer, limit_name text, limit_value integer, window_seconds integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claim_id UUID := COALESCE(p_claim_id, gen_random_uuid());
  v_hourly_starts INT := 0;
  v_daily_starts INT := 0;
  v_hourly_oldest TIMESTAMPTZ := NULL;
  v_daily_oldest TIMESTAMPTZ := NULL;
  v_retry_after_seconds INT := NULL;
BEGIN
  -- Serialize each user's quota check and claim insertion. This guards the
  -- start-rate quotas without serializing or capping the admitted runs.
  PERFORM pg_advisory_xact_lock(hashtext('limit:chat:' || p_user_id::text));

  SELECT COUNT(*), MIN(le.created_at)
  INTO v_hourly_starts, v_hourly_oldest
  FROM public.limit_events le
  WHERE le.user_id = p_user_id
    AND le.route_key = 'chat'
    AND le.decision = 'allowed'
    AND le.created_at >= p_now - make_interval(secs => p_hourly_window_seconds);

  IF v_hourly_starts >= p_hourly_limit THEN
    v_retry_after_seconds := GREATEST(
      1,
      CEIL(EXTRACT(EPOCH FROM ((v_hourly_oldest + make_interval(secs => p_hourly_window_seconds)) - p_now)))::INT
    );

    INSERT INTO public.limit_events (
      user_id,
      route_key,
      resource_id,
      repo_id,
      sandbox_id,
      decision,
      reason,
      limit_name,
      window_seconds,
      limit_value,
      remaining,
      retry_after_seconds,
      metadata
    ) VALUES (
      p_user_id,
      'chat',
      COALESCE(p_sandbox_id::TEXT, p_repo_id::TEXT),
      p_repo_id,
      p_sandbox_id,
      'denied',
      'chat_hourly_rate_exceeded',
      'chat_starts_per_hour',
      p_hourly_window_seconds,
      p_hourly_limit,
      0,
      v_retry_after_seconds,
      jsonb_build_object('hourly_starts', v_hourly_starts)
    );

    RETURN QUERY SELECT
      FALSE,
      NULL::UUID,
      'chat_rate_limited'::TEXT,
      'Chat rate limit exceeded'::TEXT,
      'chat_hourly_rate_exceeded'::TEXT,
      v_retry_after_seconds,
      'chat_starts_per_hour'::TEXT,
      p_hourly_limit,
      p_hourly_window_seconds;
    RETURN;
  END IF;

  SELECT COUNT(*), MIN(le.created_at)
  INTO v_daily_starts, v_daily_oldest
  FROM public.limit_events le
  WHERE le.user_id = p_user_id
    AND le.route_key = 'chat'
    AND le.decision = 'allowed'
    AND le.created_at >= p_now - make_interval(secs => p_daily_window_seconds);

  IF v_daily_starts >= p_daily_limit THEN
    v_retry_after_seconds := GREATEST(
      1,
      CEIL(EXTRACT(EPOCH FROM ((v_daily_oldest + make_interval(secs => p_daily_window_seconds)) - p_now)))::INT
    );

    INSERT INTO public.limit_events (
      user_id,
      route_key,
      resource_id,
      repo_id,
      sandbox_id,
      decision,
      reason,
      limit_name,
      window_seconds,
      limit_value,
      remaining,
      retry_after_seconds,
      metadata
    ) VALUES (
      p_user_id,
      'chat',
      COALESCE(p_sandbox_id::TEXT, p_repo_id::TEXT),
      p_repo_id,
      p_sandbox_id,
      'denied',
      'chat_daily_quota_exceeded',
      'chat_starts_per_day',
      p_daily_window_seconds,
      p_daily_limit,
      0,
      v_retry_after_seconds,
      jsonb_build_object('daily_starts', v_daily_starts)
    );

    RETURN QUERY SELECT
      FALSE,
      NULL::UUID,
      'chat_rate_limited'::TEXT,
      'Daily chat quota exceeded'::TEXT,
      'chat_daily_quota_exceeded'::TEXT,
      v_retry_after_seconds,
      'chat_starts_per_day'::TEXT,
      p_daily_limit,
      p_daily_window_seconds;
    RETURN;
  END IF;

  INSERT INTO public.limit_events (
    user_id,
    route_key,
    claim_id,
    resource_id,
    repo_id,
    sandbox_id,
    decision,
    metadata
  ) VALUES (
    p_user_id,
    'chat',
    v_claim_id,
    COALESCE(p_sandbox_id::TEXT, p_repo_id::TEXT),
    p_repo_id,
    p_sandbox_id,
    'allowed',
    jsonb_build_object(
      'hourly_starts', v_hourly_starts + 1,
      'daily_starts', v_daily_starts + 1
    )
  );

  RETURN QUERY SELECT
    TRUE,
    v_claim_id,
    NULL::TEXT,
    NULL::TEXT,
    NULL::TEXT,
    NULL::INT,
    NULL::TEXT,
    NULL::INT,
    NULL::INT;
END;
$$;


--
-- Name: claim_external_agent_run_limit_admission(uuid, text, uuid, timestamp with time zone, uuid, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_external_agent_run_limit_admission(p_user_id uuid, p_api_key_id text, p_repo_id uuid DEFAULT NULL::uuid, p_now timestamp with time zone DEFAULT now(), p_claim_id uuid DEFAULT gen_random_uuid(), p_minutely_limit integer DEFAULT 10, p_hourly_limit integer DEFAULT 30, p_daily_limit integer DEFAULT 150, p_minutely_window_seconds integer DEFAULT 60, p_hourly_window_seconds integer DEFAULT 3600, p_daily_window_seconds integer DEFAULT 86400) RETURNS TABLE(allowed boolean, claim_id uuid, code text, error text, reason text, retry_after_seconds integer, limit_name text, limit_value integer, window_seconds integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claim_id UUID := p_claim_id;
  v_effective_now TIMESTAMPTZ := GREATEST(p_now, now());
  v_minutely_starts INT := 0;
  v_hourly_starts INT := 0;
  v_daily_starts INT := 0;
  v_minutely_oldest TIMESTAMPTZ := NULL;
  v_hourly_oldest TIMESTAMPTZ := NULL;
  v_daily_oldest TIMESTAMPTZ := NULL;
  v_retry_after_seconds INT := NULL;
BEGIN
  -- NOTE: hashtext is 32-bit; unrelated user/key pairs can theoretically
  -- share lock contention (~1 in 2^31 per pair), but never corrupt counts.
  -- user_api_keys.id is a UUID, so ':' cannot alias lock-key components.
  PERFORM pg_advisory_xact_lock(
    hashtext('limit:external_agent_run:' || p_user_id::text || ':' || p_api_key_id)
  );

  SELECT
    COUNT(*) FILTER (
      WHERE le.created_at >= v_effective_now - make_interval(secs => p_minutely_window_seconds)
    ),
    MIN(le.created_at) FILTER (
      WHERE le.created_at >= v_effective_now - make_interval(secs => p_minutely_window_seconds)
    ),
    COUNT(*) FILTER (
      WHERE le.created_at >= v_effective_now - make_interval(secs => p_hourly_window_seconds)
    ),
    MIN(le.created_at) FILTER (
      WHERE le.created_at >= v_effective_now - make_interval(secs => p_hourly_window_seconds)
    ),
    COUNT(*) FILTER (
      WHERE le.created_at >= v_effective_now - make_interval(secs => p_daily_window_seconds)
    ),
    MIN(le.created_at) FILTER (
      WHERE le.created_at >= v_effective_now - make_interval(secs => p_daily_window_seconds)
    )
  INTO
    v_minutely_starts,
    v_minutely_oldest,
    v_hourly_starts,
    v_hourly_oldest,
    v_daily_starts,
    v_daily_oldest
  FROM public.limit_events le
  WHERE le.user_id = p_user_id
    AND le.route_key = 'external_agent_run'
    AND le.resource_id = p_api_key_id
    AND le.decision = 'allowed'
    AND le.created_at <= v_effective_now
    AND le.created_at >= v_effective_now - make_interval(secs => GREATEST(
      p_minutely_window_seconds,
      p_hourly_window_seconds,
      p_daily_window_seconds
    ));

  IF v_minutely_starts >= p_minutely_limit THEN
    v_retry_after_seconds := GREATEST(
      1,
      CEIL(EXTRACT(EPOCH FROM ((v_minutely_oldest + make_interval(secs => p_minutely_window_seconds)) - v_effective_now)))::INT
    );

    INSERT INTO public.limit_events (
      user_id,
      route_key,
      resource_id,
      repo_id,
      decision,
      reason,
      limit_name,
      window_seconds,
      limit_value,
      remaining,
      retry_after_seconds,
      metadata
    ) VALUES (
      p_user_id,
      'external_agent_run',
      p_api_key_id,
      p_repo_id,
      'denied',
      'external_agent_run_minutely_rate_exceeded',
      'external_agent_runs_per_minute',
      p_minutely_window_seconds,
      p_minutely_limit,
      0,
      v_retry_after_seconds,
      jsonb_build_object(
        'api_key_id', p_api_key_id,
        'minutely_starts', v_minutely_starts
      )
    );

    RETURN QUERY SELECT
      FALSE,
      NULL::UUID,
      'external_agent_run_rate_limited'::TEXT,
      'External Mogplex run rate limit exceeded'::TEXT,
      'external_agent_run_minutely_rate_exceeded'::TEXT,
      v_retry_after_seconds,
      'external_agent_runs_per_minute'::TEXT,
      p_minutely_limit,
      p_minutely_window_seconds;
    RETURN;
  END IF;

  IF v_hourly_starts >= p_hourly_limit THEN
    v_retry_after_seconds := GREATEST(
      1,
      CEIL(EXTRACT(EPOCH FROM ((v_hourly_oldest + make_interval(secs => p_hourly_window_seconds)) - v_effective_now)))::INT
    );

    INSERT INTO public.limit_events (
      user_id,
      route_key,
      resource_id,
      repo_id,
      decision,
      reason,
      limit_name,
      window_seconds,
      limit_value,
      remaining,
      retry_after_seconds,
      metadata
    ) VALUES (
      p_user_id,
      'external_agent_run',
      p_api_key_id,
      p_repo_id,
      'denied',
      'external_agent_run_hourly_rate_exceeded',
      'external_agent_runs_per_hour',
      p_hourly_window_seconds,
      p_hourly_limit,
      0,
      v_retry_after_seconds,
      jsonb_build_object(
        'api_key_id', p_api_key_id,
        'minutely_starts', v_minutely_starts,
        'hourly_starts', v_hourly_starts
      )
    );

    RETURN QUERY SELECT
      FALSE,
      NULL::UUID,
      'external_agent_run_rate_limited'::TEXT,
      'External Mogplex run rate limit exceeded'::TEXT,
      'external_agent_run_hourly_rate_exceeded'::TEXT,
      v_retry_after_seconds,
      'external_agent_runs_per_hour'::TEXT,
      p_hourly_limit,
      p_hourly_window_seconds;
    RETURN;
  END IF;

  IF v_daily_starts >= p_daily_limit THEN
    v_retry_after_seconds := GREATEST(
      1,
      CEIL(EXTRACT(EPOCH FROM ((v_daily_oldest + make_interval(secs => p_daily_window_seconds)) - v_effective_now)))::INT
    );

    INSERT INTO public.limit_events (
      user_id,
      route_key,
      resource_id,
      repo_id,
      decision,
      reason,
      limit_name,
      window_seconds,
      limit_value,
      remaining,
      retry_after_seconds,
      metadata
    ) VALUES (
      p_user_id,
      'external_agent_run',
      p_api_key_id,
      p_repo_id,
      'denied',
      'external_agent_run_daily_quota_exceeded',
      'external_agent_runs_per_day',
      p_daily_window_seconds,
      p_daily_limit,
      0,
      v_retry_after_seconds,
      jsonb_build_object(
        'api_key_id', p_api_key_id,
        'minutely_starts', v_minutely_starts,
        'hourly_starts', v_hourly_starts,
        'daily_starts', v_daily_starts
      )
    );

    RETURN QUERY SELECT
      FALSE,
      NULL::UUID,
      'external_agent_run_rate_limited'::TEXT,
      'Daily external Mogplex run quota exceeded'::TEXT,
      'external_agent_run_daily_quota_exceeded'::TEXT,
      v_retry_after_seconds,
      'external_agent_runs_per_day'::TEXT,
      p_daily_limit,
      p_daily_window_seconds;
    RETURN;
  END IF;

  INSERT INTO public.limit_events (
    user_id,
    route_key,
    claim_id,
    resource_id,
    repo_id,
    decision,
    metadata
  ) VALUES (
    p_user_id,
    'external_agent_run',
    v_claim_id,
    p_api_key_id,
    p_repo_id,
    'allowed',
    jsonb_build_object(
      'api_key_id', p_api_key_id,
      'minutely_starts', v_minutely_starts + 1,
      'hourly_starts', v_hourly_starts + 1,
      'daily_starts', v_daily_starts + 1
    )
  );

  RETURN QUERY SELECT
    TRUE,
    v_claim_id,
    NULL::TEXT,
    NULL::TEXT,
    NULL::TEXT,
    NULL::INT,
    NULL::TEXT,
    NULL::INT,
    NULL::INT;
END;
$$;


--
-- Name: claim_sandbox_auto_pause(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_sandbox_auto_pause(p_sandbox_record_id uuid, p_sandbox_id text, p_released_at timestamp with time zone) RETURNS TABLE(claimed boolean, previous_health_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform pg_advisory_xact_lock(
    hashtextextended('sandbox-presence:' || p_sandbox_record_id::text, 0)
  );

  return query
  with candidate as (
    select s.id, s.health_status
    from public.sandboxes s
    where s.id = p_sandbox_record_id
      and s.sandbox_id = p_sandbox_id
      and s.status = 'running'
      and s.persistent is true
      and s.exec_lock_token is null
      and not exists (
        select 1
        from public.sandbox_client_sessions scs
        where scs.sandbox_record_id = s.id
          and (
            scs.released_at is null
            or scs.last_event_at > p_released_at
          )
      )
      and not exists (
        select 1
        from public.ai_calls ac
        where ac.status in ('pending', 'streaming')
          and (
            ac.metadata->>'sandbox_record_id' = s.id::text
            or ac.metadata->>'sandbox_id' = s.id::text
            or ac.metadata->>'sandbox_id' = s.sandbox_id
          )
      )
      and not exists (
        select 1
        from public.external_agent_runs ear
        where ear.sandbox_record_id = s.id
          and ear.status in ('pending', 'streaming')
      )
    limit 1
  ),
  updated as (
    update public.sandboxes s
    set
      status = 'pausing',
      health_status = 'pausing',
      stop_reason = 'auto_pause',
      last_active_at = now()
    from candidate c
    where s.id = c.id
    returning c.health_status
  )
  select true, updated.health_status
  from updated
  union all
  select false, null::text
  where not exists (select 1 from updated);
end;
$$;


--
-- Name: claim_sandbox_boot_limit_admission(uuid, uuid, timestamp with time zone, uuid, integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_sandbox_boot_limit_admission(p_user_id uuid, p_repo_id uuid, p_now timestamp with time zone DEFAULT now(), p_claim_id uuid DEFAULT gen_random_uuid(), p_active_limit integer DEFAULT 2, p_hourly_limit integer DEFAULT 5, p_daily_limit integer DEFAULT 20, p_hourly_window_seconds integer DEFAULT 3600, p_daily_window_seconds integer DEFAULT 86400, p_concurrency_retry_after_seconds integer DEFAULT 15, p_claim_ttl_seconds integer DEFAULT 300) RETURNS TABLE(allowed boolean, claim_id uuid, code text, error text, reason text, retry_after_seconds integer, limit_name text, limit_value integer, window_seconds integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claim_id UUID := COALESCE(p_claim_id, gen_random_uuid());
  v_active_sandboxes INT := 0;
  v_provisional_boots INT := 0;
  v_hourly_boots INT := 0;
  v_daily_boots INT := 0;
  v_hourly_oldest TIMESTAMPTZ := NULL;
  v_daily_oldest TIMESTAMPTZ := NULL;
  v_retry_after_seconds INT := NULL;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('limit:sandbox_boot:' || p_user_id::text));

  SELECT COUNT(*)
  INTO v_active_sandboxes
  FROM public.sandboxes s
  WHERE s.user_id = p_user_id
    AND s.status IN ('creating', 'installing', 'running');

  SELECT COUNT(*)
  INTO v_provisional_boots
  FROM public.limit_events le
  WHERE le.user_id = p_user_id
    AND le.route_key = 'sandbox_boot'
    AND le.decision = 'allowed'
    AND le.claim_id IS NOT NULL
    AND le.created_at >= p_now - make_interval(secs => p_claim_ttl_seconds)
    AND NOT EXISTS (
      SELECT 1
      FROM public.sandboxes s
      WHERE s.limit_claim_id = le.claim_id
    );

  IF v_active_sandboxes + v_provisional_boots >= p_active_limit THEN
    INSERT INTO public.limit_events (
      user_id,
      route_key,
      resource_id,
      repo_id,
      decision,
      reason,
      limit_name,
      window_seconds,
      limit_value,
      remaining,
      retry_after_seconds,
      metadata
    ) VALUES (
      p_user_id,
      'sandbox_boot',
      p_repo_id::TEXT,
      p_repo_id,
      'denied',
      'active_sandbox_limit_exceeded',
      'active_sandboxes',
      0,
      p_active_limit,
      GREATEST(p_active_limit - (v_active_sandboxes + v_provisional_boots), 0),
      p_concurrency_retry_after_seconds,
      jsonb_build_object(
        'active_sandboxes', v_active_sandboxes,
        'provisional_boots', v_provisional_boots
      )
    );

    RETURN QUERY SELECT
      FALSE,
      NULL::UUID,
      'sandbox_boot_rate_limited'::TEXT,
      'Too many active sandboxes'::TEXT,
      'active_sandbox_limit_exceeded'::TEXT,
      p_concurrency_retry_after_seconds,
      'active_sandboxes'::TEXT,
      p_active_limit,
      0;
    RETURN;
  END IF;

  SELECT COUNT(*), MIN(le.created_at)
  INTO v_hourly_boots, v_hourly_oldest
  FROM public.limit_events le
  WHERE le.user_id = p_user_id
    AND le.route_key = 'sandbox_boot'
    AND le.decision = 'allowed'
    AND le.created_at >= p_now - make_interval(secs => p_hourly_window_seconds);

  IF v_hourly_boots >= p_hourly_limit THEN
    v_retry_after_seconds := GREATEST(
      1,
      CEIL(EXTRACT(EPOCH FROM ((v_hourly_oldest + make_interval(secs => p_hourly_window_seconds)) - p_now)))::INT
    );

    INSERT INTO public.limit_events (
      user_id,
      route_key,
      resource_id,
      repo_id,
      decision,
      reason,
      limit_name,
      window_seconds,
      limit_value,
      remaining,
      retry_after_seconds,
      metadata
    ) VALUES (
      p_user_id,
      'sandbox_boot',
      p_repo_id::TEXT,
      p_repo_id,
      'denied',
      'sandbox_boot_hourly_rate_exceeded',
      'sandbox_boots_per_hour',
      p_hourly_window_seconds,
      p_hourly_limit,
      0,
      v_retry_after_seconds,
      jsonb_build_object(
        'active_sandboxes', v_active_sandboxes,
        'provisional_boots', v_provisional_boots,
        'hourly_boots', v_hourly_boots
      )
    );

    RETURN QUERY SELECT
      FALSE,
      NULL::UUID,
      'sandbox_boot_rate_limited'::TEXT,
      'Sandbox boot rate limit exceeded'::TEXT,
      'sandbox_boot_hourly_rate_exceeded'::TEXT,
      v_retry_after_seconds,
      'sandbox_boots_per_hour'::TEXT,
      p_hourly_limit,
      p_hourly_window_seconds;
    RETURN;
  END IF;

  SELECT COUNT(*), MIN(le.created_at)
  INTO v_daily_boots, v_daily_oldest
  FROM public.limit_events le
  WHERE le.user_id = p_user_id
    AND le.route_key = 'sandbox_boot'
    AND le.decision = 'allowed'
    AND le.created_at >= p_now - make_interval(secs => p_daily_window_seconds);

  IF v_daily_boots >= p_daily_limit THEN
    v_retry_after_seconds := GREATEST(
      1,
      CEIL(EXTRACT(EPOCH FROM ((v_daily_oldest + make_interval(secs => p_daily_window_seconds)) - p_now)))::INT
    );

    INSERT INTO public.limit_events (
      user_id,
      route_key,
      resource_id,
      repo_id,
      decision,
      reason,
      limit_name,
      window_seconds,
      limit_value,
      remaining,
      retry_after_seconds,
      metadata
    ) VALUES (
      p_user_id,
      'sandbox_boot',
      p_repo_id::TEXT,
      p_repo_id,
      'denied',
      'sandbox_boot_daily_quota_exceeded',
      'sandbox_boots_per_day',
      p_daily_window_seconds,
      p_daily_limit,
      0,
      v_retry_after_seconds,
      jsonb_build_object(
        'active_sandboxes', v_active_sandboxes,
        'provisional_boots', v_provisional_boots,
        'daily_boots', v_daily_boots
      )
    );

    RETURN QUERY SELECT
      FALSE,
      NULL::UUID,
      'sandbox_boot_rate_limited'::TEXT,
      'Daily sandbox boot quota exceeded'::TEXT,
      'sandbox_boot_daily_quota_exceeded'::TEXT,
      v_retry_after_seconds,
      'sandbox_boots_per_day'::TEXT,
      p_daily_limit,
      p_daily_window_seconds;
    RETURN;
  END IF;

  INSERT INTO public.limit_events (
    user_id,
    route_key,
    claim_id,
    resource_id,
    repo_id,
    decision,
    metadata
  ) VALUES (
    p_user_id,
    'sandbox_boot',
    v_claim_id,
    p_repo_id::TEXT,
    p_repo_id,
    'allowed',
    jsonb_build_object(
      'active_sandboxes', v_active_sandboxes,
      'provisional_boots', v_provisional_boots,
      'hourly_boots', v_hourly_boots + 1,
      'daily_boots', v_daily_boots + 1
    )
  );

  RETURN QUERY SELECT
    TRUE,
    v_claim_id,
    NULL::TEXT,
    NULL::TEXT,
    NULL::TEXT,
    NULL::INT,
    NULL::TEXT,
    NULL::INT,
    NULL::INT;
END;
$$;


--
-- Name: cleanup_user_mcp_server_secrets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_user_mcp_server_secrets() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_secret_id_text text;
begin
  for v_secret_id_text in
    (
      select value
      from jsonb_each_text(
        case
          when tg_op = 'DELETE' then old.env_refs
          else coalesce(old.env_refs, '{}'::jsonb)
        end
      )
      union
      select value
      from jsonb_each_text(
        case
          when tg_op = 'DELETE' then old.header_refs
          else coalesce(old.header_refs, '{}'::jsonb)
        end
      )
    )
    except
    (
      select value
      from jsonb_each_text(
        case
          when tg_op = 'DELETE' then '{}'::jsonb
          else coalesce(new.env_refs, '{}'::jsonb)
        end
      )
      union
      select value
      from jsonb_each_text(
        case
          when tg_op = 'DELETE' then '{}'::jsonb
          else coalesce(new.header_refs, '{}'::jsonb)
        end
      )
    )
  loop
    begin
      delete from vault.secrets where id = v_secret_id_text::uuid;
    exception
      when invalid_text_representation then
        null;
    end;
  end loop;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;


--
-- Name: compute_ai_call_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_ai_call_cost() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  p_input       NUMERIC;
  p_output      NUMERIC;
  p_cache_read  NUMERIC;
  p_cache_write NUMERIC;
  v_cost        NUMERIC;
BEGIN
  -- Caller-owned cost_usd: gateway reconciliation (W7) and manual operator
  -- overrides both opt out of the formula. On INSERT, this also bypasses the
  -- ambiguous cost_usd guard below: callers using 'gateway' or 'manual' are
  -- explicitly claiming ownership of their supplied cost_usd. The CHECK
  -- constraint on cost_source restricts this to ('trigger', 'gateway', 'manual').
  -- Token updates on gateway/manual rows intentionally preserve the caller-owned
  -- cost until cost_source is changed away from gateway/manual.
  IF NEW.cost_source IN ('gateway', 'manual') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT'
     AND NEW.cost_usd IS NOT NULL THEN
    RAISE EXCEPTION
      'ai_calls.cost_usd is computed when cost_source is trigger or unset. '
      'INSERT must omit cost_usd or set cost_source=manual/gateway for caller-owned costs.'
      USING HINT = 'Use cost_source=''manual'' for operator-supplied costs, or cost_source=''gateway'' for W7 reconciliation values.';
  END IF;

  -- A direct cost_usd write on a trigger-owned or unclaimed row is ambiguous:
  -- the formula owns the value, so silently recomputing would discard the
  -- caller's number. If the caller means an operator override, they must claim
  -- that explicitly with cost_source='manual' in the same UPDATE.
  -- Manual and gateway rows have already returned above, so this guard is only
  -- reached while NEW.cost_source is trigger or unset.
  IF TG_OP = 'UPDATE'
     AND COALESCE(OLD.cost_source, 'trigger') = 'trigger'
     AND COALESCE(NEW.cost_source, 'trigger') = 'trigger'
     AND NEW.cost_usd IS DISTINCT FROM OLD.cost_usd
     AND NEW.model IS NOT DISTINCT FROM OLD.model
     AND NEW.input_tokens IS NOT DISTINCT FROM OLD.input_tokens
     AND NEW.output_tokens IS NOT DISTINCT FROM OLD.output_tokens
     AND NEW.cache_read_input_tokens IS NOT DISTINCT FROM OLD.cache_read_input_tokens
     AND NEW.cache_creation_input_tokens IS NOT DISTINCT FROM OLD.cache_creation_input_tokens THEN
    RAISE EXCEPTION
      'ai_calls.cost_usd is computed while cost_source=trigger. '
      'Direct cost_usd writes must either change pricing inputs or set cost_source=manual.'
      USING HINT = 'Use UPDATE ... SET cost_usd = X, cost_source = ''manual'' for operator overrides.';
  END IF;

  SELECT pricing_input, pricing_output, pricing_cache_read, pricing_cache_write
    INTO p_input, p_output, p_cache_read, p_cache_write
    FROM ai_models
   WHERE id = NEW.model
   LIMIT 1;

  IF NEW.input_tokens IS NULL
     AND NEW.output_tokens IS NULL
     AND NEW.cache_read_input_tokens IS NULL
     AND NEW.cache_creation_input_tokens IS NULL THEN
    NEW.cost_usd := NULL;
    NEW.cost_source := 'trigger';
    RETURN NEW;
  END IF;

  IF p_input IS NULL AND p_output IS NULL THEN
    NEW.cost_usd := NULL;
    NEW.cost_source := 'trigger';
    RETURN NEW;
  END IF;

  p_cache_read  := COALESCE(p_cache_read,  p_input * 0.1);
  p_cache_write := COALESCE(p_cache_write, p_input * 1.25);

  v_cost :=
      CASE WHEN COALESCE(NEW.input_tokens, 0)                > 0 THEN NEW.input_tokens                * p_input       ELSE 0 END
    + CASE WHEN COALESCE(NEW.cache_read_input_tokens, 0)     > 0 THEN NEW.cache_read_input_tokens     * p_cache_read  ELSE 0 END
    + CASE WHEN COALESCE(NEW.cache_creation_input_tokens, 0) > 0 THEN NEW.cache_creation_input_tokens * p_cache_write ELSE 0 END
    + CASE WHEN COALESCE(NEW.output_tokens, 0)               > 0 THEN NEW.output_tokens               * p_output      ELSE 0 END;

  NEW.cost_usd := v_cost;
  NEW.cost_source := 'trigger';
  RETURN NEW;
END;
$$;


SET default_table_access_method = heap;

--
-- Name: slack_user_mappings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.slack_user_mappings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slack_installation_id uuid NOT NULL,
    slack_user_id text NOT NULL,
    mogplex_user_id uuid,
    slack_email text,
    matched_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    link_status text DEFAULT 'legacy_email'::text NOT NULL,
    linked_at timestamp with time zone,
    linked_by_user_id uuid,
    CONSTRAINT slack_user_mappings_link_status_check CHECK ((link_status = ANY (ARRAY['legacy_email'::text, 'explicit'::text])))
);


--
-- Name: consume_slack_user_link_token(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_slack_user_link_token(p_token_hash text, p_mogplex_user_id uuid) RETURNS public.slack_user_mappings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_token public.slack_user_link_tokens;
  v_mapping public.slack_user_mappings;
begin
  if nullif(trim(p_token_hash), '') is null then
    raise exception 'token hash is required';
  end if;
  if p_mogplex_user_id is null then
    raise exception 'mogplex user id is required';
  end if;

  select *
    into v_token
  from public.slack_user_link_tokens
  where token_hash = p_token_hash
    and consumed_at is null
    and expires_at > now()
  for update;

  if v_token.id is null then
    return null;
  end if;

  update public.slack_user_link_tokens
    set consumed_at = now()
  where id = v_token.id;

  insert into public.slack_user_mappings as mapping (
    slack_installation_id,
    slack_user_id,
    mogplex_user_id,
    slack_email,
    matched_at,
    link_status,
    linked_at,
    linked_by_user_id
  ) values (
    v_token.slack_installation_id,
    v_token.slack_user_id,
    p_mogplex_user_id,
    -- Link tokens do not carry Slack profile data. A fresh explicit link keeps
    -- this null until a later users.info refresh; relinks preserve existing
    -- slack_email because the conflict update intentionally omits it.
    null,
    now(),
    'explicit',
    now(),
    p_mogplex_user_id
  )
  on conflict (slack_installation_id, slack_user_id) do update set
    mogplex_user_id = excluded.mogplex_user_id,
    matched_at = excluded.matched_at,
    link_status = 'explicit',
    linked_at = excluded.linked_at,
    linked_by_user_id = excluded.linked_by_user_id
  returning mapping.* into v_mapping;

  return v_mapping;
end;
$$;


--
-- Name: control_claim_approvals(uuid, uuid, text, text[], uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_claim_approvals(p_user_id uuid, p_session_id uuid, p_message_id text, p_approval_ids text[], p_ai_call_id uuid, p_expected_message jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  session_row public.control_sessions%rowtype;
  saved_message jsonb;
begin
  if p_ai_call_id is null or coalesce(cardinality(p_approval_ids), 0) = 0
     or (select count(*) <> count(distinct id) from unnest(p_approval_ids) id)
  then return false; end if;
  select * into session_row from public.control_sessions
    where id = p_session_id and user_id = p_user_id and archived = false for update;
  if not found then return false; end if;
  -- A newer turn supersedes this approval continuation. Check under the same
  -- row lock as the claim, not only against a request's earlier snapshot.
  if session_row.messages->-1->>'id' is distinct from p_message_id then return false; end if;
  select m into saved_message from jsonb_array_elements(session_row.messages) m
    where m->>'id' = p_message_id and m->>'role' = 'assistant';
  if saved_message is null or saved_message is distinct from p_expected_message then return false; end if;
  if exists (
    select 1 from public.control_approval_continuations
    where session_id = p_session_id and message_id = p_message_id
  ) then return false; end if;
  if exists (
    select 1 from unnest(p_approval_ids) id
    where not exists (
      select 1 from jsonb_array_elements(saved_message->'parts') part
      where part->>'state' = 'approval-requested'
        and part->'approval'->>'id' = id
    ) or exists (
      select 1 from public.control_approval_executions c
      where c.session_id = p_session_id and c.approval_id = id
    )
  ) then return false; end if;
  insert into public.control_approval_continuations
    (session_id, message_id, user_id, ai_call_id)
    values (p_session_id, p_message_id, p_user_id, p_ai_call_id);
  insert into public.control_approval_executions
    (session_id, approval_id, user_id, message_id, ai_call_id)
    select p_session_id, id, p_user_id, p_message_id, p_ai_call_id from unnest(p_approval_ids) id;
  return true;
end;
$$;


--
-- Name: control_claim_continuation(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_claim_continuation(p_user_id uuid, p_continuation_id uuid, p_runtime_run_id text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  ticket jsonb;
begin
  if coalesce(btrim(p_runtime_run_id),'') = '' then return null; end if;
  ticket := public.control_refresh_continuation(p_user_id,p_continuation_id);
  if ticket is null or ticket->>'status' <> 'ready' then return null; end if;
  update public.control_continuations set status = 'running', runtime_run_id = p_runtime_run_id, error = null, updated_at = clock_timestamp()
    where id = p_continuation_id and user_id = p_user_id and status = 'ready' returning to_jsonb(control_continuations.*) into ticket;
  return ticket;
end;
$$;


--
-- Name: control_finish_approval_continuation(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_finish_approval_continuation(p_user_id uuid, p_session_id uuid, p_message_id text, p_ai_call_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  perform 1 from public.control_sessions
    where id = p_session_id and user_id = p_user_id for update;
  if not found then return false; end if;
  delete from public.control_approval_continuations
    where session_id = p_session_id and message_id = p_message_id
      and user_id = p_user_id and ai_call_id = p_ai_call_id;
  return found;
end;
$$;


--
-- Name: control_latest_user_message(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_latest_user_message(p_messages jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select value from jsonb_array_elements(p_messages) with ordinality m
  where value->>'role' = 'user' order by ordinality desc limit 1;
$$;


--
-- Name: control_mission_workers(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_mission_workers(p_user_id uuid, p_session_id uuid, p_include_events boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  mission_run_id uuid;
  result jsonb;
begin
  select orchestration_run_id into mission_run_id
    from public.control_sessions where id = p_session_id and user_id = p_user_id;
  if not found then return null; end if;
  if mission_run_id is null then return '[]'::jsonb; end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', r.id, 'worktree_id', w.id, 'branch', w.branch_name,
      'status', r.status, 'error', r.error, 'updated_at', r.updated_at,
      'events', case when p_include_events then (
        select coalesce(jsonb_agg(to_jsonb(recent) order by recent.created_at, recent.id), '[]'::jsonb)
        from (
          select e.id, e.event_type, e.tool_name, e.message, e.payload, e.created_at
          from public.ai_call_events e
          where e.user_id = p_user_id and e.ai_call_id = r.ai_call_id
          order by e.created_at desc, e.id desc limit 100
        ) recent
      ) else '[]'::jsonb end
    ) order by w.created_at, w.id
  ), '[]'::jsonb) into result
  from public.orchestration_worktrees w
  cross join lateral (
    select a.id, a.ai_call_id, a.status, a.error, a.updated_at
    from public.external_agent_runs a
    where a.worktree_id = w.id and a.user_id = p_user_id
    order by a.created_at desc, a.id desc limit 1
  ) r
  where w.run_id = mission_run_id and w.user_id = p_user_id;
  return result;
end;
$$;


--
-- Name: control_notify_continuation_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_notify_continuation_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  perform pg_notify('mogplex_table_events', json_build_object(
    'table', TG_TABLE_NAME, 'op', TG_OP,
    'user_id', coalesce(to_jsonb(NEW)->>'user_id', to_jsonb(OLD)->>'user_id'),
    'id', coalesce(to_jsonb(NEW)->>'id', to_jsonb(OLD)->>'id')
  )::text);
  return coalesce(NEW, OLD);
end;
$$;


--
-- Name: control_refresh_continuation(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_refresh_continuation(p_user_id uuid, p_continuation_id uuid, p_parent_ai_call_id uuid DEFAULT NULL::uuid, p_parent_message jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  ticket public.control_continuations%rowtype;
  session_row public.control_sessions%rowtype;
begin
  select * into ticket from public.control_continuations where id = p_continuation_id and user_id = p_user_id;
  if not found then return null; end if;
  select * into session_row from public.control_sessions where id = ticket.session_id and user_id = p_user_id for update;
  if not found then return null; end if;
  select * into ticket from public.control_continuations where id = p_continuation_id and user_id = p_user_id for update;
  if ticket.status not in ('waiting','ready') then return to_jsonb(ticket); end if;
  if session_row.archived or session_row.repo_id::text is distinct from ticket.request_context->>'repoId'
    or public.control_latest_user_message(session_row.messages) is distinct from ticket.origin_message then
    update public.control_continuations set status = 'cancelled', error = 'Superseded by a newer user request.', updated_at = clock_timestamp()
      where id = ticket.id returning * into ticket;
    return to_jsonb(ticket);
  end if;
  if p_parent_ai_call_id is not null then
    if p_parent_ai_call_id <> ticket.parent_ai_call_id
      or p_parent_message is null
      or p_parent_message->>'role' is distinct from 'assistant'
      or p_parent_message->'metadata'->>'ai_call_id' is distinct from p_parent_ai_call_id::text
      or not exists (select 1 from jsonb_array_elements(session_row.messages) m where m = p_parent_message)
    then raise exception 'Parent transcript checkpoint is not durable' using errcode = '22023'; end if;
    update public.control_continuations set parent_ready = true, updated_at = clock_timestamp()
      where id = ticket.id returning * into ticket;
  end if;
  if ticket.parent_ready and not exists (
    select 1 from unnest(ticket.worker_run_ids) requested(worker_id) where not exists (
      select 1 from public.external_agent_runs r where r.id = requested.worker_id and r.user_id = p_user_id
        and r.status in ('success','failed','cancelled','awaiting_input')
    )
  ) then
    update public.control_continuations set status = 'ready', updated_at = clock_timestamp()
      where id = ticket.id returning * into ticket;
  end if;
  return to_jsonb(ticket);
end;
$$;


--
-- Name: control_register_continuation(uuid, uuid, uuid, text, uuid[], jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_register_continuation(p_user_id uuid, p_session_id uuid, p_parent_ai_call_id uuid, p_origin_message_id text, p_worker_run_ids uuid[], p_request_context jsonb, p_instruction text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  session_row public.control_sessions%rowtype;
  current_origin jsonb;
  existing public.control_continuations%rowtype;
  worker_ids uuid[];
begin
  select * into session_row from public.control_sessions
    where id = p_session_id and user_id = p_user_id and archived = false for update;
  if not found then return jsonb_build_object('status','not_found'); end if;
  current_origin := public.control_latest_user_message(session_row.messages);
  if current_origin is null or current_origin->>'id' is distinct from p_origin_message_id
  then return jsonb_build_object('status','superseded'); end if;
  if session_row.orchestration_run_id is null or session_row.repo_id is null
    or not exists (select 1 from public.ai_calls where id = p_parent_ai_call_id
      and user_id = p_user_id and metadata->>'mission_id' = p_session_id::text)
  then return jsonb_build_object('status','not_found'); end if;
  if coalesce(cardinality(p_worker_run_ids),0) = 0
    or (select count(*) <> count(distinct id) from unnest(p_worker_run_ids) id)
    or array_position(p_worker_run_ids, null) is not null
    or jsonb_typeof(p_request_context) is distinct from 'object'
    or p_request_context->>'repoId' is distinct from session_row.repo_id::text
    or p_request_context->>'missionId' is distinct from p_session_id::text
    or p_request_context->>'mode' = 'plan'
    or coalesce(btrim(p_request_context->>'model'),'') = ''
    or coalesce(btrim(p_instruction),'') = ''
  then return jsonb_build_object('status','invalid'); end if;
  select array_agg(id order by id) into worker_ids from unnest(p_worker_run_ids) id;
  if exists (
    select 1 from unnest(worker_ids) requested(worker_id) where not exists (
      select 1 from public.external_agent_runs r
      join public.orchestration_worktrees w on w.id = r.worktree_id
      where r.id = requested.worker_id and r.user_id = p_user_id and r.repo_id = session_row.repo_id
        and w.user_id = p_user_id and w.run_id = session_row.orchestration_run_id
        and w.repo_id = session_row.repo_id
    )
  ) then return jsonb_build_object('status','not_found'); end if;
  select * into existing from public.control_continuations
    where session_id = p_session_id and parent_ai_call_id = p_parent_ai_call_id;
  if found then
    if existing.worker_run_ids <> worker_ids or existing.request_context <> p_request_context
      or existing.instruction <> p_instruction or existing.origin_message <> current_origin
    then return jsonb_build_object('status','conflict'); end if;
    return jsonb_build_object('status','ok','continuation',to_jsonb(existing),'replayed',true);
  end if;
  if exists (select 1 from public.external_agent_runs where id = any(worker_ids) and status = 'awaiting_input')
  then return jsonb_build_object('status','needs_input'); end if;
  if not exists (select 1 from public.external_agent_runs where id = any(worker_ids) and status in ('pending','streaming'))
  then return jsonb_build_object('status','already_finished'); end if;
  insert into public.control_continuations
    (user_id, session_id, parent_ai_call_id, origin_message, worker_run_ids, request_context, instruction)
    values (p_user_id,p_session_id,p_parent_ai_call_id,current_origin,worker_ids,p_request_context,p_instruction)
    returning * into existing;
  return jsonb_build_object('status','ok','continuation',to_jsonb(existing),'replayed',false);
end;
$$;


--
-- Name: control_save_messages(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_save_messages(p_user_id uuid, p_session_id uuid, p_messages jsonb, p_expected_messages jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  session_row public.control_sessions%rowtype;
  next_messages jsonb;
  incoming jsonb;
  existing jsonb;
  expected jsonb;
  message_position integer;
begin
  if jsonb_typeof(p_messages) is distinct from 'array'
     or jsonb_typeof(p_expected_messages) is distinct from 'array'
     or exists (
       select 1 from jsonb_array_elements(p_messages) m
       where jsonb_typeof(m->'id') is distinct from 'string'
          or btrim(m->>'id') = ''
          or coalesce(m->>'role', '') not in ('user', 'assistant', 'system')
          or jsonb_typeof(m->'parts') is distinct from 'array'
     ) or (select count(*) <> count(distinct m->>'id') from jsonb_array_elements(p_messages) m)
  then raise exception 'Invalid Control messages' using errcode = '22023'; end if;

  select * into session_row from public.control_sessions
    where id = p_session_id and user_id = p_user_id and archived = false
    for update;
  if not found then return jsonb_build_object('status', 'not_found'); end if;
  next_messages := session_row.messages;

  for incoming in select value from jsonb_array_elements(p_messages) loop
    existing := null;
    expected := null;
    select m.value, (m.ordinality - 1)::integer into existing, message_position
      from jsonb_array_elements(next_messages) with ordinality m
      where m.value->>'id' = incoming->>'id';
    select m into expected from jsonb_array_elements(p_expected_messages) m
      where m->>'id' = incoming->>'id';
    if existing is null then
      if expected is not null then return jsonb_build_object('status', 'conflict'); end if;
      next_messages := next_messages || jsonb_build_array(incoming);
    elsif existing = incoming then
      continue;
    elsif expected is not null then
      if existing <> expected then return jsonb_build_object('status', 'conflict'); end if;
      next_messages := jsonb_set(next_messages, array[message_position::text], incoming);
    end if;
    -- An older browser may append, but cannot overwrite a stored message.
  end loop;

  if next_messages is distinct from session_row.messages then
    update public.control_sessions set messages = next_messages, updated_at = clock_timestamp()
      where id = p_session_id and user_id = p_user_id
      returning * into session_row;
  end if;
  return jsonb_build_object('status', 'ok', 'session', to_jsonb(session_row));
end;
$$;


--
-- Name: control_supersede_continuations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_supersede_continuations() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  update public.control_continuations set status = 'cancelled',
    error = 'Superseded by a newer user request.', updated_at = clock_timestamp()
    where session_id = new.id and user_id = new.user_id
      and status in ('waiting','ready','running')
      and (new.archived or new.repo_id::text is distinct from request_context->>'repoId'
        or public.control_latest_user_message(new.messages) is distinct from origin_message);
  return new;
end;
$$;


--
-- Name: count_user_mcp_server_secrets(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_user_mcp_server_secrets(p_user_id uuid, p_secret_ids uuid[]) RETURNS bigint
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select count(*)::bigint
  from vault.secrets
  where id = any(coalesce(p_secret_ids, '{}'::uuid[]))
    and name like 'user_mcp_servers/' || p_user_id || '/%';
$$;


--
-- Name: create_orchestration_plan(uuid, uuid, text, text, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_orchestration_plan(p_run_id uuid, p_user_id uuid, p_objective text, p_context text, p_constraints text[], p_tasks jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_run public.orchestration_runs;
  v_task jsonb;
  v_spec_id uuid;
  v_task_row public.orchestration_tasks;
  v_spec_row public.orchestration_specs;
  v_created integer := 0;
  v_tasks jsonb := '[]'::jsonb;
  v_plan jsonb := jsonb_build_object('objective', p_objective,
    'context', coalesce(p_context, ''), 'constraints', coalesce(p_constraints, '{}'));
begin
  select * into v_run
  from public.orchestration_runs
  where id = p_run_id and user_id = p_user_id
  for update;

  if not found then
    raise exception 'mission not found';
  end if;

  insert into public.orchestration_specs
    (run_id, kind, slug, title, file_path, acceptance_criteria, prompt)
  values
    (v_run.id, 'master', 'master', v_run.title,
     'specs/' || v_run.slug || '/MASTER.md', coalesce(p_constraints, '{}'),
     concat_ws(E'\n\n', p_objective, nullif(p_context, '')))
  on conflict (run_id, slug) do nothing;

  for v_task in select value from jsonb_array_elements(p_tasks)
  loop
    select * into v_spec_row from public.orchestration_specs
    where run_id = p_run_id and slug = v_task->>'slug';
    if found then
      select * into v_task_row from public.orchestration_tasks
      where run_id = p_run_id and spec_id = v_spec_row.id;
      if not found or v_spec_row.kind <> 'task' or
        v_spec_row.title is distinct from v_task->>'title' or
        v_spec_row.prompt is distinct from v_task->>'prompt' or
        v_task_row.harness is distinct from v_task->>'harness' or
        (v_task_row.metadata ? 'plan' and v_task_row.metadata->'plan' is distinct from v_plan) or
        v_spec_row.owned_paths is distinct from array(select jsonb_array_elements_text(v_task->'ownedPaths')) or
        v_spec_row.blocked_paths is distinct from array(select jsonb_array_elements_text(v_task->'blockedPaths')) or
        v_spec_row.depends_on is distinct from array(select jsonb_array_elements_text(v_task->'dependsOn')) or
        v_spec_row.acceptance_criteria is distinct from array(select jsonb_array_elements_text(v_task->'acceptanceCriteria')) or
        v_spec_row.validation_commands is distinct from array(select jsonb_array_elements_text(v_task->'validationCommands')) then
        raise exception 'Task slug % already has different instructions. Use a new slug for new work.', v_task->>'slug';
      end if;
      v_tasks := v_tasks || jsonb_build_array(to_jsonb(v_task_row));
      continue;
    end if;
    insert into public.orchestration_specs
      (run_id, kind, order_index, slug, title, file_path, branch_name,
       owned_paths, blocked_paths, depends_on, acceptance_criteria,
       validation_commands, prompt)
    values
      (v_run.id, 'task', (v_task->>'orderIndex')::integer,
       v_task->>'slug', v_task->>'title', v_task->>'filePath',
       v_task->>'branchName',
       array(select jsonb_array_elements_text(v_task->'ownedPaths')),
       array(select jsonb_array_elements_text(v_task->'blockedPaths')),
       array(select jsonb_array_elements_text(v_task->'dependsOn')),
       array(select jsonb_array_elements_text(v_task->'acceptanceCriteria')),
       array(select jsonb_array_elements_text(v_task->'validationCommands')),
       v_task->>'prompt')
    returning id into v_spec_id;

    insert into public.orchestration_tasks
      (run_id, spec_id, repo_id, harness, branch_name, base_branch, metadata)
    values
      (v_run.id, v_spec_id, v_run.repo_id, v_task->>'harness',
       v_task->>'branchName', v_run.base_branch, jsonb_build_object('plan', v_plan))
    returning * into v_task_row;

    v_tasks := v_tasks || jsonb_build_array(to_jsonb(v_task_row));
    v_created := v_created + 1;
  end loop;

  if v_created > 0 then
  insert into public.orchestration_events
    (run_id, repo_id, type, message, metadata)
  values
    (v_run.id, v_run.repo_id, 'mission_planned',
     'Added ' || v_created || case when v_created = 1 then ' task' else ' tasks' end,
     jsonb_build_object(
       'plan', v_plan,
       'taskIds',
       (select coalesce(jsonb_agg(task->>'id'), '[]'::jsonb)
        from jsonb_array_elements(v_tasks) task)
     ));

  end if;
  return v_tasks;
end;
$$;


--
-- Name: create_user_mcp_server_secret(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_user_mcp_server_secret(p_user_id uuid, p_server_id uuid, p_slot text, p_secret text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_secret_id uuid;
begin
  select vault.create_secret(
    p_secret,
    'user_mcp_servers/' || p_user_id || '/' || p_server_id || '/' || p_slot,
    'MCP server secret for ' || p_slot
  ) into v_secret_id;

  return v_secret_id;
end;
$$;


