  where p.auth_user_id = auth.uid()
  limit 1
$$;


--
-- Name: custom_access_token_hook(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_access_token_hook(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  claims jsonb;
  oauth_client_id text;
  oauth_resource_url text;
begin
  claims := event -> 'claims';
  oauth_client_id := coalesce(
    event ->> 'client_id',
    claims ->> 'client_id',
    claims ->> 'azp'
  );

  if oauth_client_id is not null then
    select resource_url
    into oauth_resource_url
    from public.mcp_oauth_clients
    where client_id = oauth_client_id;
  end if;

  if oauth_resource_url is not null and claims is not null then
    claims := jsonb_set(
      claims,
      '{aud}',
      to_jsonb(oauth_resource_url),
      true
    );
    -- The verifier requires a client_id claim; write it explicitly rather
    -- than depending on Supabase including it in the final token.
    claims := jsonb_set(
      claims,
      '{client_id}',
      to_jsonb(oauth_client_id),
      true
    );
    event := jsonb_set(event, '{claims}', claims, true);
  end if;

  return event;
end;
$$;


--
-- Name: delete_agent_category_cascade(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_agent_category_cascade(p_user_id uuid, p_category_id uuid) RETURNS TABLE(deleted boolean, cleared_agents integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_slug text;
  v_cleared int := 0;
begin
  select slug into v_slug
  from public.agent_categories
  where id = p_category_id and user_id = p_user_id
  for update;

  if not found then
    return query select false, 0;
    return;
  end if;

  with cleared as (
    update public.agents
    set category = null
    where user_id = p_user_id and category = v_slug
    returning 1
  )
  select count(*)::int into v_cleared from cleared;

  delete from public.agent_categories
  where id = p_category_id and user_id = p_user_id;

  return query select true, v_cleared;
end;
$$;


--
-- Name: delete_flow_webhook_secret(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_flow_webhook_secret() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.vault_webhook_secret_id is not null then
    delete from vault.secrets where id = old.vault_webhook_secret_id;
  end if;
  return old;
end;
$$;


--
-- Name: delete_oauth_token(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_oauth_token(p_user_id uuid, p_provider text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_secret_id uuid;
begin
  select vault_secret_id into v_secret_id
  from public.oauth_tokens
  where user_id = p_user_id and provider = p_provider;

  if v_secret_id is not null then
    delete from vault.secrets where id = v_secret_id;
    delete from public.oauth_tokens where user_id = p_user_id and provider = p_provider;
  end if;
end;
$$;


--
-- Name: delete_provider_key(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_provider_key(p_user_id uuid, p_provider text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_secret_id UUID;
BEGIN
  SELECT vault_secret_id INTO v_secret_id
  FROM provider_keys
  WHERE user_id = p_user_id AND provider = p_provider;

  IF v_secret_id IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_secret_id;
    DELETE FROM provider_keys WHERE user_id = p_user_id AND provider = p_provider;
  END IF;
END;
$$;


--
-- Name: delete_slack_installation(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_slack_installation(p_team_id text, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_secret_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('slack_install', hashtext(p_team_id)));

  -- DELETE ... RETURNING locks and removes the row in one statement, so the
  -- secret id we read is the one actually attached to the row we deleted.
  delete from public.slack_installations
  where team_id = p_team_id and installed_by_user_id = p_user_id
  returning id, vault_bot_token_id into v_id, v_secret_id;

  if v_id is null then
    return false;
  end if;

  if v_secret_id is not null then
    delete from vault.secrets where id = v_secret_id;
  end if;

  return true;
end;
$$;


--
-- Name: delete_team_provider_key(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_team_provider_key(p_team_id uuid, p_provider text) RETURNS void
