    AS $$
declare
  v_secret_id uuid;
begin
  select vault_secret_id into v_secret_id
  from public.team_provider_keys
  where team_id = p_team_id and provider = p_provider;

  if v_secret_id is not null then
    delete from vault.secrets where id = v_secret_id;
    delete from public.team_provider_keys where team_id = p_team_id and provider = p_provider;
  end if;
end;
$$;


--
-- Name: delete_user_mcp_server_secret(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_user_mcp_server_secret(p_secret_id uuid) RETURNS void
