--
-- Name: deliver_slack_run_guidance(uuid, uuid, uuid, uuid[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deliver_slack_run_guidance(p_run_id uuid, p_user_id uuid, p_ai_call_id uuid, p_guidance_ids uuid[], p_step integer) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE selected_run public.external_agent_runs%ROWTYPE; delivered_count INTEGER;
BEGIN
  SELECT * INTO selected_run FROM public.external_agent_runs
    WHERE id = p_run_id AND user_id = p_user_id FOR UPDATE;
  IF NOT FOUND OR selected_run.ai_call_id IS DISTINCT FROM p_ai_call_id
     OR selected_run.status NOT IN ('pending', 'streaming')
  THEN RETURN 0; END IF;
  UPDATE public.slack_run_guidance SET status = 'delivered', delivered_step = p_step, updated_at = now()
    WHERE run_id = p_run_id AND user_id = p_user_id AND ai_call_id = p_ai_call_id
      AND id = ANY(p_guidance_ids) AND status = 'received';
  GET DIAGNOSTICS delivered_count = ROW_COUNT;
  IF delivered_count > 0 THEN
    UPDATE public.external_agent_runs SET slack_progress_revision = slack_progress_revision + 1
      WHERE id = p_run_id AND user_id = p_user_id;
  END IF;
  RETURN delivered_count;
END;
$$;


--
-- Name: enforce_assignment_agent_ownership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_assignment_agent_ownership() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  repo_owner uuid;
  agent_owner uuid;
BEGIN
  IF NEW.repo_id IS NULL OR NEW.agent_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT user_id INTO repo_owner
  FROM public.repos
  WHERE id = NEW.repo_id;

  SELECT user_id INTO agent_owner
  FROM public.agents
  WHERE id = NEW.agent_id;

  IF repo_owner IS NULL OR agent_owner IS NULL THEN
    RETURN NEW;
  END IF;

  IF repo_owner <> agent_owner THEN
    RAISE EXCEPTION 'Assignment agent must belong to the same user as the repo'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_trigger_agent_ownership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_trigger_agent_ownership() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  agent_owner uuid;
BEGIN
  IF NEW.user_id IS NULL OR NEW.agent_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT user_id INTO agent_owner
  FROM public.agents
  WHERE id = NEW.agent_id;

  IF agent_owner IS NULL THEN
    RETURN NEW;
  END IF;

  IF agent_owner <> NEW.user_id THEN
    RAISE EXCEPTION 'Trigger agent must belong to the same user as the trigger owner'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enqueue_automation_job_run(uuid, uuid, uuid, uuid, uuid, bigint, text, text, text, jsonb, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_automation_job_run(p_user_id uuid, p_assignment_id uuid DEFAULT NULL::uuid, p_trigger_id uuid DEFAULT NULL::uuid, p_retry_of_job_run_id uuid DEFAULT NULL::uuid, p_repo_id uuid DEFAULT NULL::uuid, p_installation_id bigint DEFAULT NULL::bigint, p_source_kind text DEFAULT 'assignment'::text, p_source_type text DEFAULT 'unknown'::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_duplicate_sensitive boolean DEFAULT false, p_max_active_per_repo integer DEFAULT 25, p_max_active_per_installation integer DEFAULT 100) RETURNS TABLE(job_run_id uuid, outcome text, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job_run_id UUID;
  v_repo_active INT := 0;
  v_installation_active INT := 0;
  v_duplicate_exists BOOLEAN := FALSE;
BEGIN
  IF p_source_kind NOT IN ('assignment', 'trigger', 'manual_retry') THEN
    RAISE EXCEPTION 'Invalid source_kind: %', p_source_kind;
  END IF;

  IF p_repo_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext('enqueue_repo:' || p_repo_id::text));
  END IF;

  IF p_installation_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext('enqueue_installation:' || p_installation_id::text));
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT jr.id
    INTO v_job_run_id
    FROM public.job_runs jr
    WHERE jr.idempotency_key = p_idempotency_key
    LIMIT 1;

    IF v_job_run_id IS NOT NULL THEN
      INSERT INTO public.automation_dispatch_events (
        user_id, job_run_id, assignment_id, trigger_id, repo_id, installation_id,
        source_kind, source_type, event_kind, outcome, reason, metadata
      ) VALUES (
        p_user_id, v_job_run_id, p_assignment_id, p_trigger_id, p_repo_id, p_installation_id,
        p_source_kind, p_source_type, 'enqueue', 'suppressed', 'IDEMPOTENT_DUPLICATE', COALESCE(p_metadata, '{}'::jsonb)
      );

      RETURN QUERY SELECT v_job_run_id, 'suppressed'::TEXT, 'IDEMPOTENT_DUPLICATE'::TEXT;
      RETURN;
    END IF;
  END IF;

  IF p_duplicate_sensitive THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.job_runs jr
      LEFT JOIN public.assignments a
        ON a.id = jr.assignment_id
      LEFT JOIN public.repos r
        ON r.id = a.repo_id
      WHERE jr.status IN ('pending', 'running')
        AND (
          (p_assignment_id IS NOT NULL AND jr.assignment_id = p_assignment_id)
          OR (p_trigger_id IS NOT NULL AND jr.trigger_id = p_trigger_id)
        )
        AND COALESCE(NULLIF(jr.metadata->>'source_type', ''), '') = p_source_type
        AND (
          p_repo_id IS NULL
          OR COALESCE(r.id, NULLIF(jr.metadata->>'repo_id', '')::UUID) IS NOT DISTINCT FROM p_repo_id
        )
    ) INTO v_duplicate_exists;

    IF v_duplicate_exists THEN
      INSERT INTO public.automation_dispatch_events (
        user_id, assignment_id, trigger_id, repo_id, installation_id,
        source_kind, source_type, event_kind, outcome, reason, metadata
      ) VALUES (
        p_user_id, p_assignment_id, p_trigger_id, p_repo_id, p_installation_id,
        p_source_kind, p_source_type, 'enqueue', 'suppressed', 'ACTIVE_DUPLICATE', COALESCE(p_metadata, '{}'::jsonb)
      );

      RETURN QUERY SELECT NULL::UUID, 'suppressed'::TEXT, 'ACTIVE_DUPLICATE'::TEXT;
      RETURN;
    END IF;
  END IF;

  IF p_repo_id IS NOT NULL THEN
    SELECT COUNT(*)
    INTO v_repo_active
    FROM public.job_runs jr
    LEFT JOIN public.assignments a
      ON a.id = jr.assignment_id
    LEFT JOIN public.repos r
      ON r.id = a.repo_id
    WHERE jr.status IN ('pending', 'running')
      AND COALESCE(r.id, NULLIF(jr.metadata->>'repo_id', '')::UUID) = p_repo_id;

    IF v_repo_active >= p_max_active_per_repo THEN
      INSERT INTO public.automation_dispatch_events (
        user_id, assignment_id, trigger_id, repo_id, installation_id,
        source_kind, source_type, event_kind, outcome, reason, metadata
      ) VALUES (
        p_user_id, p_assignment_id, p_trigger_id, p_repo_id, p_installation_id,
        p_source_kind, p_source_type, 'enqueue', 'suppressed', 'REPO_PENDING_LIMIT', COALESCE(p_metadata, '{}'::jsonb)
      );

      RETURN QUERY SELECT NULL::UUID, 'suppressed'::TEXT, 'REPO_PENDING_LIMIT'::TEXT;
      RETURN;
    END IF;
  END IF;

  IF p_installation_id IS NOT NULL THEN
    SELECT COUNT(*)
    INTO v_installation_active
    FROM public.job_runs jr
    LEFT JOIN public.assignments a
      ON a.id = jr.assignment_id
    LEFT JOIN public.repos r
      ON r.id = a.repo_id
    LEFT JOIN public.triggers t
      ON t.id = jr.trigger_id
    WHERE jr.status IN ('pending', 'running')
      AND COALESCE(
        t.installation_id::BIGINT,
        r.github_installation_id::BIGINT,
        NULLIF(jr.metadata->>'installation_id', '')::BIGINT
      ) = p_installation_id;

    IF v_installation_active >= p_max_active_per_installation THEN
      INSERT INTO public.automation_dispatch_events (
        user_id, assignment_id, trigger_id, repo_id, installation_id,
        source_kind, source_type, event_kind, outcome, reason, metadata
      ) VALUES (
        p_user_id, p_assignment_id, p_trigger_id, p_repo_id, p_installation_id,
        p_source_kind, p_source_type, 'enqueue', 'suppressed', 'INSTALLATION_PENDING_LIMIT', COALESCE(p_metadata, '{}'::jsonb)
      );

      RETURN QUERY SELECT NULL::UUID, 'suppressed'::TEXT, 'INSTALLATION_PENDING_LIMIT'::TEXT;
      RETURN;
    END IF;
  END IF;

      INSERT INTO public.job_runs (
        assignment_id,
        trigger_id,
        retry_of_job_run_id,
        status,
        metadata,
        idempotency_key
      ) VALUES (
        p_assignment_id,
        p_trigger_id,
        p_retry_of_job_run_id,
        'pending',
        COALESCE(p_metadata, '{}'::jsonb),
        p_idempotency_key
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_job_run_id;

  IF v_job_run_id IS NULL THEN
    SELECT jr.id
    INTO v_job_run_id
    FROM public.job_runs jr
    WHERE jr.idempotency_key = p_idempotency_key
    LIMIT 1;

    INSERT INTO public.automation_dispatch_events (
      user_id, job_run_id, assignment_id, trigger_id, repo_id, installation_id,
      source_kind, source_type, event_kind, outcome, reason, metadata
    ) VALUES (
      p_user_id, v_job_run_id, p_assignment_id, p_trigger_id, p_repo_id, p_installation_id,
      p_source_kind, p_source_type, 'enqueue', 'suppressed', 'IDEMPOTENT_DUPLICATE', COALESCE(p_metadata, '{}'::jsonb)
    );

    RETURN QUERY SELECT v_job_run_id, 'suppressed'::TEXT, 'IDEMPOTENT_DUPLICATE'::TEXT;
    RETURN;
  END IF;

  INSERT INTO public.automation_dispatch_events (
    user_id, job_run_id, assignment_id, trigger_id, repo_id, installation_id,
    source_kind, source_type, event_kind, outcome, metadata
  ) VALUES (
    p_user_id, v_job_run_id, p_assignment_id, p_trigger_id, p_repo_id, p_installation_id,
    p_source_kind, p_source_type, 'enqueue', 'queued', COALESCE(p_metadata, '{}'::jsonb)
  );

  RETURN QUERY SELECT v_job_run_id, 'queued'::TEXT, NULL::TEXT;
END;
$$;


--
-- Name: enqueue_automation_job_run(uuid, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, text, text, jsonb, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_automation_job_run(p_user_id uuid, p_assignment_id uuid DEFAULT NULL::uuid, p_trigger_id uuid DEFAULT NULL::uuid, p_retry_of_job_run_id uuid DEFAULT NULL::uuid, p_flow_id uuid DEFAULT NULL::uuid, p_flow_version_id uuid DEFAULT NULL::uuid, p_repo_id uuid DEFAULT NULL::uuid, p_installation_id bigint DEFAULT NULL::bigint, p_source_kind text DEFAULT 'assignment'::text, p_source_type text DEFAULT 'unknown'::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_duplicate_sensitive boolean DEFAULT false, p_max_active_per_repo integer DEFAULT 25, p_max_active_per_installation integer DEFAULT 100) RETURNS TABLE(job_run_id uuid, outcome text, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job_run_id UUID;
  v_repo_active INT := 0;
  v_installation_active INT := 0;
  v_duplicate_exists BOOLEAN := FALSE;
BEGIN
  IF p_source_kind NOT IN ('assignment', 'trigger', 'flow', 'manual_retry') THEN
    RAISE EXCEPTION 'Invalid source_kind: %', p_source_kind;
  END IF;

  IF p_repo_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext('enqueue_repo:' || p_repo_id::text));
  END IF;

  IF p_installation_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext('enqueue_installation:' || p_installation_id::text));
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT jr.id
    INTO v_job_run_id
    FROM public.job_runs jr
    WHERE jr.idempotency_key = p_idempotency_key
    LIMIT 1;

    IF v_job_run_id IS NOT NULL THEN
      INSERT INTO public.automation_dispatch_events (
        user_id, job_run_id, assignment_id, trigger_id, flow_id, flow_version_id, repo_id, installation_id,
        source_kind, source_type, event_kind, outcome, reason, metadata
      ) VALUES (
        p_user_id, v_job_run_id, p_assignment_id, p_trigger_id, p_flow_id, p_flow_version_id, p_repo_id, p_installation_id,
        p_source_kind, p_source_type, 'enqueue', 'suppressed', 'IDEMPOTENT_DUPLICATE', COALESCE(p_metadata, '{}'::jsonb)
      );

      RETURN QUERY SELECT v_job_run_id, 'suppressed'::TEXT, 'IDEMPOTENT_DUPLICATE'::TEXT;
      RETURN;
    END IF;
  END IF;

  IF p_duplicate_sensitive THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.job_runs jr
      LEFT JOIN public.assignments a
        ON a.id = jr.assignment_id
      LEFT JOIN public.repos r
        ON r.id = a.repo_id
      WHERE jr.status IN ('pending', 'running')
        AND (
          (p_assignment_id IS NOT NULL AND jr.assignment_id = p_assignment_id)
          OR (p_trigger_id IS NOT NULL AND jr.trigger_id = p_trigger_id)
          OR (p_flow_id IS NOT NULL AND jr.flow_id = p_flow_id)
        )
        AND COALESCE(NULLIF(jr.metadata->>'source_type', ''), '') = p_source_type
        AND (
          p_repo_id IS NULL
          OR COALESCE(r.id, NULLIF(jr.metadata->>'repo_id', '')::UUID) IS NOT DISTINCT FROM p_repo_id
        )
    ) INTO v_duplicate_exists;

    IF v_duplicate_exists THEN
      INSERT INTO public.automation_dispatch_events (
        user_id, assignment_id, trigger_id, flow_id, flow_version_id, repo_id, installation_id,
        source_kind, source_type, event_kind, outcome, reason, metadata
      ) VALUES (
        p_user_id, p_assignment_id, p_trigger_id, p_flow_id, p_flow_version_id, p_repo_id, p_installation_id,
        p_source_kind, p_source_type, 'enqueue', 'suppressed', 'ACTIVE_DUPLICATE', COALESCE(p_metadata, '{}'::jsonb)
      );

      RETURN QUERY SELECT NULL::UUID, 'suppressed'::TEXT, 'ACTIVE_DUPLICATE'::TEXT;
      RETURN;
    END IF;
  END IF;

  IF p_repo_id IS NOT NULL THEN
    SELECT COUNT(*)
    INTO v_repo_active
    FROM public.job_runs jr
    LEFT JOIN public.assignments a
      ON a.id = jr.assignment_id
    LEFT JOIN public.repos r
      ON r.id = a.repo_id
    WHERE jr.status IN ('pending', 'running')
      AND COALESCE(r.id, NULLIF(jr.metadata->>'repo_id', '')::UUID) = p_repo_id;

    IF v_repo_active >= p_max_active_per_repo THEN
      INSERT INTO public.automation_dispatch_events (
        user_id, assignment_id, trigger_id, flow_id, flow_version_id, repo_id, installation_id,
        source_kind, source_type, event_kind, outcome, reason, metadata
      ) VALUES (
        p_user_id, p_assignment_id, p_trigger_id, p_flow_id, p_flow_version_id, p_repo_id, p_installation_id,
        p_source_kind, p_source_type, 'enqueue', 'suppressed', 'REPO_PENDING_LIMIT', COALESCE(p_metadata, '{}'::jsonb)
      );

      RETURN QUERY SELECT NULL::UUID, 'suppressed'::TEXT, 'REPO_PENDING_LIMIT'::TEXT;
      RETURN;
    END IF;
  END IF;

  IF p_installation_id IS NOT NULL THEN
    SELECT COUNT(*)
    INTO v_installation_active
    FROM public.job_runs jr
    LEFT JOIN public.assignments a
      ON a.id = jr.assignment_id
    LEFT JOIN public.repos r
      ON r.id = a.repo_id
    LEFT JOIN public.triggers t
      ON t.id = jr.trigger_id
    WHERE jr.status IN ('pending', 'running')
      AND COALESCE(
        t.installation_id::BIGINT,
        r.github_installation_id::BIGINT,
        NULLIF(jr.metadata->>'installation_id', '')::BIGINT
      ) = p_installation_id;

    IF v_installation_active >= p_max_active_per_installation THEN
      INSERT INTO public.automation_dispatch_events (
        user_id, assignment_id, trigger_id, flow_id, flow_version_id, repo_id, installation_id,
        source_kind, source_type, event_kind, outcome, reason, metadata
      ) VALUES (
        p_user_id, p_assignment_id, p_trigger_id, p_flow_id, p_flow_version_id, p_repo_id, p_installation_id,
        p_source_kind, p_source_type, 'enqueue', 'suppressed', 'INSTALLATION_PENDING_LIMIT', COALESCE(p_metadata, '{}'::jsonb)
      );

      RETURN QUERY SELECT NULL::UUID, 'suppressed'::TEXT, 'INSTALLATION_PENDING_LIMIT'::TEXT;
      RETURN;
    END IF;
  END IF;

  INSERT INTO public.job_runs (
    assignment_id,
    trigger_id,
    retry_of_job_run_id,
    flow_id,
    flow_version_id,
    status,
    metadata,
    idempotency_key
  ) VALUES (
    p_assignment_id,
    p_trigger_id,
    p_retry_of_job_run_id,
    p_flow_id,
    p_flow_version_id,
    'pending',
    COALESCE(p_metadata, '{}'::jsonb),
    p_idempotency_key
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_job_run_id;

  IF v_job_run_id IS NULL THEN
    SELECT jr.id
    INTO v_job_run_id
    FROM public.job_runs jr
    WHERE jr.idempotency_key = p_idempotency_key
    LIMIT 1;

    INSERT INTO public.automation_dispatch_events (
      user_id, job_run_id, assignment_id, trigger_id, flow_id, flow_version_id, repo_id, installation_id,
      source_kind, source_type, event_kind, outcome, reason, metadata
    ) VALUES (
      p_user_id, v_job_run_id, p_assignment_id, p_trigger_id, p_flow_id, p_flow_version_id, p_repo_id, p_installation_id,
      p_source_kind, p_source_type, 'enqueue', 'suppressed', 'IDEMPOTENT_DUPLICATE', COALESCE(p_metadata, '{}'::jsonb)
    );

    RETURN QUERY SELECT v_job_run_id, 'suppressed'::TEXT, 'IDEMPOTENT_DUPLICATE'::TEXT;
    RETURN;
  END IF;

  INSERT INTO public.automation_dispatch_events (
    user_id, job_run_id, assignment_id, trigger_id, flow_id, flow_version_id, repo_id, installation_id,
    source_kind, source_type, event_kind, outcome, metadata
  ) VALUES (
    p_user_id, v_job_run_id, p_assignment_id, p_trigger_id, p_flow_id, p_flow_version_id, p_repo_id, p_installation_id,
    p_source_kind, p_source_type, 'enqueue', 'queued', COALESCE(p_metadata, '{}'::jsonb)
  );

  RETURN QUERY SELECT v_job_run_id, 'queued'::TEXT, NULL::TEXT;
END;
$$;


--
-- Name: expire_billing_included_credit(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_billing_included_credit(p_account uuid, p_source_ref text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
  v_included bigint;
begin
  perform 1 from public.billing_accounts where id = p_account for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;

  select coalesce(sum(delta_cents), 0)::bigint
    into v_included
  from public.credit_ledger
  where account_id = p_account and bucket = 'included';

  -- Even a zero-dollar expiry row is the once-per-subscription marker: its
  -- source_ref conflict prevents webhook redelivery from advancing the
  -- Checkout generation again.
  insert into public.credit_ledger
    (account_id, delta_cents, bucket, kind, source_ref)
  values
    (p_account, -greatest(v_included, 0), 'included', 'grant_expiry', p_source_ref)
  on conflict (source_ref) do nothing;

  if not found then
    return 0;
  end if;

  update public.billing_accounts
  set subscription_checkout_generation = subscription_checkout_generation + 1,
      updated_at = now()
  where id = p_account;

  return greatest(v_included, 0);
end;
$$;


