--
-- Name: finalize_sandbox_billing_session_unmetered(uuid, timestamp with time zone, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_sandbox_billing_session_unmetered(p_session uuid, p_ended_at timestamp with time zone, p_close_generation bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
begin
  update public.sandbox_billing_sessions
  set state = 'closed_unmetered',
      ended_at = greatest(p_ended_at, started_at, metered_through_at),
      updated_at = now()
  where id = p_session
    and state = 'closing'
    and close_generation = p_close_generation;
  return found;
end;
$$;


--
-- Name: get_flow_webhook_secret(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_flow_webhook_secret(p_flow_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_secret_id uuid;
  v_secret text;
begin
  select vault_webhook_secret_id into v_secret_id
  from public.flows
  where id = p_flow_id;

  if v_secret_id is null then
    return null;
  end if;

  select decrypted_secret into v_secret
  from vault.decrypted_secrets
  where id = v_secret_id;

  return v_secret;
end;
$$;


