--
-- Name: is_valid_scope_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_valid_scope_slug(p_slug text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select p_slug ~ '^[a-z0-9](?:[a-z0-9]|-(?=[a-z0-9])){0,38}$';
$_$;


--
-- Name: list_unmetered_platform_sandboxes(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_unmetered_platform_sandboxes(p_limit integer DEFAULT 250) RETURNS TABLE(id uuid, sandbox_id text, billing_source text, actor_user_id uuid, user_id uuid, product_team_id uuid, status text)
    LANGUAGE sql
    AS $$
  with candidates as materialized (
    select s.id
    from public.sandboxes s
    where s.billing_source = 'platform'
      and s.status::text in (
        'creating', 'installing', 'running', 'pausing', 'paused', 'error'
      )
      and s.sandbox_id <> 'pending'
      and not exists (
        select 1
        from public.sandbox_billing_sessions b
        where b.sandbox_record_id = s.id
          and b.state in ('open', 'closing')
      )
    order by
      s.sandbox_billing_recovery_checked_at asc nulls first,
      s.last_active_at desc nulls last,
      s.id
    limit least(greatest(coalesce(p_limit, 250), 1), 1000)
  )
  update public.sandboxes s
  set sandbox_billing_recovery_checked_at = now()
  from candidates c
  where s.id = c.id
  returning
    s.id,
    s.sandbox_id,
    s.billing_source::text,
    s.actor_user_id,
    s.user_id,
    s.product_team_id,
    s.status::text
$$;


--
-- Name: match_memories(public.vector, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_memories(query_embedding public.vector, match_user_id uuid, match_lane text DEFAULT NULL::text, match_count integer DEFAULT 20) RETURNS TABLE(id uuid, lane text, content text, metadata jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, similarity double precision)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    m.id,
    m.lane,
    m.content,
    m.metadata,
    m.created_at,
    m.updated_at,
    (1 - (m.embedding <=> query_embedding))::double precision as similarity
  from public.memories m
  where m.user_id = match_user_id
    and (match_lane is null or m.lane = match_lane)
    and m.embedding is not null
  order by m.embedding <=> query_embedding
  limit least(coalesce(match_count, 20), 100);
$$;


