    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: ai_calls; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_calls (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    type text NOT NULL,
    model text NOT NULL,
    input_tokens integer,
    output_tokens integer,
    total_tokens integer GENERATED ALWAYS AS ((COALESCE(input_tokens, 0) + COALESCE(output_tokens, 0))) STORED,
    duration_ms integer,
    started_at timestamp with time zone DEFAULT now(),
    completed_at timestamp with time zone,
    status text DEFAULT 'pending'::text NOT NULL,
    error text,
    conversation_id text,
    job_run_id uuid,
    repo_id uuid,
    tool_calls_count integer DEFAULT 0,
    tool_calls jsonb DEFAULT '[]'::jsonb,
    metadata jsonb DEFAULT '{}'::jsonb,
    runtime_command_id text,
    cancel_requested_at timestamp with time zone,
    control_state text DEFAULT 'active'::text NOT NULL,
    limit_claim_id uuid,
    cost_usd numeric(14,8),
    cache_read_input_tokens integer,
    cache_creation_input_tokens integer,
    reasoning_tokens integer,
    gateway_generation_id text,
    cost_source text,
    gateway_generation_ids text[],
    CONSTRAINT ai_calls_control_state_check CHECK ((control_state = ANY (ARRAY['active'::text, 'cancel_requested'::text, 'cancelled'::text]))),
    CONSTRAINT ai_calls_cost_source_check CHECK ((cost_source = ANY (ARRAY['trigger'::text, 'gateway'::text, 'manual'::text]))),
    CONSTRAINT ai_calls_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'streaming'::text, 'success'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT ai_calls_type_check CHECK ((type = ANY (ARRAY['chat'::text, 'pr_review'::text, 'cron_refactor'::text, 'cron'::text, 'agent'::text, 'push_review'::text, 'issue_triage'::text, 'ci_failure'::text, 'mention'::text, 'pr_comment'::text, 'issue_comment'::text, 'labeled'::text, 'tag_push'::text])))
);


--
-- Name: COLUMN ai_calls.reasoning_tokens; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ai_calls.reasoning_tokens IS 'Capture-only; never included in cost_usd. NULL = model did not report this token class (not a billing gap).';


--
-- Name: COLUMN ai_calls.cost_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ai_calls.cost_source IS 'Who last wrote cost_usd: trigger (computed by compute_ai_call_cost), gateway (W7 reconciliation from Vercel billing), or manual (operator override). The compute trigger fires on writes to input_tokens, output_tokens, model, cache_read_input_tokens, cache_creation_input_tokens, cost_source, or cost_usd, short-circuits when cost_source IN (''gateway'', ''manual''), and stamps cost_source=''trigger'' even when the computed cost is NULL because no tokens or no pricing are available. Manual overrides persist across later token updates until cost_source is changed away from ''manual''. Direct cost_usd writes on cost_source=''trigger'' rows are rejected unless a pricing input changes; set cost_source=''manual'' in the same UPDATE for operator overrides. A separate guard (trg_ai_calls_zz_gateway_guard) blocks writes to already gateway-owned rows that leave cost_source=''gateway'' while changing cost_usd unless gateway_generation_id is also changing (W7 refresh); the guard also fires on gateway_generation_id so W7 refresh statements are visible to it. Initial W7 claims from cost_source IS DISTINCT FROM ''gateway'' remain allowed. Changing cost_source to ''manual'' releases gateway ownership and preserves the caller cost_usd; changing it to ''trigger'' releases gateway ownership and recomputes cost_usd from tokens.';


--
-- Name: COLUMN ai_calls.gateway_generation_ids; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ai_calls.gateway_generation_ids IS 'All Vercel AI Gateway generation IDs captured across tool-loop steps. Used by W7/W11 reconciliation to sum cost across all steps. The singleton gateway_generation_id column holds the first ID for backward compatibility.';


--
-- Name: merge_ai_call_metadata(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_ai_call_metadata(p_user_id uuid, p_ai_call_id uuid, p_metadata_patch jsonb) RETURNS SETOF public.ai_calls
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE public.ai_calls ac
  SET metadata = COALESCE(ac.metadata, '{}'::jsonb) || COALESCE(p_metadata_patch, '{}'::jsonb)
  WHERE ac.id = p_ai_call_id
    AND ac.user_id = p_user_id
  RETURNING ac.*;
END;
$$;


--
-- Name: mint_waitlist_replacement_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mint_waitlist_replacement_code(p_email text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id UUID;
  v_code    TEXT;
  v_note    TEXT;
BEGIN
  SELECT id INTO v_user_id
  FROM auth.users
  WHERE lower(email) = lower(p_email)
  LIMIT 1;

  IF v_user_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_note := 'replacement for ' || lower(p_email);

  -- Cap live replacement codes at one per email. Without this, a caller who
  -- can defeat the per-IP rate limit (e.g. by landing in the shared "unknown"
  -- XFF bucket or rotating IPs) can stockpile live single-use codes for a
  -- target address. Expiring instead of deleting preserves the audit row.
  UPDATE public.waitlist_codes
  SET    expires_at = NOW()
  WHERE  note = v_note
    AND  expires_at > NOW();

  v_code := 'r-' || encode(gen_random_bytes(8), 'hex');

  INSERT INTO public.waitlist_codes (code, note, max_uses, expires_at)
  VALUES (
    v_code,
    v_note,
    1,
    NOW() + INTERVAL '24 hours'
  );

  RETURN v_code;
END;
$$;


--
-- Name: FUNCTION mint_waitlist_replacement_code(p_email text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mint_waitlist_replacement_code(p_email text) IS 'Mint a single-use 24h replacement waitlist code for an existing auth user, or return NULL if the email is unknown. Expires any prior live replacement codes for the same email before minting. Service role only — any migration that recreates this function MUST re-apply the REVOKE/GRANT below it, because CREATE OR REPLACE does not reset privileges.';


--
-- Name: mogplex_notify_table_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mogplex_notify_table_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform pg_notify(
    'mogplex_table_events',
    json_build_object(
      'table', TG_TABLE_NAME,
      'op', TG_OP,
      'user_id', coalesce(to_jsonb(NEW) ->> 'user_id', to_jsonb(OLD) ->> 'user_id'),
      'id', coalesce(to_jsonb(NEW) ->> 'id', to_jsonb(OLD) ->> 'id'),
      'ai_call_id', coalesce(to_jsonb(NEW) ->> 'ai_call_id', to_jsonb(OLD) ->> 'ai_call_id')
    )::text
  );
  return coalesce(NEW, OLD);
end;
$$;


--
-- Name: notify_billing_account_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_billing_account_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform pg_catalog.pg_notify(
    'mogplex_billing_account_events',
    pg_catalog.json_build_object(
      'accountId', new.account_id,
      'sequence', new.sequence::text
    )::text
  );
  return new;
end;
$$;


--
-- Name: observability_job_run_stats(uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.observability_job_run_stats(p_user_id uuid, p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_now timestamp with time zone, p_repairable_before timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with owned_run_ids as materialized (
  select jr.id
  from public.job_runs jr
  join public.assignments a on a.id = jr.assignment_id
  join public.repos r on r.id = a.repo_id
  where r.user_id = p_user_id

  union

  select jr.id
  from public.job_runs jr
  join public.triggers t on t.id = jr.trigger_id
  where t.user_id = p_user_id

  union

  select jr.id
  from public.job_runs jr
  join public.flows f on f.id = jr.flow_id
  where f.user_id = p_user_id
),
scoped_runs as materialized (
  select
    jr.status,
    jr.created_at,
    jr.started_at,
    jr.completed_at,
    jr.last_start_attempt_at,
    jr.last_start_source
  from public.job_runs jr
  join owned_run_ids owned on owned.id = jr.id
),
totals as (
  select
    count(*)::bigint as total,
    count(*) filter (where status = 'running')::bigint as running,
    count(*) filter (where status = 'pending')::bigint as pending,
    count(*) filter (
      where status = 'pending'
        and (
          coalesce(last_start_attempt_at, created_at, started_at) <=
            p_repairable_before
          or coalesce(last_start_attempt_at, created_at, started_at) is null
        )
    )::bigint as repairable_pending,
    count(*) filter (
      where status = 'failed'
        and coalesce(started_at, created_at) >= p_window_start
        and coalesce(started_at, created_at) <= p_window_end
    )::bigint as failed_in_range,
    count(*) filter (
      where last_start_source = 'repair'
        and last_start_attempt_at >= p_window_start
        and last_start_attempt_at <= p_window_end
    )::bigint as repaired_in_range,
    count(*) filter (
      where status in ('success', 'failed')
        and coalesce(completed_at, started_at, created_at) >= p_window_start
        and coalesce(completed_at, started_at, created_at) <= p_window_end
    )::bigint as concluded_in_range,
    count(*) filter (
      where status = 'success'
        and coalesce(completed_at, started_at, created_at) >= p_window_start
        and coalesce(completed_at, started_at, created_at) <= p_window_end
    )::bigint as successful_in_range,
    coalesce(
      round(
        extract(epoch from (
          p_now - min(coalesce(last_start_attempt_at, created_at, started_at))
            filter (where status = 'pending')
        )) * 1000
      ),
      0
    )::bigint as oldest_pending_age_ms
  from scoped_runs
)
select jsonb_build_object(
  'total', total,
  'running', running,
  'pending', pending,
  'repairable_pending', repairable_pending,
  'failed_in_range', failed_in_range,
  'repaired_in_range', repaired_in_range,
  'concluded_in_range', concluded_in_range,
  'successful_in_range', successful_in_range,
  'oldest_pending_age_ms', oldest_pending_age_ms
)
from totals;
$$;


--
-- Name: observability_stats_snapshot(uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.observability_stats_snapshot(p_user_id uuid, p_calls_from timestamp with time zone, p_calls_to timestamp with time zone, p_today_start timestamp with time zone, p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_now timestamp with time zone, p_reconciliation_stale_before timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
WITH call_rows AS (
  SELECT
    -- Mirrors readObservedTokenTotal in the stats route: prefer the token
    -- breakdown when any component is present, else fall back to the total.
    CASE WHEN input_tokens IS NOT NULL
           OR output_tokens IS NOT NULL
           OR cache_read_input_tokens IS NOT NULL
           OR cache_creation_input_tokens IS NOT NULL
      THEN COALESCE(input_tokens, 0)
           + COALESCE(cache_read_input_tokens, 0)
           + COALESCE(cache_creation_input_tokens, 0)
           + COALESCE(output_tokens, 0)
      ELSE COALESCE(total_tokens, 0)
    END AS observed_tokens,
    duration_ms,
    status,
    model,
    type,
    cost_usd
  FROM ai_calls
  WHERE user_id = p_user_id
    AND (p_calls_from IS NULL OR started_at >= p_calls_from)
    AND (p_calls_to IS NULL OR started_at <= p_calls_to)
),
call_totals AS (
  SELECT
    COUNT(*)::bigint AS total_calls,
    COALESCE(SUM(observed_tokens), 0)::bigint AS total_tokens,
    COUNT(*) FILTER (WHERE status = 'success')::bigint AS success_calls,
    AVG(duration_ms) AS avg_duration_ms,
    COALESCE(SUM(cost_usd) FILTER (WHERE cost_usd IS NOT NULL), 0) AS known_cost_usd
  FROM call_rows
),
by_model AS (
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object('model', model, 'count', cnt, 'tokens', tokens)
      ORDER BY cnt DESC
    ),
    '[]'::jsonb
  ) AS v
  FROM (
    SELECT model, COUNT(*)::bigint AS cnt,
           COALESCE(SUM(observed_tokens), 0)::bigint AS tokens
    FROM call_rows
    GROUP BY model
  ) grouped
),
by_type AS (
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object('type', type, 'count', cnt)
      ORDER BY cnt DESC
    ),
    '[]'::jsonb
  ) AS v
  FROM (
    SELECT type, COUNT(*)::bigint AS cnt
    FROM call_rows
    GROUP BY type
  ) grouped
),
today AS (
  SELECT
    COUNT(*)::bigint AS calls,
    COALESCE(SUM(
      CASE WHEN input_tokens IS NOT NULL
             OR output_tokens IS NOT NULL
             OR cache_read_input_tokens IS NOT NULL
             OR cache_creation_input_tokens IS NOT NULL
        THEN COALESCE(input_tokens, 0)
             + COALESCE(cache_read_input_tokens, 0)
             + COALESCE(cache_creation_input_tokens, 0)
             + COALESCE(output_tokens, 0)
        ELSE COALESCE(total_tokens, 0)
      END
    ), 0)::bigint AS tokens,
    COALESCE(SUM(cost_usd) FILTER (WHERE cost_usd IS NOT NULL), 0) AS known_cost_usd
  FROM ai_calls
  WHERE user_id = p_user_id
    AND started_at >= p_today_start
),
sandbox AS (
  SELECT
    COUNT(*)::bigint AS total,
    COUNT(*) FILTER (WHERE status = 'running')::bigint AS active,
    -- Only the slice of each sandbox's lifetime that overlaps the selected
    -- window counts, so long-lived sandboxes don't dominate narrow ranges.
    COALESCE(SUM(GREATEST(0, EXTRACT(EPOCH FROM (
      LEAST(
        CASE WHEN status = 'running' THEN p_now
             ELSE COALESCE(last_active_at, created_at)
        END,
        COALESCE(p_window_end, p_now)
      )
      - GREATEST(created_at, p_window_start)
    )) * 1000)), 0)::bigint AS window_time_ms
  FROM sandboxes
  WHERE user_id = p_user_id
),
dispatch AS (
  SELECT
    COUNT(*) FILTER (WHERE outcome = 'suppressed')::bigint AS suppressed,
    COUNT(*) FILTER (WHERE outcome = 'deferred')::bigint AS deferred,
    COUNT(*) FILTER (WHERE outcome = 'start_failed')::bigint AS start_failed
  FROM automation_dispatch_events
  WHERE user_id = p_user_id
    AND created_at >= p_window_start
    AND (p_window_end IS NULL OR created_at <= p_window_end)
),
limit_rows AS (
  SELECT decision, route_key
  FROM limit_events
  WHERE user_id = p_user_id
    AND created_at >= p_window_start
    AND (p_window_end IS NULL OR created_at <= p_window_end)
),
limit_totals AS (
  SELECT
    COUNT(*) FILTER (WHERE decision = 'allowed')::bigint AS allowed,
    COUNT(*) FILTER (WHERE decision = 'denied')::bigint AS denied
  FROM limit_rows
),
limits_by_route AS (
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object('route_key', route_key, 'allowed', allowed, 'denied', denied)
      ORDER BY allowed + denied DESC
    ),
    '[]'::jsonb
  ) AS v
  FROM (
    SELECT route_key,
           COUNT(*) FILTER (WHERE decision = 'allowed')::bigint AS allowed,
           COUNT(*) FILTER (WHERE decision = 'denied')::bigint AS denied
    FROM limit_rows
    GROUP BY route_key
  ) grouped
),
reconciliation AS (
  -- completed_at IS NULL keeps in-flight calls in the pending count;
  -- NULL < timestamp would otherwise silently drop them.
  SELECT COUNT(*)::bigint AS pending
  FROM ai_calls
  WHERE user_id = p_user_id
    AND gateway_generation_id IS NOT NULL
    AND cost_source IS DISTINCT FROM 'gateway'
    AND (completed_at < p_reconciliation_stale_before OR completed_at IS NULL)
)
SELECT jsonb_build_object(
  'calls', jsonb_build_object(
    'total', call_totals.total_calls,
    'total_tokens', call_totals.total_tokens,
    'success', call_totals.success_calls,
    'avg_duration_ms', call_totals.avg_duration_ms,
    'known_cost_usd', call_totals.known_cost_usd,
    'by_model', by_model.v,
    'by_type', by_type.v
  ),
  'today', jsonb_build_object(
    'calls', today.calls,
    'tokens', today.tokens,
    'known_cost_usd', today.known_cost_usd
  ),
  'sandboxes', jsonb_build_object(
    'total', sandbox.total,
    'active', sandbox.active,
    'window_time_ms', sandbox.window_time_ms
  ),
  'dispatch', jsonb_build_object(
    'suppressed', dispatch.suppressed,
    'deferred', dispatch.deferred,
    'start_failed', dispatch.start_failed
  ),
  'limits', jsonb_build_object(
    'allowed', limit_totals.allowed,
    'denied', limit_totals.denied,
    'by_route', limits_by_route.v
  ),
  'reconciliation_pending', reconciliation.pending
)
FROM call_totals, by_model, by_type, today, sandbox, dispatch,
     limit_totals, limits_by_route, reconciliation;
$$;


--
-- Name: open_sandbox_billing_session(uuid, text, text, uuid, uuid, uuid, timestamp with time zone, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_sandbox_billing_session(p_sandbox_record uuid, p_vercel_sandbox_id text, p_vercel_session_id text, p_account uuid, p_actor_user uuid, p_product_team uuid, p_started_at timestamp with time zone, p_rate_micro_usd_per_minute bigint) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
declare
  v_id uuid;
  v_existing public.sandbox_billing_sessions%rowtype;
  v_sandbox public.sandboxes%rowtype;
  v_account public.billing_accounts%rowtype;
  v_balance bigint;
begin
  if nullif(trim(p_vercel_sandbox_id), '') is null then
    raise exception 'Vercel sandbox id is required';
  end if;
  if nullif(trim(p_vercel_session_id), '') is null then
    raise exception 'Vercel session id is required';
  end if;
  if p_started_at is null then
    raise exception 'sandbox billing session start is required';
  end if;
  if p_actor_user is null then
    raise exception 'sandbox billing actor is required';
  end if;
  if p_rate_micro_usd_per_minute is null
    or p_rate_micro_usd_per_minute <= 0
  then
    raise exception 'sandbox billing rate must be positive';
  end if;

  select * into v_sandbox from public.sandboxes
  where id = p_sandbox_record
  for key share;
  if not found then
    raise exception 'sandbox record % not found', p_sandbox_record;
  end if;
  if v_sandbox.billing_source is distinct from 'platform' then
    raise exception 'sandbox record % is not platform billed', p_sandbox_record;
  end if;
  if v_sandbox.sandbox_id <> trim(p_vercel_sandbox_id) then
    raise exception 'sandbox record % provider id mismatch', p_sandbox_record;
  end if;
  if coalesce(v_sandbox.actor_user_id, v_sandbox.user_id) <> p_actor_user then
    raise exception 'sandbox record % actor mismatch', p_sandbox_record;
  end if;
  if v_sandbox.product_team_id is distinct from p_product_team then
    raise exception 'sandbox record % product team mismatch', p_sandbox_record;
  end if;

  select * into v_account from public.billing_accounts
  where id = p_account
  for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;
  if p_product_team is null and not (
    v_account.owner_type = 'user'
    and v_account.owner_user_id = p_actor_user
    and v_account.product_team_id is null
  ) then
    raise exception 'billing account % personal scope mismatch', p_account;
  end if;
  if p_product_team is not null and not (
    v_account.owner_type = 'team'
    and v_account.owner_user_id is null
    and v_account.product_team_id = p_product_team
  ) then
    raise exception 'billing account % team scope mismatch', p_account;
  end if;

  select coalesce(sum(delta_cents), 0)::bigint into v_balance
  from public.credit_ledger
  where account_id = p_account;
  if v_balance <= 0 then
    raise exception using
      errcode = 'MP001',
      message = 'positive billing balance required for sandbox session';
  end if;

  insert into public.sandbox_billing_sessions (
    sandbox_record_id,
    vercel_sandbox_id,
    vercel_session_id,
    account_id,
    actor_user_id,
    product_team_id,
    started_at,
    metered_through_at,
    rate_micro_usd_per_minute
  ) values (
    p_sandbox_record,
    trim(p_vercel_sandbox_id),
    trim(p_vercel_session_id),
    p_account,
    p_actor_user,
    p_product_team,
    p_started_at,
    p_started_at,
    p_rate_micro_usd_per_minute
  ) on conflict do nothing
  returning id into v_id;

  if v_id is not null then
    return v_id;
  end if;

  select * into v_existing
  from public.sandbox_billing_sessions
  where vercel_session_id = trim(p_vercel_session_id);

  if found then
    if v_existing.sandbox_record_id <> p_sandbox_record
      or v_existing.vercel_sandbox_id <> trim(p_vercel_sandbox_id)
      or v_existing.account_id <> p_account
      or v_existing.actor_user_id <> p_actor_user
      or v_existing.product_team_id is distinct from p_product_team
      or v_existing.started_at <> p_started_at
      or v_existing.rate_micro_usd_per_minute <> p_rate_micro_usd_per_minute
    then
      raise exception 'Vercel session % billing identity mismatch', p_vercel_session_id;
    end if;
    if v_existing.state not in ('open', 'closing') then
      raise exception 'Vercel session % billing row is already closed', p_vercel_session_id;
    end if;
    return v_existing.id;
  end if;

  raise exception 'sandbox record % already has an active billing session',
    p_sandbox_record;
end;
$$;


--
-- Name: orchestration_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.orchestration_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: post_billing_period_grant(uuid, bigint, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_billing_period_grant(p_account uuid, p_delta bigint, p_grant_source_ref text, p_expiry_source_ref text, p_period text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(posted boolean, expired_cents bigint)
    LANGUAGE plpgsql
    AS $$
declare
  v_included_before bigint;
begin
  perform 1 from public.billing_accounts where id = p_account for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;

  select coalesce(sum(delta_cents), 0)::bigint
    into v_included_before
  from public.credit_ledger
  where account_id = p_account and bucket = 'included';

  insert into public.credit_ledger
    (account_id, delta_cents, bucket, kind, source_ref, period, metadata)
  values
    (p_account, p_delta, 'included', 'grant', p_grant_source_ref, p_period, p_metadata)
  on conflict (source_ref) do nothing;

  if not found then
    return query select false, 0::bigint;
    return;
  end if;

  if v_included_before > 0 then
    insert into public.credit_ledger
      (account_id, delta_cents, bucket, kind, source_ref, period)
    values
      (p_account, -v_included_before, 'included', 'grant_expiry',
       p_expiry_source_ref, p_period)
    on conflict (source_ref) do nothing;
  end if;

  return query select true, greatest(v_included_before, 0::bigint);
end;
$$;


--
-- Name: post_billing_usage_debit(uuid, bigint, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_billing_usage_debit(p_account uuid, p_amount bigint, p_kind text, p_source_ref text, p_period text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(posted boolean, debited_cents bigint, included_debited_cents bigint, purchased_debited_cents bigint)
    LANGUAGE plpgsql
    AS $$
declare
  v_included_balance bigint;
  v_included_debit bigint;
  v_purchased_debit bigint;
begin
  if p_amount <= 0 then
    raise exception 'billing usage amount must be positive, got %', p_amount;
  end if;
  if p_kind not in ('usage_tokens', 'usage_sandbox') then
    raise exception 'invalid billing usage kind %', p_kind;
  end if;

  perform 1 from public.billing_accounts where id = p_account for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;

  if exists (
    select 1 from public.credit_ledger
    where source_ref in (p_source_ref || ':inc', p_source_ref || ':pur')
  ) then
    return query select false, 0::bigint, 0::bigint, 0::bigint;
    return;
  end if;

  select greatest(
    coalesce(sum(delta_cents) filter (where bucket = 'included'), 0),
    0
  )::bigint
    into v_included_balance
  from public.credit_ledger
  where account_id = p_account;

  v_included_debit := least(v_included_balance, p_amount);
  v_purchased_debit := p_amount - v_included_debit;

  if v_included_debit > 0 then
    insert into public.credit_ledger
      (account_id, delta_cents, bucket, kind, source_ref, period, metadata)
    values
      (p_account, -v_included_debit, 'included', p_kind,
       p_source_ref || ':inc', p_period, p_metadata);
  end if;

  if v_purchased_debit > 0 then
    insert into public.credit_ledger
      (account_id, delta_cents, bucket, kind, source_ref, period, metadata)
    values
      (p_account, -v_purchased_debit, 'purchased', p_kind,
       p_source_ref || ':pur', p_period, p_metadata);
  end if;

  return query select true, p_amount, v_included_debit, v_purchased_debit;
end;
$$;


--
-- Name: post_credit_ledger_entry(uuid, bigint, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_credit_ledger_entry(p_account uuid, p_delta bigint, p_bucket text, p_kind text, p_source_ref text, p_period text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
  v_posted boolean;
begin
  perform 1 from public.billing_accounts where id = p_account for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;

  insert into public.credit_ledger
    (account_id, delta_cents, bucket, kind, source_ref, period, metadata)
  values
    (p_account, p_delta, p_bucket, p_kind, p_source_ref, p_period, p_metadata)
  on conflict (source_ref) do nothing;
  v_posted := found;
  return v_posted;
end;
$$;


--
-- Name: prevent_active_sandbox_billing_session_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_active_sandbox_billing_session_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if exists (
    select 1 from public.sandbox_billing_sessions
    where sandbox_record_id = old.id and state in ('open', 'closing')
  ) then
    raise exception 'sandbox % has an active billing session', old.id;
  end if;
  return old;
end;
$$;


--
-- Name: prune_orchestration_worktree(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_orchestration_worktree(p_worktree_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_worktree public.orchestration_worktrees;
begin
  update public.orchestration_worktrees
  set status = 'pruned',
      pruned_at = now()
  where id = p_worktree_id
    and user_id = p_user_id
    and status = 'archived'
  returning * into v_worktree;

  if not found then
    raise exception 'archived worktree not found';
  end if;

  update public.orchestration_tasks
  set worktree_id = null,
      root_directory = null
  where id = v_worktree.task_id
    and worktree_id = v_worktree.id;

  return to_jsonb(v_worktree);
end;
$$;


--
-- Name: publish_billing_account_update_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_billing_account_update_events() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_projection_changed boolean;
  v_status_changed boolean;
  v_source text;
begin
  v_projection_changed := row(
    new.tier,
    new.stripe_subscription_id,
    new.period_anchor,
    new.plan_code,
    new.plan_audience,
    new.max_named_users,
    new.included_concurrency,
    new.included_retained_bytes,
    new.included_hosted_usage_cents,
    new.entitlement_version
  ) is distinct from row(
    old.tier,
    old.stripe_subscription_id,
    old.period_anchor,
    old.plan_code,
    old.plan_audience,
    old.max_named_users,
    old.included_concurrency,
    old.included_retained_bytes,
    old.included_hosted_usage_cents,
    old.entitlement_version
  );
  v_status_changed := new.status is distinct from old.status;
  if not v_projection_changed and not v_status_changed then
    return new;
  end if;

  v_source := case
    when new.entitlement_projection_event_id is distinct from
      old.entitlement_projection_event_id
      then coalesce(
        nullif(btrim(new.entitlement_projection_event_id), ''),
        'database:' || pg_catalog.pg_current_xact_id()::text ||
          ':billing-account:' || new.id::text
      )
    else 'database:' || pg_catalog.pg_current_xact_id()::text ||
      ':billing-account:' || new.id::text
  end;

  if v_status_changed then
    perform public.append_billing_account_event(
      new.id,
      'billing.account.status_changed',
      v_source
    );
    if new.status = 'past_due'
      and new.plan_code in ('pro', 'plus', 'max') then
      perform public.append_billing_account_event(
        new.id,
        'billing.capacity.change_failed',
        v_source
      );
    end if;
  end if;

  perform public.append_billing_account_event(
    new.id,
    'billing.summary.changed',
    v_source
  );
  return new;
end;
$$;


--
-- Name: publish_billing_capacity_release_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_billing_capacity_release_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account uuid;
begin
  select lease.account_id into v_account
  from public.billing_workflow_capacity_leases lease
  where lease.id = new.lease_id;
  perform public.append_billing_account_event(
    v_account,
    'billing.summary.changed',
    new.source_ref
  );
  return new;
end;
$$;


--
-- Name: publish_billing_credit_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_billing_credit_events() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.append_billing_account_event(
    new.account_id,
    'billing.summary.changed',
    new.source_ref
  );
  if new.delta_cents > 0 then
    perform public.append_billing_account_event(
      new.account_id,
      'billing.hosted_usage.added',
      new.source_ref
    );
  end if;
  return new;
end;
$$;


--
-- Name: publish_billing_direct_summary_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_billing_direct_summary_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row jsonb := pg_catalog.to_jsonb(new);
  v_account uuid;
  v_source text;
begin
  v_account := (v_row->>'account_id')::uuid;
  v_source := nullif(btrim(v_row->>tg_argv[0]), '');
  if v_account is not null and v_source is not null then
    perform public.append_billing_account_event(
      v_account,
      'billing.summary.changed',
      v_source
    );
  end if;
  return new;
end;
$$;


--
-- Name: publish_billing_entitlement_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_billing_entitlement_events() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.append_billing_account_event(
    new.account_id,
    case
      when new.effective_at > pg_catalog.clock_timestamp()
        then 'billing.capacity.change_pending'
      else 'billing.capacity.change_applied'
    end,
    new.source_event_id
  );
  perform public.append_billing_account_event(
    new.account_id,
    'billing.summary.changed',
    new.source_event_id
  );
  return new;
end;
$$;


--
-- Name: publish_billing_provider_cost_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_billing_provider_cost_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.account_id is not null and new.retail_debit_micros > 0 then
    perform public.append_billing_account_event(
      new.account_id,
      'billing.summary.changed',
      new.provider || ':' || new.provider_event_id
    );
  end if;
  return new;
end;
$$;


--
-- Name: publish_billing_reservation_terminal_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_billing_reservation_terminal_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account uuid;
begin
  select reservation.account_id into v_account
  from public.billing_cost_reservations reservation
  where reservation.id = new.reservation_id;
  perform public.append_billing_account_event(
    v_account,
    'billing.summary.changed',
