$$;


--
-- Name: publish_slack_run_progress(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_slack_run_progress(p_run_id uuid, p_user_id uuid, p_ai_call_id uuid, p_progress jsonb) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE published_revision BIGINT;
BEGIN
  IF jsonb_typeof(p_progress) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Progress must be an object' USING ERRCODE = '22023';
  END IF;
  UPDATE public.external_agent_runs
     SET slack_progress = p_progress,
         slack_progress_revision = slack_progress_revision + 1
   WHERE id = p_run_id AND user_id = p_user_id AND ai_call_id = p_ai_call_id
     AND status IN ('pending', 'streaming')
  RETURNING slack_progress_revision INTO published_revision;
  RETURN published_revision;
END;
$$;


--
-- Name: publish_token_usage_cost_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_token_usage_cost_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_cost_micros bigint := (new.cost_units + 99) / 100;
begin
  perform public.record_billing_provider_cost_event(
    'vercel-ai-gateway',
    new.source_ref,
    'ai',
    new.account_id,
    null,
    v_cost_micros,
    'USD',
    v_cost_micros,
    v_cost_micros,
    'hosted_usage',
    'gateway_passthrough_2026_08_18',
    new.cost_units,
    '1e-8_usd',
    new.created_at,
    pg_catalog.jsonb_build_object(
      'operationRef',
      coalesce(
        nullif(new.metadata ->> 'ai_call_id', ''),
        pg_catalog.regexp_replace(new.source_ref, '^tok:', '')
      )
    ),
    new.metadata
  );
  return new;
end;
$$;


--
-- Name: record_billing_capacity_release(text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_billing_capacity_release(p_lease_ref text, p_terminal_outcome text, p_source_ref text, p_released_at timestamp with time zone, p_metadata jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lease public.billing_workflow_capacity_leases%rowtype;
  v_existing public.billing_workflow_capacity_release_events%rowtype;
begin
  select * into v_lease
  from public.billing_workflow_capacity_leases
  where lease_ref = btrim(p_lease_ref)
  for update;
  if not found then
    raise exception 'billing capacity lease % not found', p_lease_ref;
  end if;
  if p_released_at < v_lease.acquired_at then
    raise exception 'capacity release cannot predate the lease';
  end if;

  insert into public.billing_workflow_capacity_release_events (
    lease_id,
    terminal_outcome,
    source_ref,
    released_at,
    metadata
  ) values (
    v_lease.id,
    p_terminal_outcome,
    btrim(p_source_ref),
    p_released_at,
    coalesce(p_metadata, '{}')
  ) on conflict do nothing;

  if found then
    return true;
  end if;

  select * into v_existing
  from public.billing_workflow_capacity_release_events
  where lease_id = v_lease.id
    or source_ref = btrim(p_source_ref)
  order by id
  limit 1;

  if v_existing.lease_id <> v_lease.id
    or v_existing.terminal_outcome <> p_terminal_outcome
    or v_existing.source_ref <> btrim(p_source_ref)
    or v_existing.released_at <> p_released_at
    or v_existing.metadata <> coalesce(p_metadata, '{}') then
    raise exception 'capacity release idempotency conflict for %', p_lease_ref;
  end if;

  return false;
end;
$$;


--
-- Name: record_billing_capacity_schedule_projection(uuid, text, text, text, timestamp with time zone, smallint, timestamp with time zone, text, text, text, integer, integer, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_billing_capacity_schedule_projection(p_account uuid, p_subscription_id text, p_schedule_id text, p_source_event_id text, p_provider_event_created_at timestamp with time zone, p_event_priority smallint, p_effective_at timestamp with time zone, p_item_ref text, p_item_kind text, p_price_lookup_key text, p_quantity integer, p_concurrency_delta integer, p_retained_data_bytes_delta bigint, p_metadata jsonb) RETURNS TABLE(applied boolean, duplicate boolean, stale boolean, entitlement_recorded boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account public.billing_accounts%rowtype;
  v_existing public.billing_capacity_schedule_projections%rowtype;
  v_latest public.billing_capacity_schedule_projections%rowtype;
  v_should_apply boolean;
  v_recorded boolean := false;
begin
  if p_subscription_id is null or btrim(p_subscription_id) = ''
    or p_schedule_id is null or btrim(p_schedule_id) = ''
    or p_source_event_id is null or btrim(p_source_event_id) = ''
    or p_provider_event_created_at is null
    or p_effective_at is null
    or p_item_ref is null or btrim(p_item_ref) = ''
    or p_price_lookup_key is null or btrim(p_price_lookup_key) = '' then
    raise exception 'capacity schedule projection identity is invalid';
  end if;
  if p_event_priority is null or p_event_priority not in (0, 50, 100)
    or p_item_kind is null
    or p_item_kind not in ('concurrency_addon', 'retained_data_addon')
    or p_quantity is null or p_quantity < 0
    or p_concurrency_delta is null or p_concurrency_delta < 0
    or p_retained_data_bytes_delta is null
    or p_retained_data_bytes_delta < 0
    or (p_item_kind = 'concurrency_addon'
      and (p_concurrency_delta = 0 or p_retained_data_bytes_delta <> 0))
    or (p_item_kind = 'retained_data_addon'
      and (p_retained_data_bytes_delta = 0 or p_concurrency_delta <> 0)) then
    raise exception 'capacity schedule projection values are invalid';
  end if;
  if p_metadata is not null and jsonb_typeof(p_metadata) <> 'object' then
    raise exception 'capacity schedule projection metadata must be an object';
  end if;

  select * into v_account
  from public.billing_accounts
  where id = p_account
  for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;
  if v_account.stripe_subscription_id is not null
    and v_account.stripe_subscription_id <> btrim(p_subscription_id) then
    raise exception 'capacity schedule subscription does not match account';
  end if;

  select * into v_existing
  from public.billing_capacity_schedule_projections
  where account_id = p_account
    and source_event_id = btrim(p_source_event_id);
  if found then
    if v_existing.stripe_subscription_id <> btrim(p_subscription_id)
      or v_existing.stripe_schedule_id <> btrim(p_schedule_id)
      or v_existing.provider_event_created_at <> p_provider_event_created_at
      or v_existing.event_priority <> p_event_priority
      or v_existing.effective_at <> p_effective_at
      or v_existing.item_ref <> btrim(p_item_ref)
      or v_existing.item_kind <> p_item_kind
      or v_existing.price_lookup_key <> btrim(p_price_lookup_key)
      or v_existing.quantity <> p_quantity
      or v_existing.concurrency_delta <> p_concurrency_delta
      or v_existing.retained_data_bytes_delta <> p_retained_data_bytes_delta
      or v_existing.metadata <> coalesce(p_metadata, '{}') then
      raise exception 'capacity schedule projection idempotency conflict for %',
        p_source_event_id;
    end if;
    return query select false, true, not v_existing.applied, false;
    return;
  end if;

  select * into v_latest
  from public.billing_capacity_schedule_projections
  where account_id = p_account
    and stripe_schedule_id = btrim(p_schedule_id)
    and item_ref = btrim(p_item_ref)
    and billing_capacity_schedule_projections.applied
  order by provider_event_created_at desc,
    event_priority desc,
    source_event_id desc
  limit 1;

  v_should_apply := not found
    or p_provider_event_created_at > v_latest.provider_event_created_at
    or (
      p_provider_event_created_at = v_latest.provider_event_created_at
      and p_event_priority > v_latest.event_priority
    )
    or (
      p_provider_event_created_at = v_latest.provider_event_created_at
      and p_event_priority = v_latest.event_priority
      and btrim(p_source_event_id) > v_latest.source_event_id
    );

  insert into public.billing_capacity_schedule_projections (
    account_id,
    stripe_subscription_id,
    stripe_schedule_id,
    source_event_id,
    provider_event_created_at,
    event_priority,
    effective_at,
    item_ref,
    item_kind,
    price_lookup_key,
    quantity,
    concurrency_delta,
    retained_data_bytes_delta,
    applied,
    metadata
  ) values (
    p_account,
    btrim(p_subscription_id),
    btrim(p_schedule_id),
    btrim(p_source_event_id),
    p_provider_event_created_at,
    p_event_priority,
    p_effective_at,
    btrim(p_item_ref),
    p_item_kind,
    btrim(p_price_lookup_key),
    p_quantity,
    p_concurrency_delta,
    p_retained_data_bytes_delta,
    v_should_apply,
    coalesce(p_metadata, '{}')
  );

  if v_should_apply then
    v_recorded := public.record_billing_entitlement_item(
      p_account,
      btrim(p_item_ref),
      p_item_kind,
      btrim(p_price_lookup_key),
      p_quantity,
      p_concurrency_delta,
      p_retained_data_bytes_delta,
      0,
      p_effective_at,
      btrim(p_source_event_id),
      coalesce(p_metadata, '{}') || jsonb_build_object(
        'stripe_subscription_id', btrim(p_subscription_id),
        'stripe_schedule_id', btrim(p_schedule_id),
        'scheduled', true
      )
    );
  end if;

  return query select
    v_should_apply,
    false,
    not v_should_apply,
    v_recorded;
end;
$$;


--
-- Name: record_billing_entitlement_item(uuid, text, text, text, integer, integer, bigint, bigint, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_billing_entitlement_item(p_account uuid, p_item_ref text, p_item_kind text, p_price_lookup_key text, p_quantity integer, p_concurrency_delta integer, p_retained_data_bytes_delta bigint, p_hosted_usage_cents_delta bigint, p_effective_at timestamp with time zone, p_source_event_id text, p_metadata jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_existing public.billing_entitlement_items%rowtype;
begin
  perform 1 from public.billing_accounts where id = p_account;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;

  insert into public.billing_entitlement_items (
    account_id,
    item_ref,
    item_kind,
    price_lookup_key,
    quantity,
    concurrency_delta,
    retained_data_bytes_delta,
    hosted_usage_cents_delta,
    effective_at,
    source_event_id,
    metadata
  ) values (
    p_account,
    btrim(p_item_ref),
    p_item_kind,
    btrim(p_price_lookup_key),
    p_quantity,
    p_concurrency_delta,
    p_retained_data_bytes_delta,
    p_hosted_usage_cents_delta,
    p_effective_at,
    btrim(p_source_event_id),
    coalesce(p_metadata, '{}')
  ) on conflict (account_id, item_ref, source_event_id) do nothing;

  if found then
    return true;
  end if;

  select * into v_existing
  from public.billing_entitlement_items
  where account_id = p_account
    and item_ref = btrim(p_item_ref)
    and source_event_id = btrim(p_source_event_id);

  if v_existing.item_kind <> p_item_kind
    or v_existing.price_lookup_key <> btrim(p_price_lookup_key)
    or v_existing.quantity <> p_quantity
    or v_existing.concurrency_delta <> p_concurrency_delta
    or v_existing.retained_data_bytes_delta <> p_retained_data_bytes_delta
    or v_existing.hosted_usage_cents_delta <> p_hosted_usage_cents_delta
    or v_existing.effective_at <> p_effective_at
    or v_existing.metadata <> coalesce(p_metadata, '{}') then
    raise exception 'entitlement item idempotency conflict for %', p_source_event_id;
  end if;

  return false;
end;
$$;


--
-- Name: record_billing_provider_cost_event(text, text, text, uuid, text, bigint, text, bigint, bigint, text, text, numeric, text, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_billing_provider_cost_event(p_provider text, p_provider_event_id text, p_cost_source text, p_account uuid, p_shared_overhead_category text, p_provider_cost_micros bigint, p_provider_currency text, p_normalized_cost_micros bigint, p_retail_debit_micros bigint, p_billing_treatment text, p_pricing_rule_version text, p_measured_quantity numeric, p_measured_unit text, p_occurred_at timestamp with time zone, p_refs jsonb, p_metadata jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_existing public.billing_provider_cost_events%rowtype;
begin
  if p_account is not null then
    perform 1 from public.billing_accounts where id = p_account;
    if not found then
      raise exception 'billing account % not found', p_account;
    end if;
  end if;

  insert into public.billing_provider_cost_events (
    provider,
    provider_event_id,
    cost_source,
    account_id,
    shared_overhead_category,
    provider_cost_micros,
    provider_currency,
    normalized_cost_micros,
    retail_debit_micros,
    billing_treatment,
    pricing_rule_version,
    measured_quantity,
    measured_unit,
    operation_ref,
    root_workflow_ref,
    run_ref,
    sandbox_ref,
    artifact_ref,
    occurred_at,
    metadata
  ) values (
    btrim(p_provider),
    btrim(p_provider_event_id),
    p_cost_source,
    p_account,
    p_shared_overhead_category,
    p_provider_cost_micros,
    upper(p_provider_currency),
    p_normalized_cost_micros,
    p_retail_debit_micros,
    p_billing_treatment,
    btrim(p_pricing_rule_version),
    p_measured_quantity,
    p_measured_unit,
    p_refs ->> 'operationRef',
    p_refs ->> 'rootWorkflowRef',
    p_refs ->> 'runRef',
    p_refs ->> 'sandboxRef',
    p_refs ->> 'artifactRef',
    p_occurred_at,
    coalesce(p_metadata, '{}')
  ) on conflict (provider, provider_event_id) do nothing;

  if found then
    return true;
  end if;

  select * into v_existing
  from public.billing_provider_cost_events
  where provider = btrim(p_provider)
    and provider_event_id = btrim(p_provider_event_id);

  if v_existing.cost_source <> p_cost_source
    or v_existing.account_id is distinct from p_account
    or v_existing.shared_overhead_category is distinct from
      p_shared_overhead_category
    or v_existing.provider_cost_micros <> p_provider_cost_micros
    or v_existing.provider_currency <> upper(p_provider_currency)
    or v_existing.normalized_cost_micros <> p_normalized_cost_micros
    or v_existing.retail_debit_micros <> p_retail_debit_micros
    or v_existing.billing_treatment <> p_billing_treatment
    or v_existing.pricing_rule_version <> btrim(p_pricing_rule_version)
    or v_existing.measured_quantity is distinct from p_measured_quantity
    or v_existing.measured_unit is distinct from p_measured_unit
    or v_existing.operation_ref is distinct from p_refs ->> 'operationRef'
    or v_existing.root_workflow_ref is distinct from
      p_refs ->> 'rootWorkflowRef'
    or v_existing.run_ref is distinct from p_refs ->> 'runRef'
    or v_existing.sandbox_ref is distinct from p_refs ->> 'sandboxRef'
    or v_existing.artifact_ref is distinct from p_refs ->> 'artifactRef'
    or v_existing.occurred_at <> p_occurred_at
    or v_existing.metadata <> coalesce(p_metadata, '{}') then
    raise exception 'provider cost idempotency conflict for %:%',
      p_provider, p_provider_event_id;
  end if;

  return false;
end;
$$;


--
-- Name: record_billing_reservation_terminal(text, text, bigint, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_billing_reservation_terminal(p_reservation_ref text, p_terminal_kind text, p_consumed_micros bigint, p_source_ref text, p_terminal_at timestamp with time zone, p_metadata jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_reservation public.billing_cost_reservations%rowtype;
  v_existing public.billing_cost_reservation_terminal_events%rowtype;
begin
  select * into v_reservation
  from public.billing_cost_reservations
  where reservation_ref = btrim(p_reservation_ref)
  for update;
  if not found then
    raise exception 'billing reservation % not found', p_reservation_ref;
  end if;
  if p_terminal_at < v_reservation.created_at then
    raise exception 'reservation terminal cannot predate the reservation';
  end if;
  if p_terminal_kind = 'settled'
    and p_consumed_micros > v_reservation.reserved_micros then
    raise exception 'reservation settlement exceeds its approved bound';
  end if;

  insert into public.billing_cost_reservation_terminal_events (
    reservation_id,
    terminal_kind,
    consumed_micros,
    source_ref,
    terminal_at,
    metadata
  ) values (
    v_reservation.id,
    p_terminal_kind,
    p_consumed_micros,
    btrim(p_source_ref),
    p_terminal_at,
    coalesce(p_metadata, '{}')
  ) on conflict do nothing;

  if found then
    return true;
  end if;

  select * into v_existing
  from public.billing_cost_reservation_terminal_events
  where reservation_id = v_reservation.id
    or source_ref = btrim(p_source_ref)
  order by id
  limit 1;

  if v_existing.reservation_id <> v_reservation.id
    or v_existing.terminal_kind <> p_terminal_kind
    or v_existing.consumed_micros <> p_consumed_micros
    or v_existing.source_ref <> btrim(p_source_ref)
    or v_existing.terminal_at <> p_terminal_at
    or v_existing.metadata <> coalesce(p_metadata, '{}') then
    raise exception 'reservation terminal idempotency conflict for %',
      p_reservation_ref;
  end if;

  return false;
end;
$$;


--
-- Name: record_billing_shadow_capacity_lease(uuid, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_billing_shadow_capacity_lease(p_account uuid, p_lease_ref text, p_source_ref text, p_root_workflow_ref text, p_acquired_at timestamp with time zone, p_metadata jsonb) RETURNS TABLE(posted boolean, would_admit boolean, active_before integer, concurrency_limit integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_mode text;
  v_limit integer;
  v_active integer;
  v_would_admit boolean;
  v_existing public.billing_workflow_capacity_leases%rowtype;
begin
  select entitlement_enforcement_mode, included_concurrency
    into v_mode, v_limit
  from public.billing_accounts
  where id = p_account
  for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;
  if v_mode not in ('shadow', 'meter_only') then
    raise exception 'shadow capacity writer is disabled for % mode', v_mode;
  end if;

  select lease.* into v_existing
  from public.billing_workflow_capacity_leases lease
  left join public.billing_workflow_capacity_release_events release
    on release.lease_id = lease.id
  where lease.lease_ref = btrim(p_lease_ref)
    or lease.source_ref = btrim(p_source_ref)
    or (
      lease.account_id = p_account
      and lease.root_workflow_ref = btrim(p_root_workflow_ref)
      and release.id is null
    )
  order by lease.id
  limit 1;

  if found then
    if v_existing.account_id is distinct from p_account
      or v_existing.lease_ref <> btrim(p_lease_ref)
      or v_existing.source_ref <> btrim(p_source_ref)
      or v_existing.root_workflow_ref <> btrim(p_root_workflow_ref)
      or v_existing.acquired_at <> p_acquired_at
      or v_existing.metadata <> coalesce(p_metadata, '{}') then
      raise exception 'capacity lease idempotency conflict for %', p_lease_ref;
    end if;

    return query select false, v_existing.would_admit,
      v_existing.active_before, v_existing.concurrency_limit;
    return;
  end if;

  select count(*)::integer into v_active
  from public.billing_workflow_capacity_leases lease
  left join public.billing_workflow_capacity_release_events release
    on release.lease_id = lease.id
  where lease.account_id = p_account
    and release.id is null;

  v_would_admit := v_active < v_limit;

  insert into public.billing_workflow_capacity_leases (
    account_id,
    lease_ref,
    source_ref,
    root_workflow_ref,
    accounting_mode,
    concurrency_limit,
    active_before,
    would_admit,
    acquired_at,
    metadata
  ) values (
    p_account,
    btrim(p_lease_ref),
    btrim(p_source_ref),
    btrim(p_root_workflow_ref),
    v_mode,
    v_limit,
    v_active,
    v_would_admit,
    p_acquired_at,
    coalesce(p_metadata, '{}')
  ) on conflict do nothing;

  if found then
    return query select true, v_would_admit, v_active, v_limit;
    return;
  end if;

  select * into v_existing
  from public.billing_workflow_capacity_leases
  where lease_ref = btrim(p_lease_ref)
    or source_ref = btrim(p_source_ref)
  order by id
  limit 1;

  if not found
    or v_existing.account_id is distinct from p_account
    or v_existing.lease_ref <> btrim(p_lease_ref)
    or v_existing.source_ref <> btrim(p_source_ref)
    or v_existing.root_workflow_ref <> btrim(p_root_workflow_ref)
    or v_existing.acquired_at <> p_acquired_at
    or v_existing.metadata <> coalesce(p_metadata, '{}') then
    raise exception 'capacity lease idempotency conflict for %', p_lease_ref;
  end if;

  return query select false, v_existing.would_admit,
    v_existing.active_before, v_existing.concurrency_limit;
end;
$$;


--
-- Name: record_billing_shadow_reservation(uuid, text, text, text, text, bigint, jsonb, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_billing_shadow_reservation(p_account uuid, p_reservation_ref text, p_source_ref text, p_operation_ref text, p_root_workflow_ref text, p_reserved_micros bigint, p_basis jsonb, p_basis_version text, p_expires_at timestamp with time zone, p_metadata jsonb) RETURNS TABLE(posted boolean, would_admit boolean, balance_micros text, open_reserved_micros text, spendable_micros text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_mode text;
  v_balance bigint;
  v_open_reserved bigint;
  v_spendable bigint;
  v_would_admit boolean;
  v_existing public.billing_cost_reservations%rowtype;
begin
  select entitlement_enforcement_mode into v_mode
  from public.billing_accounts
  where id = p_account
  for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;
  if v_mode not in ('shadow', 'meter_only') then
    raise exception 'shadow reservation writer is disabled for % mode', v_mode;
  end if;
  select coalesce(sum(delta_cents), 0)::bigint * 10000
    into v_balance
  from public.credit_ledger
  where account_id = p_account;

  select coalesce(sum(reservation.reserved_micros), 0)::bigint
    into v_open_reserved
  from public.billing_cost_reservations reservation
  left join public.billing_cost_reservation_terminal_events terminal
    on terminal.reservation_id = reservation.id
  where reservation.account_id = p_account
    and terminal.id is null;

  v_spendable := v_balance - v_open_reserved;
  v_would_admit := v_spendable >= p_reserved_micros;

  insert into public.billing_cost_reservations (
    account_id,
    reservation_ref,
    source_ref,
    operation_ref,
    root_workflow_ref,
    reserved_micros,
    basis,
    basis_version,
    accounting_mode,
    balance_micros_before,
    open_reserved_micros_before,
    spendable_micros_before,
    would_admit,
    expires_at,
    metadata
  ) values (
    p_account,
    btrim(p_reservation_ref),
    btrim(p_source_ref),
    btrim(p_operation_ref),
    nullif(btrim(p_root_workflow_ref), ''),
    p_reserved_micros,
    coalesce(p_basis, '{}'),
    btrim(p_basis_version),
    v_mode,
    v_balance,
    v_open_reserved,
    v_spendable,
    v_would_admit,
    p_expires_at,
    coalesce(p_metadata, '{}')
  ) on conflict do nothing;

  if found then
    return query select true, v_would_admit, v_balance::text,
      v_open_reserved::text, v_spendable::text;
    return;
  end if;

  select * into v_existing
  from public.billing_cost_reservations
  where reservation_ref = btrim(p_reservation_ref)
    or source_ref = btrim(p_source_ref)
  order by id
  limit 1;

  if v_existing.account_id is distinct from p_account
    or v_existing.reservation_ref <> btrim(p_reservation_ref)
    or v_existing.source_ref <> btrim(p_source_ref)
    or v_existing.operation_ref <> btrim(p_operation_ref)
    or v_existing.root_workflow_ref is distinct from
      nullif(btrim(p_root_workflow_ref), '')
    or v_existing.reserved_micros <> p_reserved_micros
    or v_existing.basis <> coalesce(p_basis, '{}')
    or v_existing.basis_version <> btrim(p_basis_version)
    or v_existing.expires_at <> p_expires_at
    or v_existing.metadata <> coalesce(p_metadata, '{}') then
    raise exception 'reservation idempotency conflict for %', p_reservation_ref;
  end if;

  return query select false, v_existing.would_admit,
    v_existing.balance_micros_before::text,
    v_existing.open_reserved_micros_before::text,
    v_existing.spendable_micros_before::text;
end;
$$;


--
-- Name: record_billing_shadow_retained_data_event(uuid, text, text, bigint, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_billing_shadow_retained_data_event(p_account uuid, p_resource_type text, p_resource_ref text, p_delta_bytes bigint, p_source_ref text, p_operation_ref text, p_occurred_at timestamp with time zone, p_metadata jsonb) RETURNS TABLE(posted boolean, would_admit boolean, logical_bytes text, retained_limit_bytes text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_mode text;
  v_limit bigint;
  v_total_before bigint;
  v_total_after bigint;
  v_resource_before bigint;
  v_resource_after bigint;
  v_would_admit boolean;
  v_existing public.billing_retained_data_events%rowtype;
begin
  select entitlement_enforcement_mode, included_retained_bytes
    into v_mode, v_limit
  from public.billing_accounts
  where id = p_account
  for update;
  if not found then
    raise exception 'billing account % not found', p_account;
  end if;
  if v_mode not in ('shadow', 'meter_only') then
    raise exception 'shadow retained-data writer is disabled for % mode', v_mode;
  end if;

  select coalesce(sum(rollup.logical_bytes), 0)::bigint into v_total_before
  from public.billing_retained_data_rollups rollup
  where rollup.account_id = p_account;

  select coalesce(max(rollup.logical_bytes), 0)::bigint into v_resource_before
  from public.billing_retained_data_rollups rollup
  where rollup.account_id = p_account
    and rollup.resource_type = p_resource_type;

  v_total_after := v_total_before + p_delta_bytes;
  v_resource_after := v_resource_before + p_delta_bytes;
  if v_total_after < 0 or v_resource_after < 0 then
    raise exception 'retained data change would make logical bytes negative';
  end if;
  v_would_admit := p_delta_bytes < 0 or v_total_after <= v_limit;

  insert into public.billing_retained_data_events (
    account_id,
    resource_type,
    resource_ref,
    delta_bytes,
    source_ref,
    operation_ref,
    accounting_mode,
    retained_limit_bytes,
    logical_bytes_before,
    logical_bytes_after,
    would_admit,
    occurred_at,
    metadata
  ) values (
    p_account,
    p_resource_type,
    btrim(p_resource_ref),
    p_delta_bytes,
    btrim(p_source_ref),
    nullif(btrim(p_operation_ref), ''),
    v_mode,
    v_limit,
    v_total_before,
    v_total_after,
    v_would_admit,
    p_occurred_at,
    coalesce(p_metadata, '{}')
  ) on conflict (source_ref) do nothing;

  if not found then
    select * into v_existing
    from public.billing_retained_data_events
    where source_ref = btrim(p_source_ref);

    if v_existing.account_id is distinct from p_account
      or v_existing.resource_type <> p_resource_type
      or v_existing.resource_ref <> btrim(p_resource_ref)
      or v_existing.delta_bytes <> p_delta_bytes
      or v_existing.operation_ref is distinct from
        nullif(btrim(p_operation_ref), '')
      or v_existing.occurred_at <> p_occurred_at
      or v_existing.metadata <> coalesce(p_metadata, '{}') then
      raise exception 'retained data idempotency conflict for %', p_source_ref;
    end if;

    return query select false, v_existing.would_admit,
      v_existing.logical_bytes_after::text,
      v_existing.retained_limit_bytes::text;
    return;
  end if;

  insert into public.billing_retained_data_rollups (
    account_id,
    resource_type,
    logical_bytes,
    updated_at
  ) values (
    p_account,
    p_resource_type,
    v_resource_after,
    now()
  ) on conflict (account_id, resource_type) do update
    set logical_bytes = excluded.logical_bytes,
        updated_at = excluded.updated_at;

  return query select true, v_would_admit, v_total_after::text, v_limit::text;
end;
$$;


--
-- Name: record_job_run_start_attempt(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_job_run_start_attempt(p_job_run_id uuid, p_source text, p_attempted_at timestamp with time zone DEFAULT now(), p_status_hint text DEFAULT NULL::text) RETURNS TABLE(found boolean, attempted_at timestamp with time zone, status text, start_attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE public.job_runs AS jr
  SET
    start_attempts = COALESCE(jr.start_attempts, 0) + 1,
    last_start_attempt_at = p_attempted_at,
    last_start_source = p_source,
    last_start_error = CASE
      WHEN p_status_hint IS NOT NULL AND p_status_hint <> 'pending' THEN 'Job is ' || p_status_hint
      ELSE NULL
    END
  WHERE jr.id = p_job_run_id
  RETURNING
    TRUE,
    p_attempted_at,
    jr.status,
    jr.start_attempts;

  IF FOUND THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT FALSE, p_attempted_at, NULL::TEXT, NULL::INT;
END;
$$;


--
-- Name: record_sandbox_client_attach_event(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_sandbox_client_attach_event(p_sandbox_record_id uuid, p_user_id uuid, p_tab_id text, p_session_id text, p_event_seq integer) RETURNS TABLE(session_row_id uuid, applied boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_now timestamptz := now();
begin
  perform pg_advisory_xact_lock(
    hashtextextended('sandbox-presence:' || p_sandbox_record_id::text, 0)
  );

  return query
  with upserted as (
    insert into public.sandbox_client_sessions (
      sandbox_record_id,
      user_id,
      tab_id,
      session_id,
      attached_at,
      released_at,
      release_reason,
      last_event_at,
      event_seq
    )
    values (
      p_sandbox_record_id,
      p_user_id,
      p_tab_id,
      p_session_id,
      v_now,
      null,
      null,
      v_now,
      p_event_seq
    )
    on conflict (sandbox_record_id, user_id, tab_id, session_id)
    do update set
      attached_at = excluded.attached_at,
      released_at = null,
      release_reason = null,
      release_event_id = null,
      auto_pause_queued_at = null,
      last_event_at = excluded.last_event_at,
      event_seq = excluded.event_seq
    where sandbox_client_sessions.event_seq < excluded.event_seq
    returning sandbox_client_sessions.id
  ),
  existing as (
    select scs.id
    from public.sandbox_client_sessions scs
    where scs.sandbox_record_id = p_sandbox_record_id
      and scs.user_id = p_user_id
      and scs.tab_id = p_tab_id
      and scs.session_id = p_session_id
      and not exists (select 1 from upserted)
    limit 1
  )
  select upserted.id, true from upserted
  union all
  select existing.id, false from existing;
end;
$$;


--
-- Name: record_sandbox_client_release_event(uuid, uuid, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_sandbox_client_release_event(p_sandbox_record_id uuid, p_user_id uuid, p_tab_id text, p_session_id text, p_event_seq integer, p_release_reason text) RETURNS TABLE(session_row_id uuid, applied boolean, should_queue boolean, released_at timestamp with time zone, release_event_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_session_row_id uuid;
  v_released_at timestamptz;
  v_release_event_id uuid;
  v_auto_pause_queued_at timestamptz;
  v_event_seq integer;
  v_release_reason text;
begin
  perform pg_advisory_xact_lock(
    hashtextextended('sandbox-presence:' || p_sandbox_record_id::text, 0)
  );

  insert into public.sandbox_client_sessions as scs (
    sandbox_record_id,
    user_id,
    tab_id,
    session_id,
    attached_at,
    released_at,
    release_reason,
    auto_pause_queued_at,
    last_event_at,
    event_seq
  )
  values (
    p_sandbox_record_id,
    p_user_id,
    p_tab_id,
    p_session_id,
    v_now,
    v_now,
    p_release_reason,
    null,
    v_now,
    p_event_seq
  )
  on conflict (sandbox_record_id, user_id, tab_id, session_id)
  do update set
    released_at = excluded.released_at,
    release_reason = excluded.release_reason,
    release_event_id = null,
    auto_pause_queued_at = null,
    last_event_at = excluded.last_event_at,
    event_seq = excluded.event_seq
  where scs.event_seq <= excluded.event_seq
    and scs.released_at is null
  returning
    scs.id,
    scs.released_at,
    scs.release_event_id,
    scs.auto_pause_queued_at,
    scs.event_seq,
    scs.release_reason
  into
    v_session_row_id,
    v_released_at,
    v_release_event_id,
    v_auto_pause_queued_at,
    v_event_seq,
    v_release_reason;

  if v_session_row_id is not null then
    insert into public.sandbox_lifecycle_events (
      sandbox_record_id,
      user_id,
      tab_id,
      session_id,
      event_type,
      payload,
      created_at
    )
    values (
      p_sandbox_record_id,
      p_user_id,
      p_tab_id,
      p_session_id,
      'tab_released',
      jsonb_build_object(
        'event_seq', v_event_seq,
        'session_row_id', v_session_row_id,
        'reason', v_release_reason,
        'released_at', v_released_at
      ),
      v_now
    )
    returning id into v_release_event_id;

    update public.sandbox_client_sessions scs
    set release_event_id = v_release_event_id
    where scs.id = v_session_row_id;

    return query
    select
      v_session_row_id,
      true,
      true,
      v_released_at,
      v_release_event_id;
    return;
  end if;

  select
    scs.id,
    scs.released_at,
    scs.release_event_id,
    scs.auto_pause_queued_at,
    scs.event_seq,
    scs.release_reason
  into
    v_session_row_id,
    v_released_at,
    v_release_event_id,
    v_auto_pause_queued_at,
    v_event_seq,
    v_release_reason
  from public.sandbox_client_sessions scs
  where scs.sandbox_record_id = p_sandbox_record_id
    and scs.user_id = p_user_id
    and scs.tab_id = p_tab_id
    and scs.session_id = p_session_id
  limit 1
  for update;

  if v_session_row_id is null then
    return;
  end if;

  if v_released_at is not null and v_release_event_id is null then
    insert into public.sandbox_lifecycle_events (
      sandbox_record_id,
      user_id,
      tab_id,
      session_id,
      event_type,
      payload,
      created_at
    )
    values (
      p_sandbox_record_id,
      p_user_id,
      p_tab_id,
      p_session_id,
      'tab_released',
      jsonb_build_object(
        'event_seq', v_event_seq,
        'session_row_id', v_session_row_id,
        'reason', v_release_reason,
        'released_at', v_released_at
      ),
      v_now
    )
    returning id into v_release_event_id;

    update public.sandbox_client_sessions scs
    set release_event_id = v_release_event_id
    where scs.id = v_session_row_id
      and scs.release_event_id is null;
  end if;

  return query
  select
    v_session_row_id,
    false,
    v_released_at is not null
      and v_auto_pause_queued_at is null
      and v_release_event_id is not null,
    v_released_at,
    v_release_event_id;
end;
$$;


--
-- Name: record_waitlist_request(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_waitlist_request(p_email text, p_name text, p_company text, p_use_case text, p_source text) RETURNS TABLE(inserted boolean)
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$
  -- COALESCE(EXCLUDED.col, col) keeps the stored value when the resubmitted
  -- payload omits an optional field. Empty strings are normalized to NULL by
  -- the route layer, so this also protects against accidental blanking.
  -- `source` and `updated_at` always reflect the latest submission.
  --
  -- Isolation assumption: `xmax = 0` is the standard MVCC trick for telling
  -- INSERT from UPDATE on an upsert RETURNING clause, and it is reliable
  -- under READ COMMITTED (PostgREST's default isolation). Under REPEATABLE
  -- READ or SERIALIZABLE the freshly-inserted row's xmax can be non-zero in
  -- some snapshot-conflict paths, which would yield a false `inserted=false`.
  -- PostgREST does not run RPCs under elevated isolation, so this is safe
  -- in production; callers running this function from a non-PostgREST
  -- session at higher isolation should not rely on `inserted` being exact.
  INSERT INTO public.waitlist_requests (email, name, company, use_case, source)
  VALUES (p_email, p_name, p_company, p_use_case, p_source)
  ON CONFLICT ON CONSTRAINT waitlist_requests_email_unique DO UPDATE SET
    name       = COALESCE(EXCLUDED.name,     public.waitlist_requests.name),
    company    = COALESCE(EXCLUDED.company,  public.waitlist_requests.company),
    use_case   = COALESCE(EXCLUDED.use_case, public.waitlist_requests.use_case),
    source     = EXCLUDED.source,
    updated_at = NOW()
  RETURNING (xmax = 0) AS inserted;
$$;


--
-- Name: FUNCTION record_waitlist_request(p_email text, p_name text, p_company text, p_use_case text, p_source text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_waitlist_request(p_email text, p_name text, p_company text, p_use_case text, p_source text) IS 'Upsert a waitlist request, returning inserted=true on fresh insert and false when the conflict path fired. Optional fields are preserved with COALESCE. Service role only — any migration that recreates this function MUST re-apply the REVOKE/GRANT below it, because CREATE OR REPLACE does not reset privileges.';


--
-- Name: redeem_waitlist_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_waitlist_code(p_code text) RETURNS TABLE(ok boolean, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.waitlist_codes
     SET uses = uses + 1
   WHERE code = p_code
     AND (max_uses IS NULL OR uses < max_uses)
     AND (expires_at IS NULL OR expires_at > NOW());

  IF FOUND THEN
    RETURN QUERY SELECT TRUE, NULL::TEXT;
    RETURN;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.waitlist_codes WHERE code = p_code) THEN
    RETURN QUERY SELECT FALSE, 'invalid'::TEXT;
  ELSIF EXISTS (
    SELECT 1 FROM public.waitlist_codes
     WHERE code = p_code
       AND expires_at IS NOT NULL
       AND expires_at <= NOW()
  ) THEN
    RETURN QUERY SELECT FALSE, 'expired'::TEXT;
  ELSE
    RETURN QUERY SELECT FALSE, 'exhausted'::TEXT;
  END IF;
END;
$$;


--
-- Name: reject_immutable_billing_event_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_immutable_billing_event_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception '% is append-only; insert a compensating event', tg_table_name;
