--
-- Name: release_archived_worktree(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_archived_worktree(p_worktree_id uuid, p_user_id uuid, p_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.orchestration_worktrees
  set metadata = metadata - 'archived_claim'
  where id = p_worktree_id
    and user_id = p_user_id
    and metadata->'archived_claim'->>'token' = p_token::text;
end;
$$;


--
-- Name: release_billing_capacity_on_job_terminal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_billing_capacity_on_job_terminal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lease public.billing_workflow_capacity_leases%rowtype;
  v_outcome text;
  v_released_at timestamptz;
begin
  if new.status = 'success' then
    v_outcome := 'success';
  elsif new.status = 'cancelled' then
    if coalesce(new.cancel_reason, '') like 'ZOMBIE_REAPED_%' then
      v_outcome := 'operator_repair';
    else
      v_outcome := 'cancelled';
    end if;
  elsif coalesce(new.error, '') ilike '%timed out%'
    or coalesce(new.error, '') ilike '%timeout%' then
    v_outcome := 'timeout';
  elsif coalesce(new.error, '') like 'RECONCILED_%' then
    v_outcome := 'operator_repair';
  else
    v_outcome := 'failure';
  end if;

  v_released_at := coalesce(new.completed_at, new.cancelled_at, now());

  for v_lease in
    select lease.*
    from public.billing_workflow_capacity_leases lease
    left join public.billing_workflow_capacity_release_events release
      on release.lease_id = lease.id
    where lease.root_workflow_ref = new.id::text
      and release.id is null
    order by lease.id
  loop
    perform 1
    from public.billing_accounts
    where id = v_lease.account_id
    for update;

    insert into public.billing_workflow_capacity_release_events (
      lease_id,
      terminal_outcome,
      source_ref,
      released_at,
      metadata
    ) values (
      v_lease.id,
      v_outcome,
      'job-terminal:' || new.id::text || ':lease:' || v_lease.id::text,
      v_released_at,
      jsonb_build_object(
        'jobRunId', new.id::text,
        'jobStatus', new.status
      )
    ) on conflict (lease_id) do nothing;
  end loop;

  return new;
end;
$$;


--
-- Name: release_slack_repo_agent_monthly_run(text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_slack_repo_agent_monthly_run(p_team_id text, p_month_start date, p_slack_event_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if nullif(trim(p_team_id), '') is null then
    raise exception 'team id is required';
  end if;
  if p_month_start is null then
    raise exception 'month start is required';
  end if;
  if nullif(trim(p_slack_event_id), '') is null then
    raise exception 'slack event id is required';
  end if;

  perform pg_advisory_xact_lock(
    ('x' || substr(
      md5(
        'slack_repo_agent_month:'
        || p_team_id
        || ':'
        || to_char(p_month_start, 'YYYY-MM-DD')
      ),
      1,
      16
    ))::bit(64)::bigint
  );

  delete from public.slack_repo_agent_monthly_run_reservations
  where team_id = p_team_id
    and month_start = p_month_start
    and slack_event_id = p_slack_event_id;
end;
$$;


--
-- Name: reopen_sandbox_billing_session(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_sandbox_billing_session(p_session uuid, p_close_generation bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
begin
  update public.sandbox_billing_sessions
  set state = 'open', close_requested_at = null, updated_at = now()
  where id = p_session
    and state = 'closing'
    and close_generation = p_close_generation;
  return found;
end;
$$;


--
-- Name: request_sandbox_billing_session_close(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_sandbox_billing_session_close(p_session uuid, p_requested_at timestamp with time zone DEFAULT now()) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
  v_session public.sandbox_billing_sessions%rowtype;
begin
  select * into v_session
  from public.sandbox_billing_sessions
  where id = p_session
  for update;

  if not found then
    raise exception 'sandbox billing session % not found', p_session;
  end if;

  if v_session.state = 'open' then
    update public.sandbox_billing_sessions
    set state = 'closing',
        close_generation = close_generation + 1,
        close_requested_at = p_requested_at,
        updated_at = now()
    where id = p_session
    returning close_generation into v_session.close_generation;
  end if;

  -- Closing and terminal calls return the established generation. This keeps
  -- retries idempotent without using NULL as an overloaded state signal.
  return v_session.close_generation;
end;
$$;


--
-- Name: reserve_slack_repo_agent_monthly_run(uuid, text, date, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_slack_repo_agent_monthly_run(p_slack_installation_id uuid, p_team_id text, p_month_start date, p_slack_event_id text, p_monthly_limit integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_used integer;
begin
  if p_monthly_limit is null or p_monthly_limit <= 0 then
    return true;
  end if;

  if p_slack_installation_id is null then
    raise exception 'slack installation id is required';
  end if;
  if nullif(trim(p_team_id), '') is null then
    raise exception 'team id is required';
  end if;
  if p_month_start is null then
    raise exception 'month start is required';
  end if;
  if nullif(trim(p_slack_event_id), '') is null then
    raise exception 'slack event id is required';
  end if;

  -- Advisory lock ids are 64-bit, so this intentionally uses the first
  -- 64 bits of a stable hash. Format the date explicitly so the key does
  -- not depend on the session DateStyle.
  perform pg_advisory_xact_lock(
    ('x' || substr(
      md5(
        'slack_repo_agent_month:'
        || p_team_id
        || ':'
        || to_char(p_month_start, 'YYYY-MM-DD')
      ),
      1,
      16
    ))::bit(64)::bigint
  );

  if exists (
    select 1
    from public.slack_repo_agent_monthly_run_reservations
    where team_id = p_team_id
      and month_start = p_month_start
      and slack_event_id = p_slack_event_id
  ) then
    return true;
  end if;

  select count(*) into v_used
  from public.slack_repo_agent_monthly_run_reservations
  where team_id = p_team_id
    and month_start = p_month_start;

  if v_used >= p_monthly_limit then
    return false;
  end if;

  insert into public.slack_repo_agent_monthly_run_reservations (
    slack_installation_id,
    team_id,
    month_start,
    slack_event_id
  ) values (
    p_slack_installation_id,
    p_team_id,
    p_month_start,
    p_slack_event_id
  );

  return true;
end;
$$;


--
-- Name: resolve_agent_template_fork(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_agent_template_fork(p_user_id uuid, p_source_template text, p_name text, p_model text, p_system_prompt text, p_description text, p_category text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
-- INPUT VALIDATION CONTRACT (SECURITY DEFINER)
-- -----------------------------------------------
-- This function runs with elevated privileges (service_role effective rights).
-- It does NOT sanitize p_name, p_model, p_system_prompt, p_description, or
-- p_category beyond the length guards below and the underlying column constraints.
--
-- These parameters MUST always originate from the static PRECONFIGURED_AGENTS
-- array in lib/agents/templates.ts.  They must NEVER be derived from
-- user-supplied request body fields or any other untrusted source.
-- If a new call site is added in the future, the caller is responsible for
-- ensuring the values come exclusively from that same trusted static array.
--
-- The char_length() guards below mirror the agents table column constraints.
-- They exist as a belt-and-suspenders defence against accidental misuse;
-- they are not a substitute for validating at the call site.
declare
  v_agent_id uuid;
begin
  if p_user_id is null then
    raise exception 'user_id is required';
  end if;

  if p_source_template is null or btrim(p_source_template) = '' then
    raise exception 'source_template is required';
  end if;

  -- Input length guards — mirror the agents table column constraints.
  -- Values must always originate from PRECONFIGURED_AGENTS (see contract above).
  --
  -- NOTE: char_length(NULL) evaluates to NULL in PL/pgSQL, which is falsy in
  -- IF conditions. Each guard therefore checks IS NULL explicitly so that a
  -- NULL argument is rejected with a clear error rather than silently bypassing
  -- the guard and reaching the INSERT (where it would hit a NOT NULL column
  -- constraint with an opaque Postgres error instead of this message).
  if p_name is null or char_length(p_name) > 255 then
    raise exception 'p_name is required and must not exceed 255 characters';
  end if;
  if p_model is null or char_length(p_model) > 255 then
    raise exception 'p_model is required and must not exceed 255 characters';
  end if;
  if p_category is null or char_length(p_category) > 255 then
    raise exception 'p_category is required and must not exceed 255 characters';
  end if;
  if p_description is null or char_length(p_description) > 1000 then
    raise exception 'p_description is required and must not exceed 1000 characters';
  end if;
  if p_system_prompt is null or char_length(p_system_prompt) > 16000 then
    raise exception 'p_system_prompt is required and must not exceed 16000 characters';
  end if;

  -- Advisory lock seed 8106 is reserved exclusively for resolve_agent_template_fork.
  -- All future pg_advisory_xact_lock calls in this codebase must use a different seed
  -- to avoid aliasing. Update this comment when adding new advisory locks.
  --
  -- This advisory lock is the SOLE serialiser for the insert path (i.e. when no
  -- fork row exists yet for this user+template combination). It prevents two
  -- concurrent transactions from both finding v_agent_id IS NULL and both
  -- attempting to INSERT, which would violate uniqueness or produce duplicate rows.
  perform pg_advisory_xact_lock(
    hashtextextended(p_user_id::text || ':' || p_source_template, 8106)
  );

  -- NOTE ON FOR UPDATE: this lock clause only affects rows that already exist.
  -- PostgreSQL cannot lock a non-existent row with FOR UPDATE, so it provides
  -- no protection on the first-fork creation path (when no row is present yet).
  -- The advisory lock above is the sole serialiser for that path.
  -- FOR UPDATE here is belt-and-suspenders for the existing-row path only:
  -- it prevents a concurrent UPDATE/DELETE on the row between this SELECT and
  -- the RETURNING id below, which is otherwise benign given freeze-on-fork
  -- semantics (the row is never updated after creation).
  -- Do NOT remove the advisory lock above on the assumption that FOR UPDATE is
  -- sufficient — it is not sufficient for the insert path.
  select id into v_agent_id
  from public.agents
  where user_id = p_user_id and source_template = p_source_template
  order by created_at, id
  limit 1
  for update;

  if v_agent_id is null then
    -- FREEZE-ON-FORK SEMANTICS: the INSERT branch runs only once — when the
    -- user's fork does not yet exist. p_name, p_model, p_system_prompt,
    -- p_description, and p_category are copied from PRECONFIGURED_AGENTS at
    -- the moment the fork is created and are NEVER updated afterwards.
    --
    -- Consequences for callers and future maintainers:
    --   1. If a template definition changes in PRECONFIGURED_AGENTS (e.g. a
    --      revised system prompt or a new default model), users whose forks
    --      predate the change will NOT receive the update automatically.
    --   2. This is intentional: user forks are treated as owned copies. Users
    --      may have modified their forked agent after creation; overwriting on
    --      every resolve call would silently destroy those edits.
    --   3. If propagating template updates to existing forks is ever required,
    --      a separate migration / backfill job must be written explicitly —
    --      do NOT change the SELECT branch of this function to UPDATE, as that
    --      would lose user edits and change semantics for all callers.
    --
    -- The same freeze semantics apply in resolveAgentTemplateFork (TypeScript)
    -- and in the assignments route's resolveTemplateAgentFork dep.
    insert into public.agents (
      user_id,
      name,
      model,
      system_prompt,
      description,
      category,
      source_template
    ) values (
      p_user_id,
      p_name,
      p_model,
      p_system_prompt,
      p_description,
      p_category,
      p_source_template
    )
    returning id into v_agent_id;

    -- Guard against a silent INSERT suppression (e.g. a trigger or RLS policy
    -- that aborts the row without raising). Without this check the function
    -- would return NULL, PostgREST would surface { data: null, error: null },
    -- and the caller would receive a generic 500 with no actionable context.
    if v_agent_id is null then
      raise exception 'agent insert did not return an id for template %', p_source_template;
    end if;
  end if;

  return v_agent_id;
end;
$$;


--
-- Name: resolve_control_approval(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_control_approval(p_approval_id uuid, p_user_id uuid, p_decision text, p_source text, p_note text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
begin
  if p_decision not in ('approved', 'denied', 'expired', 'cancelled') then
    raise exception 'invalid approval decision %', p_decision;
  end if;

  update public.control_approvals
  set status = p_decision,
      resolved_at = now(),
      resolved_by = p_user_id,
      resolution_source = p_source,
      resolution_note = p_note
  where id = p_approval_id
    and user_id = p_user_id
    and status = 'pending'
    and (
      p_decision in ('expired', 'cancelled')
      or expires_at is null
      or expires_at > now()
    );

  return found;
end;
$$;


--
-- Name: rollback_billing_automation_job_start(uuid, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rollback_billing_automation_job_start(p_job_run_id uuid, p_source_ref text, p_rolled_back_at timestamp with time zone, p_metadata jsonb) RETURNS TABLE(reset boolean, lease_released boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lease public.billing_workflow_capacity_leases%rowtype;
  v_reset boolean := false;
  v_released boolean := false;
begin
  perform 1
  from public.job_runs
  where id = p_job_run_id
  for update;
  if not found then
    return query select false, false;
    return;
  end if;

  select lease.* into v_lease
  from public.billing_workflow_capacity_leases lease
  left join public.billing_workflow_capacity_release_events release
    on release.lease_id = lease.id
  where lease.root_workflow_ref = p_job_run_id::text
    and release.id is null
  order by lease.id desc
  limit 1;

  if found then
    perform 1
    from public.billing_accounts
    where id = v_lease.account_id
    for update;

    insert into public.billing_workflow_capacity_release_events (
      lease_id,
      terminal_outcome,
      source_ref,
      released_at,
      metadata
    ) values (
      v_lease.id,
      'failure',
      btrim(p_source_ref) || ':lease:' || v_lease.id::text,
      p_rolled_back_at,
      coalesce(p_metadata, '{}')
    ) on conflict (lease_id) do nothing;
    v_released := found;
  end if;

  update public.job_runs
  set status = 'pending',
      started_at = null,
      completed_at = null,
      duration_ms = null,
      input_tokens = null,
      output_tokens = null,
      error = null,
      runtime_provider = null,
      runtime_run_id = null,
      workflow_run_id = null
  where id = p_job_run_id
    and status = 'running';
  v_reset := found;

  return query select v_reset, v_released;
end;
$$;


--
-- Name: rollback_billing_automation_job_start_v2(uuid, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rollback_billing_automation_job_start_v2(p_job_run_id uuid, p_source_ref text, p_rolled_back_at timestamp with time zone, p_metadata jsonb) RETURNS TABLE(reset boolean, lease_released boolean, job_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lease public.billing_workflow_capacity_leases%rowtype;
  v_reset boolean := false;
  v_released boolean := false;
  v_job_status text;
begin
  select status into v_job_status
  from public.job_runs
  where id = p_job_run_id
  for update;
  if not found then
    return query select false, false, null::text;
    return;
  end if;

  select lease.* into v_lease
  from public.billing_workflow_capacity_leases lease
  left join public.billing_workflow_capacity_release_events release
    on release.lease_id = lease.id
  where lease.root_workflow_ref = p_job_run_id::text
    and release.id is null
  order by lease.id desc
  limit 1;

  if found then
    perform 1
    from public.billing_accounts
    where id = v_lease.account_id
    for update;

    insert into public.billing_workflow_capacity_release_events (
      lease_id,
      terminal_outcome,
      source_ref,
      released_at,
      metadata
    ) values (
      v_lease.id,
      'failure',
      btrim(p_source_ref) || ':lease:' || v_lease.id::text,
      p_rolled_back_at,
      coalesce(p_metadata, '{}')
    ) on conflict (lease_id) do nothing;
    v_released := found;
  end if;

  update public.job_runs
  set status = 'pending',
      started_at = null,
      completed_at = null,
      duration_ms = null,
      input_tokens = null,
      output_tokens = null,
      error = null,
      runtime_provider = null,
      runtime_run_id = null,
      workflow_run_id = null
  where id = p_job_run_id
    and status = 'running';
  v_reset := found;
  if v_reset then
    v_job_status := 'pending';
  end if;

  return query select v_reset, v_released, v_job_status;
end;
$$;


--
-- Name: rollup_job_run_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rollup_job_run_cost() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.job_run_id IS NOT NULL THEN
    UPDATE job_runs
       SET cost_usd = (
             SELECT SUM(cost_usd)
               FROM ai_calls
              WHERE job_run_id = NEW.job_run_id
           )
     WHERE id = NEW.job_run_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sandbox_compute_cost_on_stop(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sandbox_compute_cost_on_stop() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  closing         BOOLEAN;
  session_start   TIMESTAMPTZ;
  session_end     TIMESTAMPTZ;
  session_seconds INT;
  rate            NUMERIC := 0.0028;
  cost_delta      NUMERIC;
BEGIN
  -- Are we closing a session this UPDATE? Valid transitions:
  --   active → stopped  (full teardown)
  --   active → paused   (persistent-sandbox pause)
  closing := (
    NEW.status IN ('stopped', 'paused')
    AND (OLD.status IS NULL OR OLD.status NOT IN ('stopped', 'paused'))
  );

  IF NOT closing THEN
    RETURN NEW;
  END IF;

  session_end := COALESCE(NEW.stopped_at, now());

  -- stopped_at is a record-level field; keep writing it on a
  -- session close so the column still reflects the most recent
  -- terminating transition (stopped OR paused). Consumers that
  -- care about 'fully terminated' should join on status.
  IF NEW.stopped_at IS NULL THEN
    NEW.stopped_at := session_end;
  END IF;

  session_start := COALESCE(OLD.last_boot_started_at, OLD.created_at);
  IF session_start IS NULL THEN
    RETURN NEW;
  END IF;

  session_seconds := GREATEST(
    0,
    EXTRACT(EPOCH FROM (session_end - session_start))::int
  );

  -- If the caller already pre-computed compute_seconds /
  -- cost_cents_estimate for this UPDATE (e.g. to apply a rate
  -- override), trust their values. Otherwise accumulate onto any
  -- prior session totals stored on the row.
  IF NEW.compute_seconds IS NULL OR NEW.compute_seconds = COALESCE(OLD.compute_seconds, 0) THEN
    NEW.compute_seconds := COALESCE(OLD.compute_seconds, 0) + session_seconds;
  END IF;

  IF NEW.cost_cents_estimate IS NULL
     OR NEW.cost_cents_estimate = COALESCE(OLD.cost_cents_estimate, 0)
  THEN
    cost_delta := ROUND(session_seconds * rate, 4);
    NEW.cost_cents_estimate :=
      COALESCE(OLD.cost_cents_estimate, 0) + cost_delta;
  END IF;

  RETURN NEW;
END;
$$;


