--
-- Name: settle_slack_run_guidance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_slack_run_guidance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE settled_count INTEGER;
BEGIN
  IF NEW.ai_call_id IS DISTINCT FROM OLD.ai_call_id THEN
    NEW.slack_progress := NULL;
    NEW.slack_progress_revision := NEW.slack_progress_revision + 1;
  END IF;
  IF NEW.status NOT IN ('pending', 'streaming') OR NEW.ai_call_id IS DISTINCT FROM OLD.ai_call_id THEN
    UPDATE public.slack_run_guidance SET status = 'not_applied', updated_at = now()
      WHERE run_id = OLD.id AND user_id = OLD.user_id AND ai_call_id = OLD.ai_call_id AND status = 'received';
    GET DIAGNOSTICS settled_count = ROW_COUNT;
    IF settled_count > 0 THEN NEW.slack_progress_revision := NEW.slack_progress_revision + 1; END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: show_db_tree(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.show_db_tree() RETURNS TABLE(tree_structure text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- First show all databases
    RETURN QUERY
    SELECT ':file_folder: ' || datname || ' (DATABASE)'
    FROM pg_database 
    WHERE datistemplate = false;

    -- Then show current database structure
    RETURN QUERY
    WITH RECURSIVE 
    -- Get schemas
    schemas AS (
        SELECT 
            n.nspname AS object_name,
            1 AS level,
            n.nspname AS path,
            'SCHEMA' AS object_type
        FROM pg_namespace n
        WHERE n.nspname NOT LIKE 'pg_%' 
        AND n.nspname != 'information_schema'
    ),

    -- Get all objects (tables, views, functions, etc.)
    objects AS (
        SELECT 
            c.relname AS object_name,
            2 AS level,
            s.path || ' → ' || c.relname AS path,
            CASE c.relkind
                WHEN 'r' THEN 'TABLE'
                WHEN 'v' THEN 'VIEW'
                WHEN 'm' THEN 'MATERIALIZED VIEW'
                WHEN 'i' THEN 'INDEX'
                WHEN 'S' THEN 'SEQUENCE'
                WHEN 'f' THEN 'FOREIGN TABLE'
            END AS object_type
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        JOIN schemas s ON n.nspname = s.object_name
        WHERE c.relkind IN ('r','v','m','i','S','f')

        UNION ALL

        SELECT 
            p.proname AS object_name,
            2 AS level,
            s.path || ' → ' || p.proname AS path,
            'FUNCTION' AS object_type
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        JOIN schemas s ON n.nspname = s.object_name
    ),

    -- Combine schemas and objects
    combined AS (
        SELECT * FROM schemas
        UNION ALL
        SELECT * FROM objects
    )

    -- Final output with tree-like formatting
    SELECT 
        REPEAT('    ', level) || 
        CASE 
            WHEN level = 1 THEN '└── :open_file_folder: '
            ELSE '    └── ' || 
                CASE object_type
                    WHEN 'TABLE' THEN ':bar_chart: '
                    WHEN 'VIEW' THEN ':eye: '
                    WHEN 'MATERIALIZED VIEW' THEN ':newspaper: '
                    WHEN 'FUNCTION' THEN ':zap: '
                    WHEN 'INDEX' THEN ':mag: '
                    WHEN 'SEQUENCE' THEN ':1234: '
                    WHEN 'FOREIGN TABLE' THEN ':globe_with_meridians: '
                    ELSE ''
                END
        END || object_name || ' (' || object_type || ')'
    FROM combined
    ORDER BY path;
END;
$$;


--
-- Name: store_flow_webhook_secret(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_flow_webhook_secret(p_flow_id uuid, p_user_id uuid, p_secret text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing_secret_id uuid;
  v_new_secret_id uuid;
begin
  -- Serialize rotations for this flow so concurrent requests cannot both
  -- create a secret and orphan the loser.
  select vault_webhook_secret_id into v_existing_secret_id
  from public.flows
  where id = p_flow_id
    and user_id = p_user_id
  for update;

  if not found then
    raise exception 'Flow not found';
  end if;

  if v_existing_secret_id is not null then
    delete from vault.secrets where id = v_existing_secret_id;
  end if;

  select vault.create_secret(
    p_secret,
    'flow/' || p_flow_id::text || '/webhook_secret',
    'Signed webhook secret for workflow ' || p_flow_id::text
  ) into v_new_secret_id;

  if v_new_secret_id is null then
    raise exception 'vault.create_secret returned null for flow %', p_flow_id;
  end if;

  update public.flows
  set vault_webhook_secret_id = v_new_secret_id,
      updated_at = now()
  where id = p_flow_id
    and user_id = p_user_id;

  return v_new_secret_id;
end;
$$;


--
-- Name: store_oauth_token(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_oauth_token(p_user_id uuid, p_provider text, p_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing_secret_id uuid;
  v_new_secret_id uuid;
begin
  select vault_secret_id into v_existing_secret_id
  from public.oauth_tokens
  where user_id = p_user_id and provider = p_provider;

  if v_existing_secret_id is not null then
    delete from vault.secrets where id = v_existing_secret_id;
  end if;

  select vault.create_secret(
    p_token,
    p_user_id || '/' || p_provider || '/oauth',
    'OAuth token for ' || p_provider
  ) into v_new_secret_id;

  insert into public.oauth_tokens (user_id, provider, vault_secret_id, updated_at)
  values (p_user_id, p_provider, v_new_secret_id, now())
  on conflict (user_id, provider)
  do update set vault_secret_id = v_new_secret_id, updated_at = now();
end;
$$;


--
-- Name: store_provider_key(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_provider_key(p_user_id uuid, p_provider text, p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing_secret_id UUID;
  v_new_secret_id UUID;
BEGIN
  -- Check for existing mapping
  SELECT vault_secret_id INTO v_existing_secret_id
  FROM provider_keys
  WHERE user_id = p_user_id AND provider = p_provider;

  IF v_existing_secret_id IS NOT NULL THEN
    -- Remove old secret
    DELETE FROM vault.secrets WHERE id = v_existing_secret_id;
  END IF;

  -- Use vault.create_secret() which has pgsodium permissions
  SELECT vault.create_secret(
    p_key,
    p_user_id || '/' || p_provider,
    'Provider API key for ' || p_provider
  ) INTO v_new_secret_id;

  -- Upsert mapping
  INSERT INTO provider_keys (user_id, provider, vault_secret_id, updated_at)
  VALUES (p_user_id, p_provider, v_new_secret_id, NOW())
  ON CONFLICT (user_id, provider)
  DO UPDATE SET vault_secret_id = v_new_secret_id, updated_at = NOW();
END;
$$;


--
-- Name: store_slack_bot_token(text, text); Type: FUNCTION; Schema: public; Owner: -
