--
-- Name: transfer_team_ownership(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_team_ownership(p_team_id uuid, p_current_owner_user_id uuid, p_next_owner_user_id uuid) RETURNS TABLE(previous_owner_user_id uuid, next_owner_user_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_team_owner_user_id uuid;
  v_current_owner_role text;
  v_next_owner_role text;
begin
  if p_current_owner_user_id = p_next_owner_user_id then
    raise exception 'cannot transfer ownership to the current owner'
      using errcode = 'check_violation';
  end if;

  select owner_user_id
    into v_team_owner_user_id
  from public.teams
  where id = p_team_id
  for update;

  if v_team_owner_user_id is null then
    raise exception 'team not found'
      using errcode = 'no_data_found';
  end if;

  if v_team_owner_user_id <> p_current_owner_user_id then
    raise exception 'only the current owner can transfer team ownership'
      using errcode = 'insufficient_privilege';
  end if;

  select role
    into v_current_owner_role
  from public.team_members
  where team_id = p_team_id
    and user_id = p_current_owner_user_id
  for update;

  if v_current_owner_role is null or v_current_owner_role <> 'owner' then
    raise exception 'current owner membership not found'
      using errcode = 'raise_exception';
  end if;

  select role
    into v_next_owner_role
  from public.team_members
  where team_id = p_team_id
    and user_id = p_next_owner_user_id
  for update;

  if v_next_owner_role is null then
    raise exception 'next owner is not a team member'
      using errcode = 'no_data_found';
  end if;

  if v_next_owner_role <> 'admin' then
    raise exception 'ownership can only transfer to an admin'
      using errcode = 'check_violation';
  end if;

  update public.team_members
  set role = 'owner'
  where team_id = p_team_id
    and user_id = p_next_owner_user_id;

  update public.team_members
  set role = 'admin'
  where team_id = p_team_id
    and user_id = p_current_owner_user_id;

  update public.teams
  set owner_user_id = p_next_owner_user_id,
      updated_at = now()
  where id = p_team_id;

  previous_owner_user_id := p_current_owner_user_id;
  next_owner_user_id := p_next_owner_user_id;
  return next;
end;
$$;


--
-- Name: transition_orchestration_run(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_orchestration_run(p_run_id uuid, p_from_status text, p_to_status text, p_error text DEFAULT NULL::text, p_metadata_patch jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
  v_current text;
begin
  select status into v_current
  from public.orchestration_runs
  where id = p_run_id
  for update;

  if not found then
    raise exception 'orchestration_run % not found', p_run_id;
  end if;

  if v_current <> p_from_status then
    return false;
  end if;

  update public.orchestration_runs
  set status = p_to_status,
      error = case when p_to_status in ('failed', 'cancelled')
        then coalesce(p_error, error) else p_error end,
      metadata = case when p_metadata_patch is not null
        then metadata || p_metadata_patch else metadata end
  where id = p_run_id;

  return true;
end;
$$;


--
-- Name: transition_orchestration_task(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_orchestration_task(p_task_id uuid, p_from_status text, p_to_status text, p_error text DEFAULT NULL::text, p_metadata_patch jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
  v_current text;
begin
  select status into v_current
  from public.orchestration_tasks
  where id = p_task_id
  for update;

  if not found then
    raise exception 'orchestration_task % not found', p_task_id;
  end if;

  if v_current <> p_from_status then
    return false;
  end if;

  update public.orchestration_tasks
  set status = p_to_status,
      error = case when p_to_status in ('failed', 'conflict', 'needs_user')
        then coalesce(p_error, error) else p_error end,
      metadata = case when p_metadata_patch is not null
        then metadata || p_metadata_patch else metadata end,
      pushed_at = case when p_to_status = 'pushed'
        then coalesce(pushed_at, now()) else pushed_at end
  where id = p_task_id;

  return true;
end;
$$;


--
-- Name: update_orchestration_run(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_orchestration_run(p_run_id uuid, p_user_id uuid, p_title text DEFAULT NULL::text, p_approval_mode text DEFAULT NULL::text, p_metadata_patch jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
begin
  update public.orchestration_runs
  set title = coalesce(p_title, title),
      approval_mode = coalesce(p_approval_mode, approval_mode),
      metadata = case when p_metadata_patch is not null
        then metadata || p_metadata_patch else metadata end
  where id = p_run_id and user_id = p_user_id;

  return found;
end;
$$;


--
-- Name: update_user_mcp_server_secret(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_mcp_server_secret(p_secret_id uuid, p_user_id uuid, p_server_id uuid, p_slot text, p_secret text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform vault.update_secret(
    p_secret_id,
    p_secret,
    'user_mcp_servers/' || p_user_id || '/' || p_server_id || '/' || p_slot,
    'MCP server secret for ' || p_slot
  );
end;
$$;


--
-- Name: upgrade_deprecated_model_pins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upgrade_deprecated_model_pins() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  upgraded_flows INTEGER := 0;
  upgraded_agents INTEGER := 0;
  upgraded_profiles INTEGER := 0;
BEGIN
  DROP TABLE IF EXISTS pg_temp.user_upgrades;

  CREATE TEMPORARY TABLE user_upgrades ON COMMIT DROP AS
  SELECT
    p.id AS user_id,
    s.deprecated_model_id,
    s.successor_model_id
  FROM public.profiles p
  -- Availability is enforced by the view.
  CROSS JOIN public.model_supersessions_effective s
  WHERE p.auto_enable_new_models
    -- Never upgrade onto a model the user explicitly turned off.
    AND NOT EXISTS (
      SELECT 1
      FROM public.user_model_preferences ump
      WHERE ump.user_id = p.id
        AND ump.model_id = s.successor_model_id
        AND ump.is_enabled = false
    )
    -- Never upgrade onto a model one of the user's teams forbids while that
    -- team still permits what is pinned today.
    AND NOT EXISTS (
      SELECT 1
      FROM public.team_members tm
      JOIN public.teams t ON t.id = tm.team_id
      WHERE tm.user_id = p.id
        AND t.model_allowlist IS NOT NULL
        AND t.model_allowlist @> ARRAY[s.deprecated_model_id]
        AND NOT (t.model_allowlist @> ARRAY[s.successor_model_id])
    );

  -- Steady state on essentially every cron run: mappings exist but nobody holds
  -- a pin that needs moving. Return before touching flows — otherwise the
  -- driving query expands jsonb_array_elements(draft_graph->'nodes') across
  -- every flow row with an array `nodes`, and a correlated semi-join is not
  -- something to rely on the planner short-circuiting.
  IF NOT EXISTS (SELECT 1 FROM user_upgrades) THEN
    DROP TABLE IF EXISTS pg_temp.user_upgrades;
    RETURN jsonb_build_object('flows', 0, 'agents', 0, 'profiles', 0);
  END IF;

  CREATE INDEX ON user_upgrades (user_id, deprecated_model_id);

  -- 1) Automation pins: agent nodes' data.modelOverride in the draft graph.
  --    The rewrite is computed in the SET expression, against the locked row,
  --    so a concurrent autosave cannot be clobbered (see header).
  UPDATE public.flows f
  SET draft_graph = jsonb_set(
        f.draft_graph,
        '{nodes}',
        (
          SELECT COALESCE(
            jsonb_agg(
              CASE
                WHEN elem.node->>'type' = 'agent'
                 AND u.successor_model_id IS NOT NULL
                  THEN jsonb_set(
                    elem.node,
                    '{data,modelOverride}',
                    to_jsonb(u.successor_model_id)
                  )
                ELSE elem.node
              END
              ORDER BY elem.ordinality
            ),
            '[]'::jsonb
          )
          FROM jsonb_array_elements(f.draft_graph->'nodes')
            WITH ORDINALITY AS elem(node, ordinality)
          LEFT JOIN user_upgrades u
            ON u.user_id = f.user_id
           AND u.deprecated_model_id = elem.node->'data'->>'modelOverride'
        )
      )
  WHERE jsonb_typeof(f.draft_graph->'nodes') = 'array'
    AND EXISTS (
      SELECT 1
      FROM jsonb_array_elements(f.draft_graph->'nodes') AS n(node)
      JOIN user_upgrades u
        ON u.user_id = f.user_id
       AND u.deprecated_model_id = n.node->'data'->>'modelOverride'
      WHERE n.node->>'type' = 'agent'
    );
  GET DIAGNOSTICS upgraded_flows = ROW_COUNT;

  -- 2) Agent base models (what a node without an override runs on).
  UPDATE public.agents a
  SET model = u.successor_model_id
  FROM user_upgrades u
  WHERE u.user_id = a.user_id
    AND a.model = u.deprecated_model_id;
  GET DIAGNOSTICS upgraded_agents = ROW_COUNT;

  -- 3) Per-user default model.
  UPDATE public.profiles p
  SET default_model = u.successor_model_id
  FROM user_upgrades u
  WHERE u.user_id = p.id
    AND p.default_model = u.deprecated_model_id;
  GET DIAGNOSTICS upgraded_profiles = ROW_COUNT;

  DROP TABLE IF EXISTS pg_temp.user_upgrades;

  RETURN jsonb_build_object(
    'flows', upgraded_flows,
    'agents', upgraded_agents,
    'profiles', upgraded_profiles
  );
END;
$$;


--
-- Name: FUNCTION upgrade_deprecated_model_pins(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upgrade_deprecated_model_pins() IS 'Repoints saved model references (flows.draft_graph agent modelOverride, agents.model, profiles.default_model) at the successor recorded in model_supersessions. Called by /api/cron/sync-models. Guards, all fail-closed: successor must appear in model_supersessions_effective; profiles.auto_enable_new_models must be true; the user must not have explicitly disabled the successor; and no team the user belongs to may permit the deprecated model while forbidding the successor. Deliberately does NOT touch flow_versions.graph (immutable published snapshots — the runtime resolver in lib/models/supersession-runtime.ts handles those at invocation time) or ai_calls.model (historical cost attribution). COST: the candidate set is profiles CROSS JOIN model_supersessions_effective, rebuilt every run, so cost scales with total profiles rather than affected pins. Intentional at current scale; if profiles exceed ~10k or this shows up in cron timings, pre-filter the candidate set to users who actually hold a deprecated pin before applying the consent guards.';


--
-- Name: upsert_connection_by_source_preset(uuid, text, text, text, text, text, text, text, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_connection_by_source_preset(p_user_id uuid, p_source_preset text, p_name text, p_type text, p_auth_type text, p_auth_header text, p_mcp_transport text, p_mcp_url text, p_encrypted_credentials text, p_description text, p_oauth_client_id text, p_oauth_authorize_url text, p_oauth_token_url text, p_oauth_scopes text, p_oauth_authorized_at timestamp with time zone, p_oauth_token_expires_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_connection_id uuid;
begin
  if p_source_preset is null or btrim(p_source_preset) = '' then
    raise exception 'source_preset is required';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_user_id::text || ':' || p_source_preset, 5504)
  );

  select id into v_connection_id
  from public.connections
  where user_id = p_user_id and source_preset = p_source_preset
  order by created_at
  limit 1
  for update;

  if v_connection_id is null then
    insert into public.connections (
      user_id,
      source_preset,
      name,
      type,
      auth_type,
      auth_header,
      mcp_transport,
      mcp_url,
      encrypted_credentials,
      description,
      oauth_client_id,
      oauth_authorize_url,
      oauth_token_url,
      oauth_scopes,
      oauth_authorized_at,
      oauth_token_expires_at
    ) values (
      p_user_id,
      p_source_preset,
      p_name,
      p_type,
      p_auth_type,
      p_auth_header,
      p_mcp_transport,
      p_mcp_url,
      p_encrypted_credentials,
      p_description,
      p_oauth_client_id,
      p_oauth_authorize_url,
      p_oauth_token_url,
      p_oauth_scopes,
      p_oauth_authorized_at,
      p_oauth_token_expires_at
    )
    returning id into v_connection_id;
  else
    update public.connections
    set
      name = p_name,
      type = p_type,
      auth_type = p_auth_type,
      auth_header = p_auth_header,
      mcp_transport = p_mcp_transport,
      mcp_url = p_mcp_url,
      encrypted_credentials = p_encrypted_credentials,
      description = p_description,
      oauth_client_id = p_oauth_client_id,
      oauth_authorize_url = p_oauth_authorize_url,
      oauth_token_url = p_oauth_token_url,
      oauth_scopes = p_oauth_scopes,
      oauth_authorized_at = p_oauth_authorized_at,
      oauth_token_expires_at = p_oauth_token_expires_at,
      updated_at = now()
    where id = v_connection_id;
  end if;

  return v_connection_id;
end;
$$;


