--
-- Name: billing_accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_type text NOT NULL,
    owner_user_id uuid,
    product_team_id uuid,
    stripe_customer_id text,
    stripe_subscription_id text,
    tier text DEFAULT 'free'::text NOT NULL,
    period_anchor date,
    auto_topup_enabled boolean DEFAULT false NOT NULL,
    auto_topup_threshold_cents bigint DEFAULT 500 NOT NULL,
    auto_topup_amount_cents bigint DEFAULT 2500 NOT NULL,
    budget_cap_cents bigint,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    subscription_checkout_generation bigint DEFAULT 0 NOT NULL,
    sandbox_usage_remainder_units bigint DEFAULT 0 NOT NULL,
    token_usage_remainder_cost_units bigint DEFAULT 0 NOT NULL,
    plan_code text,
    plan_audience text DEFAULT 'legacy'::text NOT NULL,
    max_named_users integer,
    included_concurrency integer DEFAULT 0 NOT NULL,
    included_retained_bytes bigint DEFAULT 0 NOT NULL,
    included_hosted_usage_cents bigint DEFAULT 0 NOT NULL,
    entitlement_catalog_version text DEFAULT 'capacity_v2'::text NOT NULL,
    entitlement_version bigint DEFAULT 0 NOT NULL,
    entitlement_enforcement_mode text DEFAULT 'shadow'::text NOT NULL,
    entitlement_projection_effective_at timestamp with time zone,
    entitlement_projection_event_id text,
    entitlement_projection_priority smallint DEFAULT 0 NOT NULL,
    billing_event_sequence bigint DEFAULT 0 NOT NULL,
    CONSTRAINT billing_accounts_billing_event_sequence_check CHECK ((billing_event_sequence >= 0)),
    CONSTRAINT billing_accounts_entitlement_enforcement_mode_check CHECK ((entitlement_enforcement_mode = ANY (ARRAY['shadow'::text, 'meter_only'::text, 'enforced'::text]))),
    CONSTRAINT billing_accounts_entitlement_projection_priority_check CHECK ((entitlement_projection_priority = ANY (ARRAY[0, 100]))),
    CONSTRAINT billing_accounts_entitlement_version_check CHECK ((entitlement_version >= 0)),
    CONSTRAINT billing_accounts_included_concurrency_check CHECK ((included_concurrency >= 0)),
    CONSTRAINT billing_accounts_included_hosted_usage_cents_check CHECK ((included_hosted_usage_cents >= 0)),
    CONSTRAINT billing_accounts_included_retained_bytes_check CHECK ((included_retained_bytes >= 0)),
    CONSTRAINT billing_accounts_max_named_users_check CHECK (((max_named_users IS NULL) OR (max_named_users > 0))),
    CONSTRAINT billing_accounts_owner_shape CHECK ((((owner_type = 'user'::text) AND (owner_user_id IS NOT NULL) AND (product_team_id IS NULL)) OR ((owner_type = 'team'::text) AND (product_team_id IS NOT NULL) AND (owner_user_id IS NULL)))),
    CONSTRAINT billing_accounts_owner_type_check CHECK ((owner_type = ANY (ARRAY['user'::text, 'team'::text]))),
    CONSTRAINT billing_accounts_plan_audience_check CHECK ((plan_audience = ANY (ARRAY['legacy'::text, 'individual'::text, 'business'::text, 'enterprise'::text]))),
    CONSTRAINT billing_accounts_plan_code_check CHECK (((plan_code IS NULL) OR (plan_code = ANY (ARRAY['pro'::text, 'plus'::text, 'max'::text, 'business'::text, 'enterprise'::text])))),
    CONSTRAINT billing_accounts_sandbox_usage_remainder_check CHECK (((sandbox_usage_remainder_units >= 0) AND (sandbox_usage_remainder_units < 600000000))),
    CONSTRAINT billing_accounts_status_check CHECK ((status = ANY (ARRAY['active'::text, 'past_due'::text, 'frozen_topups'::text]))),
    CONSTRAINT billing_accounts_tier_check CHECK ((tier = ANY (ARRAY['free'::text, 'pro'::text, 'team'::text, 'business'::text])))
);


