--

CREATE VIEW public.billing_active_workflow_capacity_leases WITH (security_invoker='true') AS
 SELECT lease.id,
    lease.account_id,
    lease.lease_ref,
    lease.source_ref,
    lease.root_workflow_ref,
    lease.accounting_mode,
    lease.concurrency_limit,
    lease.active_before,
    lease.would_admit,
    lease.acquired_at,
    lease.metadata,
    lease.recorded_at
   FROM (public.billing_workflow_capacity_leases lease
     LEFT JOIN public.billing_workflow_capacity_release_events release ON ((release.lease_id = lease.id)))
  WHERE (release.id IS NULL);


