-- Name: billing_annual_grant_schedules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_annual_grant_schedules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    stripe_subscription_id text NOT NULL,
