    price_lookup_key text NOT NULL,
    included_usage_cents bigint NOT NULL,
    cycle_started_at timestamp with time zone NOT NULL,
    grant_offset smallint NOT NULL,
    grant_period text NOT NULL,
    due_at timestamp with time zone NOT NULL,
    source_event_id text NOT NULL,
    runtime_run_id text,
    status text DEFAULT 'pending'::text NOT NULL,
    completed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_annual_grant_schedules_due_after_cycle CHECK ((due_at > cycle_started_at)),
    CONSTRAINT billing_annual_grant_schedules_entitlement_version_check CHECK ((entitlement_version > 0)),
    CONSTRAINT billing_annual_grant_schedules_grant_offset_check CHECK (((grant_offset >= 1) AND (grant_offset <= 11))),
    CONSTRAINT billing_annual_grant_schedules_grant_period_check CHECK ((grant_period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'::text)),
    CONSTRAINT billing_annual_grant_schedules_included_usage_cents_check CHECK ((included_usage_cents > 0)),
    CONSTRAINT billing_annual_grant_schedules_plan_shape CHECK ((((price_lookup_key = 'capacity_v2_pro_annual'::text) AND (included_usage_cents = 500)) OR ((price_lookup_key = 'capacity_v2_plus_annual'::text) AND (included_usage_cents = 2500)) OR ((price_lookup_key = 'capacity_v2_max_annual'::text) AND (included_usage_cents = 5000)))),
    CONSTRAINT billing_annual_grant_schedules_price_lookup_key_check CHECK ((btrim(price_lookup_key) <> ''::text)),
    CONSTRAINT billing_annual_grant_schedules_source_event_id_check CHECK ((btrim(source_event_id) <> ''::text)),
    CONSTRAINT billing_annual_grant_schedules_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'cancel_pending'::text, 'completed'::text, 'cancelled'::text]))),
    CONSTRAINT billing_annual_grant_schedules_stripe_subscription_id_check CHECK ((btrim(stripe_subscription_id) <> ''::text)),
    CONSTRAINT billing_annual_grant_schedules_terminal_shape CHECK ((((status = 'completed'::text) AND (completed_at IS NOT NULL) AND (cancelled_at IS NULL)) OR ((status = 'cancelled'::text) AND (cancelled_at IS NOT NULL) AND (completed_at IS NULL)) OR ((status = ANY (ARRAY['pending'::text, 'cancel_pending'::text])) AND (completed_at IS NULL) AND (cancelled_at IS NULL))))
);


