    CONSTRAINT billing_entitlement_items_concurrency_delta_check CHECK ((concurrency_delta >= 0)),
    CONSTRAINT billing_entitlement_items_hosted_usage_cents_delta_check CHECK ((hosted_usage_cents_delta >= 0)),
    CONSTRAINT billing_entitlement_items_item_kind_check CHECK ((item_kind = ANY (ARRAY['plan'::text, 'concurrency_addon'::text, 'retained_data_addon'::text]))),
    CONSTRAINT billing_entitlement_items_item_ref_check CHECK ((btrim(item_ref) <> ''::text)),
    CONSTRAINT billing_entitlement_items_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT billing_entitlement_items_price_lookup_key_check CHECK ((btrim(price_lookup_key) <> ''::text)),
    CONSTRAINT billing_entitlement_items_quantity_check CHECK ((quantity >= 0)),
    CONSTRAINT billing_entitlement_items_retained_data_bytes_delta_check CHECK ((retained_data_bytes_delta >= 0)),
    CONSTRAINT billing_entitlement_items_source_event_id_check CHECK ((btrim(source_event_id) <> ''::text))
);


--
-- Name: billing_current_entitlement_items; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_current_entitlement_items WITH (security_invoker='true') AS
 SELECT DISTINCT ON (account_id, item_ref) id,
    account_id,
    item_ref,
    item_kind,
    price_lookup_key,
    quantity,
    concurrency_delta,
    retained_data_bytes_delta,
    hosted_usage_cents_delta,
    effective_at,
    source_event_id,
    metadata,
    recorded_at
   FROM public.billing_entitlement_items
  WHERE (effective_at <= now())
  ORDER BY account_id, item_ref, effective_at DESC, id DESC;


--
-- Name: billing_provider_cost_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_provider_cost_events (
    id bigint NOT NULL,
    provider text NOT NULL,
    provider_event_id text NOT NULL,
    cost_source text NOT NULL,
    account_id uuid,
    shared_overhead_category text,
    provider_cost_micros bigint NOT NULL,
    provider_currency text DEFAULT 'USD'::text NOT NULL,
    normalized_cost_micros bigint NOT NULL,
    retail_debit_micros bigint NOT NULL,
    billing_treatment text NOT NULL,
    pricing_rule_version text NOT NULL,
    measured_quantity numeric(30,9),
    measured_unit text,
    operation_ref text,
    root_workflow_ref text,
    run_ref text,
    sandbox_ref text,
    artifact_ref text,
    occurred_at timestamp with time zone NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_provider_cost_events_billing_treatment_check CHECK ((billing_treatment = ANY (ARRAY['capacity_revenue'::text, 'hosted_usage'::text, 'shared_overhead'::text]))),
    CONSTRAINT billing_provider_cost_events_cost_source_check CHECK ((cost_source = ANY (ARRAY['ai'::text, 'trigger'::text, 'sandbox_compute'::text, 'sandbox_transfer'::text, 'retained_data'::text, 'vercel_function'::text, 'database'::text, 'email'::text, 'object_storage'::text, 'transfer'::text, 'observability'::text, 'other'::text]))),
    CONSTRAINT billing_provider_cost_events_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT billing_provider_cost_events_normalized_cost_micros_check CHECK ((normalized_cost_micros >= 0)),
    CONSTRAINT billing_provider_cost_events_owner_shape CHECK ((((account_id IS NOT NULL) AND (shared_overhead_category IS NULL) AND (billing_treatment <> 'shared_overhead'::text)) OR ((account_id IS NULL) AND (shared_overhead_category IS NOT NULL) AND (billing_treatment = 'shared_overhead'::text)))),
    CONSTRAINT billing_provider_cost_events_pricing_rule_version_check CHECK ((btrim(pricing_rule_version) <> ''::text)),
    CONSTRAINT billing_provider_cost_events_provider_check CHECK ((btrim(provider) <> ''::text)),
    CONSTRAINT billing_provider_cost_events_provider_cost_micros_check CHECK ((provider_cost_micros >= 0)),
    CONSTRAINT billing_provider_cost_events_provider_currency_check CHECK ((char_length(provider_currency) = 3)),
    CONSTRAINT billing_provider_cost_events_provider_event_id_check CHECK ((btrim(provider_event_id) <> ''::text)),
    CONSTRAINT billing_provider_cost_events_retail_debit_micros_check CHECK ((retail_debit_micros >= 0)),
    CONSTRAINT billing_provider_cost_events_retail_shape CHECK (((billing_treatment = 'hosted_usage'::text) OR (retail_debit_micros = 0)))
);


--
-- Name: billing_customer_retail_cost_operations; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_customer_retail_cost_operations WITH (security_invoker='true') AS
 SELECT account_id,
    COALESCE(operation_ref, root_workflow_ref, run_ref, sandbox_ref, provider_event_id) AS operation_ref,
    (sum(retail_debit_micros))::bigint AS retail_debit_micros,
    max(occurred_at) AS occurred_at,
    max(COALESCE(NULLIF((metadata ->> 'customer_description'::text), ''::text), 'Hosted work'::text)) AS description
   FROM public.billing_provider_cost_events event
  WHERE ((account_id IS NOT NULL) AND (billing_treatment = 'hosted_usage'::text))
  GROUP BY account_id, COALESCE(operation_ref, root_workflow_ref, run_ref, sandbox_ref, provider_event_id);


--
-- Name: billing_customer_retail_cost_items; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_customer_retail_cost_items WITH (security_invoker='true') AS
 WITH normalized AS (
         SELECT event.account_id,
            COALESCE(event.operation_ref, event.root_workflow_ref, event.run_ref, event.sandbox_ref, event.provider_event_id) AS operation_ref,
            event.cost_source,
            event.retail_debit_micros
           FROM public.billing_provider_cost_events event
          WHERE ((event.account_id IS NOT NULL) AND (event.billing_treatment = 'hosted_usage'::text))
        )
 SELECT normalized.account_id,
    normalized.operation_ref,
    normalized.cost_source,
    (sum(normalized.retail_debit_micros))::bigint AS retail_debit_micros,
    operation.occurred_at
   FROM (normalized
     JOIN public.billing_customer_retail_cost_operations operation ON (((operation.account_id = normalized.account_id) AND (operation.operation_ref = normalized.operation_ref))))
  GROUP BY normalized.account_id, normalized.operation_ref, normalized.cost_source, operation.occurred_at;


