--
-- Name: billing_open_cost_reservations; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_open_cost_reservations WITH (security_invoker='true') AS
 SELECT reservation.id,
    reservation.account_id,
    reservation.reservation_ref,
    reservation.source_ref,
    reservation.operation_ref,
    reservation.root_workflow_ref,
    reservation.reserved_micros,
    reservation.basis,
    reservation.basis_version,
    reservation.accounting_mode,
    reservation.balance_micros_before,
    reservation.open_reserved_micros_before,
    reservation.spendable_micros_before,
    reservation.would_admit,
    reservation.expires_at,
    reservation.metadata,
    reservation.created_at
   FROM (public.billing_cost_reservations reservation
     LEFT JOIN public.billing_cost_reservation_terminal_events terminal ON ((terminal.reservation_id = reservation.id)))
  WHERE (terminal.id IS NULL);


