--
-- Name: billing_retained_data_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_retained_data_events (
    id bigint NOT NULL,
    account_id uuid NOT NULL,
    resource_type text NOT NULL,
    resource_ref text NOT NULL,
    delta_bytes bigint NOT NULL,
    source_ref text NOT NULL,
    operation_ref text,
    accounting_mode text NOT NULL,
    retained_limit_bytes bigint NOT NULL,
    logical_bytes_before bigint NOT NULL,
    logical_bytes_after bigint NOT NULL,
    would_admit boolean NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_retained_data_events_accounting_mode_check CHECK ((accounting_mode = ANY (ARRAY['shadow'::text, 'meter_only'::text]))),
    CONSTRAINT billing_retained_data_events_delta_bytes_check CHECK ((delta_bytes <> 0)),
    CONSTRAINT billing_retained_data_events_logical_bytes_after_check CHECK ((logical_bytes_after >= 0)),
    CONSTRAINT billing_retained_data_events_logical_bytes_before_check CHECK ((logical_bytes_before >= 0)),
    CONSTRAINT billing_retained_data_events_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT billing_retained_data_events_resource_ref_check CHECK ((btrim(resource_ref) <> ''::text)),
    CONSTRAINT billing_retained_data_events_resource_type_check CHECK ((resource_type = ANY (ARRAY['workflow_history'::text, 'node_run_history'::text, 'job_run_history'::text, 'ai_call_history'::text, 'automation_dispatch_history'::text, 'logs_events'::text, 'review_finding'::text, 'generated_artifact'::text, 'customer_upload'::text, 'sandbox_snapshot'::text]))),
    CONSTRAINT billing_retained_data_events_retained_limit_bytes_check CHECK ((retained_limit_bytes >= 0)),
    CONSTRAINT billing_retained_data_events_source_ref_check CHECK ((btrim(source_ref) <> ''::text))
);


--
-- Name: billing_retained_data_events_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.billing_retained_data_events ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.billing_retained_data_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


