--

CREATE TABLE public.billing_retained_data_rollups (
    account_id uuid NOT NULL,
    resource_type text NOT NULL,
    logical_bytes bigint NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_retained_data_rollups_logical_bytes_check CHECK ((logical_bytes >= 0)),
    CONSTRAINT billing_retained_data_rollups_resource_type_check CHECK ((resource_type = ANY (ARRAY['workflow_history'::text, 'node_run_history'::text, 'job_run_history'::text, 'ai_call_history'::text, 'automation_dispatch_history'::text, 'logs_events'::text, 'review_finding'::text, 'generated_artifact'::text, 'customer_upload'::text, 'sandbox_snapshot'::text])))
);


--
-- Name: billing_retained_data_totals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_retained_data_totals WITH (security_invoker='true') AS
 SELECT account_id,
    (sum(logical_bytes))::bigint AS logical_bytes
   FROM public.billing_retained_data_rollups
  GROUP BY account_id;


