--
-- Name: model_supersessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.model_supersessions (
    deprecated_model_id text NOT NULL,
    successor_model_id text NOT NULL,
    reason text DEFAULT 'anthropic_newest_version'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT model_supersessions_distinct CHECK ((deprecated_model_id <> successor_model_id))
);


--
-- Name: TABLE model_supersessions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.model_supersessions IS 'Deprecated model id -> the model that replaced it, recorded when the sync cron retires an Anthropic model because a newer same-priced version of the same family shipped. Rows are terminal: a deprecated id always points directly at a model that is not itself deprecated (maintained by planSupersessionWrites in lib/models/model-supersessions.ts). Read via model_supersessions_effective, which additionally filters to successors the catalog is currently offering.';


--
-- Name: model_supersessions_effective; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.model_supersessions_effective WITH (security_invoker='true') AS
 SELECT s.deprecated_model_id,
    s.successor_model_id
   FROM (public.model_supersessions s
     JOIN public.ai_models successor ON (((successor.id = s.successor_model_id) AND successor.is_available AND (COALESCE(successor.is_hidden, false) = false))))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.ai_models deprecated
          WHERE ((deprecated.id = s.deprecated_model_id) AND deprecated.is_available AND (COALESCE(deprecated.is_hidden, false) = false)))));


--
-- Name: VIEW model_supersessions_effective; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.model_supersessions_effective IS 'Supersessions currently in effect: the successor is on offer and the deprecated model is not. Read by the runtime model resolver and by upgrade_deprecated_model_pins(). Retraction is primarily handled by the sync cron, which DELETEs a mapping once the newest-version policy retains the deprecated model again (see reconcileSupersessions in app/api/cron/sync-models/route.ts). The deprecated-side filter here is a secondary net for a model that is both available and visible; it is inert for models hidden by the stale sweep, since that hide is deliberately durable.';


