COMMENT ON COLUMN public.waitlist_requests.issued_code IS 'Operator-assigned access code, once approved. Nullable until approval.';


--
-- Name: COLUMN waitlist_requests.updated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.waitlist_requests.updated_at IS 'Bumped by the app on every upsert. Lets the route distinguish a fresh insert from a duplicate submission without a timing heuristic.';


--
-- Name: workspaces; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspaces (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    is_default boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sandbox_billing_mode text DEFAULT 'platform'::text NOT NULL,
    sandbox_vercel_team_id text,
    sandbox_vercel_project_id text,
    vercel_link_status text DEFAULT 'unknown'::text NOT NULL,
    vercel_link_checked_at timestamp with time zone,
    vercel_link_error_code text,
    vercel_link_message text,
    sandbox_timeout_ms integer DEFAULT 600000 NOT NULL,
    sandbox_idle_timeout_ms integer,
    owner_type text DEFAULT 'user'::text NOT NULL,
    owner_user_id uuid,
    product_team_id uuid,
    created_by_user_id uuid,
    CONSTRAINT workspaces_owner_shape_check CHECK ((((owner_type = 'user'::text) AND (owner_user_id IS NOT NULL) AND (product_team_id IS NULL)) OR ((owner_type = 'team'::text) AND (owner_user_id IS NULL) AND (product_team_id IS NOT NULL)))),
    CONSTRAINT workspaces_owner_type_check CHECK ((owner_type = ANY (ARRAY['user'::text, 'team'::text]))),
    CONSTRAINT workspaces_sandbox_billing_mode_check CHECK ((sandbox_billing_mode = ANY (ARRAY['platform'::text, 'user_vercel_project'::text]))),
    CONSTRAINT workspaces_vercel_link_status_check CHECK ((vercel_link_status = ANY (ARRAY['unknown'::text, 'valid'::text, 'missing_project'::text, 'auth_invalid'::text, 'inaccessible'::text])))
);


--
-- Name: buckets; Type: TABLE; Schema: storage; Owner: -
--

CREATE TABLE storage.buckets (
    id text NOT NULL,
    name text NOT NULL,
    public boolean DEFAULT false NOT NULL,
    file_size_limit bigint,
    allowed_mime_types text[],
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: objects; Type: TABLE; Schema: storage; Owner: -
--

CREATE TABLE storage.objects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    bucket_id text,
    name text,
    owner uuid,
    owner_id text,
    metadata jsonb,
    path_tokens text[] GENERATED ALWAYS AS (string_to_array(name, '/'::text)) STORED,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_accessed_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: secrets; Type: TABLE; Schema: vault; Owner: -
--

CREATE TABLE vault.secrets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text,
    description text DEFAULT ''::text NOT NULL,
    secret text NOT NULL,
    key_id uuid,
    nonce bytea,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE secrets; Type: COMMENT; Schema: vault; Owner: -
--

COMMENT ON TABLE vault.secrets IS 'Vault shim: secret column is NOT encrypted. Replace with app-layer encryption at cutover.';


--
-- Name: decrypted_secrets; Type: VIEW; Schema: vault; Owner: -
--

CREATE VIEW vault.decrypted_secrets AS
 SELECT id,
    name,
    description,
    secret,
    secret AS decrypted_secret,
    key_id,
    nonce,
    created_at,
    updated_at
   FROM vault.secrets;


