--
-- Name: TRIGGER trg_ai_calls_cost ON ai_calls; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TRIGGER trg_ai_calls_cost ON public.ai_calls IS 'Must sort before trg_ai_calls_zz_gateway_guard under PostgreSQL alphabetical BEFORE-trigger ordering so cost_source is finalized before gateway clobber checks.';


