--
-- Name: TRIGGER trg_ai_calls_zz_gateway_guard ON ai_calls; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TRIGGER trg_ai_calls_zz_gateway_guard ON public.ai_calls IS 'Runs after trg_ai_calls_cost by alphabetical BEFORE-trigger ordering. Blocks cost_usd changes on already gateway-owned rows that leave cost_source=gateway without a new gateway_generation_id; also fires on gateway_generation_id so W7 refresh statements are visible to the guard.';


